export default [{"id":216,"question":"السلام على المقابر: هل هو خاصٌّ بمَن يدخلها، أم يُسلم عليها مَن مرَّ بجوارها ولو كان بينه وبينها بُعْدٌ؟","title":"ما المشروع في زيارة القبور والسلام عليها؟","answer":"الجواب: مَن مرَّ عليها وسلَّم حصل له أجره بذلك، ومَن وقف عليها ودخل فيها وسلَّم عليهم ودعا لهم فهو أكمل، كان النبيُّ ﷺ يزور القبور ويقف عليهم ويُسلّم عليهم ويقول لأصحابه: إذا زرتم القبور فقولوا: السلام عليكم أهل الدِّيار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المُستقدمين منا والمُستأخرين، وكان يزور البقيع ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، وغدًا مُؤجَّلون، اللهم اغفر لأهل بقيع الغرقد.\nفالسنة أن يزورهم قصدًا، وأن يقف عليهم، ويدعو لهم، ويترحم عليهم، ويتذكر هذا المقام العظيم، يتذكر الموت وما بعده من الأهوال؛ حتى يستفيد من هذه الزيارة، لكن لا يجلس عند القبور للدعاء أو القراءة، ولا يدعُ الموتى ويستغيث بهم، لا، إنما يُسلِّم عليهم، ويدعو لهم، ويتذكر، مثلما قال النبيُّ ﷺ: زوروا القبور، فإنها تُذكركم الآخرة، وفي اللفظ الآخر: تُذكركم الموت.\nأما ما يفعله الجُهَّال من زيارتها لدعائها من دون الله، والاستغاثة بالموتى؛ فهذا شركٌ أكبر، هذا دين الجاهلية.\nومن البدع: أن يزورها ليدعو عندها، يجلس عندها ويدعو، يظن أن الدعاء عندها أنفع، أو يقرأ عندها؛ لأنَّ القراءة عندها أنفع، هذا غلطٌ، هذا من البدع ومن الجهل، فالقراءة في المساجد وفي بيتك أفضل، ولهذا قال النبيُّ ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا متفقٌ عليه، وقال ﷺ: إنَّ الشيطان يفرُّ من البيت الذي تُقرأ فيه سورة البقرة.\nفالمقصود أنَّ القبور لها شأنٌ، والبيوت لها شأنٌ، فالقبور وظيفة الزائر أن يدعو لهم، ويستغفر لهم، ويترحم عليهم، ويتذكر أحوالهم، حتى يتذكر الموت وما بعده، لكن لا يزورهم ليسألهم ويستغيث بهم ويطلب منهم مددًا كما يفعل الجُهَّال مع البدوي، أو مع الرسول ﷺ، أو مع الحسين، أو مع الشيخ عبدالقادر الجيلاني، أو مع أبي حنيفة، أو مع فلان، أو فلان، لا.\nيزور القبور لما قال النبيُّ ﷺ: لأنها تُذكر الآخرة، لأنها تُذكر الموت، والموتى في حاجةٍ إلى أن يُدْعَى لهم، لا أن يُدْعَوا، فهم ضُعفاء، ما يستطيعون أن يقضوا حاجتك، قضاؤها عند الله ، ولكن تدعو لهم، وتترحم عليهم، فهم بحاجةٍ إلى دعوتك، وتستغفر لهم، وتسأل الله لهم النَّجاة والرحمة والعفو، أما حاجاتك فاسألها من الله، اطلبها من ربِّك : في بيتك، في المسجد، في أي مكانٍ تضرع إلى ربك، واسأله قضاء حاجتك: من قضاء دَيْنٍ، من حصول مغفرةٍ، من النَّجاة من النار، من تيسير الزواج، من تيسير الأولاد، من تيسير الرزق، إلى غير ذلك من الشؤون.\nوهكذا السؤال بحقِّ الميت أو بجاهه كله من البدع، لا أصل له، وإنما التَّوسل إلى الله بأسمائه الحسنى وصفاته العُلى في دُعائك، أو بأعمالك الصَّالحة، أو بتوحيدك وإخلاصك.","link":"https://binbaz.org.sa/fatwas/3997/ما-المشروع-في-زيارة-القبور-والسلام-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0223.mp3","categories":["زيارة القبور"]},{"id":899,"question":"هل استقبال القبلة بعد السلام على النبي ﷺ والدّعاء له أصلٌ؟","title":"حكم الدعاء إلى القبلة بعد زيارة النبيﷺ","answer":"الجواب: نعم، هكذا كان السلفُ، كانوا إذا سلَّموا عليه وأرادوا الدّعاء استقبلوا القبلة، ولا يدعون مُستقبلين القبر، بل يدعون الله ويستقبلون القبلة في أي مكانٍ. أما السلام عليه فتستقبله، فقد ثبت عن أبي حنيفة رحمه الله أنه حتى عند السلام يستقبل القبلةَ، ولكن الصواب الذي عليه الجمهور أنه يستقبل القبر عند السلام والدّعاء له عليه الصلاة والسلام، وأما إذا أراد أن يدعو لنفسه بعد ذلك فإنه يستقبل القبلة.","link":"https://binbaz.org.sa/fatwas/20944/حكم-الدعاء-الى-القبلة-بعد-زيارة-النبيﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0740هل استقبال القبلة بعد السلام على النبي صلى الله عليه وسلم والدعاء له أصل؟ابن باز فتاوى المحاضرات.mp3","categories":["زيارة القبور"]},{"id":936,"question":"هل تجوز زيارة النّساء لقبر النبي صلى الله عليه وسلم؟","title":"حكم زيارة النّساء لقبر النبي ﷺ","answer":"الجواب: الزيارة للقبور سنة في حقِّ الرجال، النبي عليه الصلاة والسلام قال: زوروا القبور فإنَّها تُذكركم الآخرة، فهي سنة، زيارة القبور للرجال: زيارة قبر النبي ﷺ وغيره، لا يُشدّ رَحْلٌ، تُزار لكن بدون شدِّ رَحْلٍ: لا تُشدّ الرحال إلا لثلاثة مساجد: المسجد الحرام، ومسجد النبي ﷺ، والمسجد الأقصى للصلاة فيهم والدعاء والقراءة والاعتكاف ونحو ذلك، والحج والعمرة في المسجد الحرام.\nأما القبور فلا تُزار بشدِّ الرَّحْل، لكن بغير شدِّ رحلٍ، كل إنسانٍ يزور القبورَ في بلده، أو أتى بلدًا للتّجارة، أو لزيارة أخٍ له، فزار قبورها وسلَّم عليهم، سنة، فهي تُزار بدون شدِّ الرحل في حقِّ الرجال؛ لأن الرسول أمر بهذا، قال: زوروا القبورَ فإنها تُذكركم الآخرة، فنهى عنها أولًا في أول الإسلام؛ لأنَّ الناس لهم تعلُّق بالقبور، ففُطِمُوا عنها، ونهوا عنها، ثم لما انتشر الإسلامُ وفقه الناسُ الإسلامَ أُبيح لهم زيارة القبور.\nأما النساء: فلم يُبح لهنَّ ذلك، فقد جاء في الأحاديث: لعن زائرات القبور، فلا يجوز للنِّساء زيارة القبور مطلقًا، إنما الزيارة للرجال خاصَّةً.","link":"https://binbaz.org.sa/fatwas/20977/حكم-زيارة-النساء-لقبر-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0773هل يجوز زيارة النساء لقبر النبي صلى الله عليه وسلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["زيارة القبور"]},{"id":1114,"question":"إنني من مدينة جدة، ودائم الذهاب إلى المدينة المنورة، فهل يجب عليَّ السلام على قبر الرسول ﷺ وصحابته كلما ذهبتُ؟","title":"حكم السلام على النبي لمن زار مسجدهﷺ","answer":"الجواب:\nلا، ما يجب، يُستحب السلام، ولا يجب، زيارة القبور سنة، وإذا زرتَ المدينة شُرع لك أن تُسلّم على النبي ﷺ وعلى صاحبيه، وهذا نافلة، مندوب، وليس بواجبٍ. وأنت تُصلي عليه وتُسلّم عليه في كل مكانٍ عليه الصلاة والسلام، ولو في بلادك، ولو في الطريق: \"اللهم صلِّ وسلِّم على رسول الله عليه الصلاة والسلام\"، ولو أنَّك في الجو، في الطائرة، أو في البحر، أو في أي مكان، يقول النبيُّ ﷺ في الحديث الصحيح: وصلُّوا عليَّ، فإنَّ صلاتكم تبلغني حيث كنتم، اللهم صلِّ عليه وسلم، ويقول: إنَّ خير أيامكم يوم الجمعة، فأكثروا عليَّ من الصلاة فيها، فإنَّ صلاتكم معروضة عليَّ، قيل: يا رسول الله، كيف تُعرض عليك وقد أَرَمْتَ؟! يعني: بليت، قال: إنَّ الله حرَّم على الأرض أن تأكل أجساد الأنبياء.\nفأخبر أنَّ صلاتنا تُعرض عليه عليه الصلاة والسلام، فالإكثار من الصلاة والسلام عليه أمرٌ مطلوبٌ: في المدينة، وفي الرياض، وفي مكة، وفي جدة، وفي كل مكانٍ، وفي البحر، وفي الجو، وفي كل مكانٍ، يقول عليه الصلاة والسلام: مَن صلَّى عليَّ واحدةً صلَّى الله عليه بها عشرًا، اللهم صلِّ عليه وسلم.\nوإذا زار المدينة سلَّم عليه وعلى صاحبيه عليه الصلاة والسلام، هذا هو الأفضل والسُّنة، وصلَّى في المسجد ما تيسَّر، ويُستحب أن يزور البقيع ويُسلّم على أهل البقيع، ويُستحب أن يزور قباء، ويُصلي في مسجد قباء أيضًا، ويُستحب أن يزور الشُّهداء ويُسلِّم عليهم، هذا الرجل.\nأما المرأة فلا تزور القبور، ولكن تُصلي في المسجد النبوي، في مسجد قباء، هذا مشروعٌ، أما زيارة القبور فهي خاصَّة بالرجال دون النِّساء.","link":"https://binbaz.org.sa/fatwas/21165/حكم-السلام-على-النبي-لمن-زار-مسجدهﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0961هل يلزم عليَّ كلما زرت مسجد النبي صلى الله عليه وسلم السلام على قبر النبي وأصحابته؟.mp3","categories":["زيارة القبور"]},{"id":2194,"question":"الاستثناء هنا في قوله: وإنا إن شاء الله بكم لاحقون (في دعاء زيارة القبور)؟","title":"معنى \"إن شاء الله بكم لاحقون\" في دعاء القبر","answer":"الجواب:\n\nللتَّبرك.","link":"https://binbaz.org.sa/fatwas/22317/معنى-ان-شاء-الله-بكم-لاحقون-في-دعاء-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد في زيارة القبور.mp3","categories":["زيارة القبور"]},{"id":2197,"question":"بعض الشيعة يأتون عند البقيع ويجلسون، والرجل هنا يتكلم، ويبكون مع النساء والرجال؟","title":"ما المشروع في زيارة القبور ووقتها وآدابها؟","answer":"الجواب:\nالشيعة لا يُقتدى بهم، فالشيعة الرافضة غلاة في الأموات، وغلاة في آل البيت، فلا يُقتدى بهم، والسنة أن تقف وتسلم وأن تمشي، وإذا كان عاجزًا وجلس لا بأس، فالنبي جلس عند قبر أمه ودعا لها حتى مُنِعَ من ذلك.\nس: بعض الذين يزورون القبور –كأن يزور قبر أبيه أو أمه- يُخصص يوم الجمعة، ويأتي إلى القبر، ثم يجلس عنده، وربما لا يدعو ويجلس ساعةً؟\nج: هذا ما له أصل، فتخصيص الجمعة لا أصل له، فزيارة القبور تكون في أي يومٍ -والحمد لله.\nس: بعضهم إذا زار القبر يُصلي على نفس القبر؟\nج: يُصلي الصلاة المعروفة؟\nس: لا، الصلاة على الميت.\nج: لا، هذا ما يجوز.\nس: المشي حافيًا هل يكون عند دخول المقبرة أو بين المقابر؟\nج: بين المقابر فقط، أما قبلها فلا بأس.","link":"https://binbaz.org.sa/fatwas/22320/ما-المشروع-في-زيارة-القبور-ووقتها-وادابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض أحكام زيارة القبور.mp3","categories":["زيارة القبور"]},{"id":2484,"question":"زيارة القبور يوم الجمعة؟","title":"حكم تخصيص يوم الجمعة بزيارة القبور","answer":"الجواب:\nما ورد فيها شيء، في أي وقت، ما فيها خاص، في أي وقت يزور القبور، سنة في الليل أو في النهار، في الجمعة وفي غيرها.","link":"https://binbaz.org.sa/fatwas/22613/حكم-تخصيص-يوم-الجمعة-بزيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تخصيص يوم الجمعة لزيارة القبور.mp3","categories":["زيارة القبور"]},{"id":4317,"question":"أخذ النساء والسلام من الخلف على النبي ﷺ وكذلك الأطفال؟","title":"حكم سلام النساء والأطفال على النبي ﷺ","answer":"الجواب: الرجال السنة أن يسلم عليه أمامه أمام وجهه عليه الصلاة والسلام ثم يتحول قليلًا إلى الصدّيق ثم قليلًا إلى عمر رضي الله عنهما، هذه السنة، أما النساء لا ما ينبغي السلام، والأطفال اللي يعرف يسلم يسلم مع الرجال، أما النساء السنة ألا يسلمن، وإلا الدولة تتساهل معهم؛ لأن بعض الأئمة يجيز زيارة النساء للقبور ولهذا تساهلت الدولة معهم في الموضوع، ولكن الأرجح أن النساء لا يزرن لا قبره ولا قبر غيره عليه الصلاة والسلام؛ لحديث أن الرسول لعن زائرات القبور، هذا عام، أما قوله: \"زوروا القبور فإنها تذكركم الآخرة\" هذا يختص بالرجال، خطاب للرجال، هذا هو الأرجح.","link":"https://binbaz.org.sa/fatwas/24591/حكم-سلام-النساء-والاطفال-على-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أخذ النساء والأطفال للسلام على النبي من خلف المسجد.mp3","categories":["زيارة القبور"]},{"id":4826,"question":"أحد الإخوان يقول: أريد أن أزور أمي في قبرها، فكيف أُسلم عليها؟ هل أقول: السلام عليك يا أمي، أو ما أشبه ذلك؟","title":"ما كيفية السلام على الميت في قبره؟","answer":"السلام عليكم يا أمي، السلام عليكم ورحمة الله وبركاته، غفر الله لك، ورحمك، وأسكنك الجنة، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/25237/ما-كيفية-السلام-على-الميت-في-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية السلام على الميت في قبره.mp3","categories":["زيارة القبور"]},{"id":5007,"question":"قوله ﷺ: كنتُ نهيتُكم؟","title":"هل كانت زيارة القبور ممنوعة ثم رُخِّص فيها؟","answer":"الجواب: كان أولًا نُهي عن زيارة القبور، ثم نُسخ النهي، فإنهم لما كانوا حديثي عهدٍ بالإسلام نُهوا عن الزيارة؛ لئلا يقع شيءٌ من الشرك، فلما استقرَّ الإسلامُ في قلوبهم وعرفوا الإسلام رخّص لهم في الزيارة؛ لأنها مصلحةٌ بلا مضرَّةٍ، ففيها ترقيق القلوب، وتذكيرٌ بالموت والآخرة.","link":"https://binbaz.org.sa/fatwas/28809/هل-كانت-زيارة-القبور-ممنوعة-ثم-رخص-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كانت زيارة القبورة ممنوعة ثم رخص فيها؟.mp3","categories":["زيارة القبور"]},{"id":5008,"question":"من أين أُخِذَ نهي النّساء عن زيارة القبور؟","title":"ما دليل نهي النّساء عن زيارة القبور؟","answer":"الجواب: من أحاديث أخرى: ففي حديث ابن عباسٍ قال: \"\"لعن رسولُ الله ﷺ زائرات القبور، والمتخذين عليها المساجد والسُّرج\"\"، وحديث أبي هريرة، وحديث حسان بن ثابت، كلها فيها النهي عن زيارة القبور للنساء.","link":"https://binbaz.org.sa/fatwas/28810/ما-دليل-نهي-النساء-عن-زيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما دليل نهي النساء عن زيارة القبور؟.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":5009,"question":"إذا مرَّ أمام المقبرة هل عليه أن يسلم؟","title":"هل يشرع دعاء زيارة القبور للمارِّ بها؟","answer":"الجواب: الأفضل، وليس هو بلازم، فهي سنة، مستحبّ، فلو وقف على الجدار وسلَّم فهذا طيّب.","link":"https://binbaz.org.sa/fatwas/28811/هل-يشرع-دعاء-زيارة-القبور-للمار-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشرع دعاء زيارة القبور للمار بها؟.mp3","categories":["زيارة القبور","الأدعية والأذكار"]},{"id":5024,"question":"قبور الكفّار هل يجوز إهانتها؟","title":"هل يجوز إهانة قبور الكفار؟","answer":"الجواب: لا، تُزار بس، بدون إهانة؛ لذِكْر الآخرة، إذا زارها من أجل ذِكْر الآخرة فقط.","link":"https://binbaz.org.sa/fatwas/28930/هل-يجوز-اهانة-قبور-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز إهانة قبور الكفار؟.mp3","categories":["زيارة القبور"]},{"id":5027,"question":"تخصيص بعض الناس زيارة القبور بيوم الجمعة؟","title":"ما حكم تخصيص زيارة القبور بيوم الجمعة","answer":"الجواب: لا، ما لها أصل، ما لها وقت مخصوص، تُزار في كل وقت، في الليل والنهار، ما لها وقت معين.","link":"https://binbaz.org.sa/fatwas/28932/ما-حكم-تخصيص-زيارة-القبور-بيوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم تخصيص زيارة القبور بيوم الجمعة.mp3","categories":["زيارة القبور"]},{"id":5795,"question":"عندما يزور الإنسان القبر هل يستقبل القبلة؟","title":"هل استقبال القبلة شرط عند زيارة القبر؟","answer":"الجواب: الأفضل أن يكون أمام وجهه إذا تيسر، ولا في حاجة لاستقبال القبلة، لكن الأفضل إذا تيسر يقف أمام وجهه كما يزوره في حياته، ويقابله في حياته، هذا أحسن إذا تيسر، وإلا في أي جهة سلم كفى، ولو بقى على القبور يسلم على الجميع ومشى كفى. السؤال: ولو بغيت أدعي له؟ الجواب: تدعي له وأنت ماشي.","link":"https://binbaz.org.sa/fatwas/1126/هل-استقبال-القبلة-شرط-عند-زيارة-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_132.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":5797,"question":"عندما يزور الإنسان القبر هل يستقبل القبلة؟","title":"هل استقبال القبلة شرط عند زيارة القبر؟","answer":"الجواب: الأفضل أن يكون أمام وجهه إذا تيسر، ولا في حاجة لاستقبال القبلة، لكن الأفضل إذا تيسر يقف أمام وجهه كما يزوره في حياته، ويقابله في حياته، هذا أحسن إذا تيسر، وإلا في أي جهة سلم كفى، ولو بقى على القبور يسلم على الجميع ومشى كفى. السؤال: ولو بغيت أدعي له؟ الجواب: تدعي له وأنت ماشي.","link":"https://binbaz.org.sa/fatwas/1126/هل-استقبال-القبلة-شرط-عند-زيارة-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_132.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":5800,"question":"كيف يجمع بين ما ورد أن عائشة قد زارت القبور، وبين الأحاديث التي تحرم ذلك؟","title":"الجمع بين زيارة عائشة القبور وبين النهي عن زيارتها","answer":"الجواب: عائشة ما كانت تزور القبور، إنما زارت قبر أخيها؛ لأنه مات وهو غائب عنها قرب مكة، فقالت: \"لو شهدتك ما زرتك\" يعني: لو شهدت موتك ما زرتك، فهذا يدل على أن زيارة القبور للنساء ما هي بمشروعة؛ ولهذا قالت: لو شهدتك ما زرتك. فلو كانت الزيارة مشروعة للنساء كانت زارته مطلقًا، ولو شهدته، كما ينبغي أن يزور النساء البقيع، والشهداء؛ فلم يكن النساء في عهد النبي ﷺ ولا في عهد الخلفاء يزرن البقيع، ولا قبور الشهداء، فعلم أنه استقر عندهم أن زيارة النساء للقبور غير مشروعة. والحكمة -والله أعلم- في ذلك أن النساء مثل ما قال مشايخ الندوة قليلات الصبر، ضعيفات البصيرة، فلو زرن القبور لربما وقع منهن من الجزع، والنياحة، والتكشف، والتبرج ما لا يحمد عقباه، وهن فتنة، فمن -رحمة الله- أن منعهن من اتباع الجنائز، ومن زيارة القبور؛ لأنهن لو اتبعن الجنائز لربما حصل فتنة بين الماشي في الجنائز؛ لأنه قل امرأة أن تعتني بالستر، والحجاب، والتحفظ، وهكذا عند زيارة القبور، فيقع فتن في اختلاطهن بالرجال حين الزيارة، وحين تشييع الجنازة. فالحكمة -والله أعلم- مترتبة من كونهن فتنة، قليلات الصبر، قليلات النظر في العواقب، وربما يحن، وينحن على الميت؛ فيضره ذلك، وربما أبدين شيئًا من الفتنة من شعورهن، أو أجسادهن، فيفتن الرجال الأحياء، ويؤذين الأموات بنياحتهن، وقلة صبرهن، وربك حكيم عليم، جل وعلا.","link":"https://binbaz.org.sa/fatwas/1129/الجمع-بين-زيارة-عاىشة-القبور-وبين-النهي-عن-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_135.mp3","categories":["زيارة القبور","البدع والمحدثات"]},{"id":5807,"question":".............؟","title":"حكم زيارة النساء للمقابر","answer":"الجواب: عائشة -رضي الله عنها- زارت قبر أخيها، وقالت: \"ولو شهدتك ما زرتك\" لأنها كانت غائبة، قال العلماء: هذا يدل على أنها لو كانت الزيارة مشروعة لما قالت هذا الكلام، لو شهدتك ما زرتك! مرت عليه في طريقها إلى الحج؛ لأنه مات قرب مكة، فنقل إلى مكة، ودفن هناك، فهذا اجتهاد منها، والنبي ﷺ لعن الزائرات، جاء في حديث أبي هريرة، وحسان بن ثابت، وابن عباس أن رسول الله ﷺ لعن زائرات القبور، وفي لفظ: زوارات القبور، وأخذ العلماء من ذلك منع زيارة القبور، وأنهن لا يزرنها؛ لأنهن فتنة، وصبرهن قليل، فمن -رحمة الله- أن منعن من ذلك.  السؤال: في وقت مخصص للزيارة؟ الشيخ: لا ما في وقت مخصص للرجال يزورون في الليل، والنهار ما في وقت مخصص.","link":"https://binbaz.org.sa/fatwas/1149/حكم-زيارة-النساء-للمقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_152.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":5823,"question":".............؟","title":"حكم زيارة النساء للمقابر","answer":"الجواب: عائشة -رضي الله عنها- زارت قبر أخيها، وقالت: \"ولو شهدتك ما زرتك\" لأنها كانت غائبة، قال العلماء: هذا يدل على أنها لو كانت الزيارة مشروعة لما قالت هذا الكلام، لو شهدتك ما زرتك! مرت عليه في طريقها إلى الحج؛ لأنه مات قرب مكة، فنقل إلى مكة، ودفن هناك، فهذا اجتهاد منها، والنبي ﷺ لعن الزائرات، جاء في حديث أبي هريرة، وحسان بن ثابت، وابن عباس أن رسول الله ﷺ لعن زائرات القبور، وفي لفظ: زوارات القبور، وأخذ العلماء من ذلك منع زيارة القبور، وأنهن لا يزرنها؛ لأنهن فتنة، وصبرهن قليل، فمن -رحمة الله- أن منعن من ذلك.  السؤال: في وقت مخصص للزيارة؟ الشيخ: لا ما في وقت مخصص للرجال يزورون في الليل، والنهار ما في وقت مخصص.","link":"https://binbaz.org.sa/fatwas/1149/حكم-زيارة-النساء-للمقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_152.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":6632,"question":"ما هي أوقات زيارة القبور؟ وما هو الدعاء الذي يدعى للميت في المقبرة؟ وما حكم زيارة أيام الأعياد؟","title":"هل لزيارة القبور وقت معين؟ وحكم الزيارة أيام الأعياد","answer":"الجواب: القبور تسن زيارتها، وليس لها حد محدود، لا في الليل، ولا في النهار، النبي ﷺ زارها ليلًا، وزارها نهارًا -عليه الصلاة والسلام- فليس لها وقت محدود يشرع زيارتها، متى تيسر للعبد زيارتها، فليس لها يوم محدود، لا جمعة، ولا غيرها، متى تيسرت الزيارة، وفرغ للزيارة، أو وفقه الله للزيارة في أي وقت، في يوم العيد، أو في يوم الجمعة، أو في السبت، أو في الليل، أو في النهار. أما أن يخص لها وقتًا يوم العيد راتبًا، أو يوم الجمعة راتبًا، هذا لا أصل له، لكن يزورها متى تيسر، يتذكر بها الآخرة، والموت، ويستعد للآخرة، النبي  قال: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه، فيقول -عليه الصلاة والسلام- لهم: إذا زرتم القبور؛ قولوا السلام عليكم أهل الديار من المؤمنين، والمسلمين، وإنا  -إن شاء الله- بكم لاحقون، يرحم الله المستقدمين منا، والمستأخرين، نسأل الله لنا، ولكم العافية وكان يزور البقيع ﷺ ويدعو لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، غدًا مؤجلون، اللهم اغفر لأهل بقيع الغرقد هذه زيارته -عليه الصلاة والسلام-. والمقصود منها ذكر الآخرة، ذكر الموت، والإحسان للموتى، والدعاء لهم، والترحم عليهم، هذا المقصود حتى يستعد للآخرة، وحتى يستعد للموت قبل نزوله. السؤال: في بعض البلاد يزورنها ليلة العيد إذا أعلن فجأة رمضان، ليلة العيد، أو صباح العيد، زيارة جماعية؟ الجواب: لا نعلم لهذا أصلًا، هذا بدعة، هذا ليس له أصل، كونه يخص ليلة العيد، أو ليلة من الليالي، جماعيًا يقصدونها، لا أصل له، ولا ينبغي له، إذا أراد هذا يكون من البدعة، إذا أراد هذا خاص، وأنه قربة، وهذا ظاهر عمله. السؤال: والميت إذا وضع على عربة مدفع هل هذا جائز؟ الجواب: لماذا؟ السؤال: في بعض الدول الإسلامية يضعونها على عربة مدفع، ويدقون المزيكا يحملون...؟ الجواب: هذا ما له أصل، هذا ما له أصل، أما كونه يحمل في السيارة حتى لا يتعبوا ما في بأس.  السؤال: لا هم يحملونه فوق عربة مدفع؟ الجواب: أما على طريقة.. مالها أصل، إذا كان معه موسيقى؛ صار أقبح. السؤال: وستة خيول سود؟ الجواب: هذا غلط، هذا غلط.","link":"https://binbaz.org.sa/fatwas/2477/هل-لزيارة-القبور-وقت-معين-وحكم-الزيارة-ايام-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1004.mp3","categories":["زيارة القبور","حرمة الأموات","البدع والمحدثات"]},{"id":6647,"question":"ما هي أوقات زيارة القبور؟ وما هو الدعاء الذي يدعى للميت في المقبرة؟ وما حكم زيارة أيام الأعياد؟","title":"هل لزيارة القبور وقت معين؟ وحكم الزيارة أيام الأعياد","answer":"الجواب: القبور تسن زيارتها، وليس لها حد محدود، لا في الليل، ولا في النهار، النبي ﷺ زارها ليلًا، وزارها نهارًا -عليه الصلاة والسلام- فليس لها وقت محدود يشرع زيارتها، متى تيسر للعبد زيارتها، فليس لها يوم محدود، لا جمعة، ولا غيرها، متى تيسرت الزيارة، وفرغ للزيارة، أو وفقه الله للزيارة في أي وقت، في يوم العيد، أو في يوم الجمعة، أو في السبت، أو في الليل، أو في النهار. أما أن يخص لها وقتًا يوم العيد راتبًا، أو يوم الجمعة راتبًا، هذا لا أصل له، لكن يزورها متى تيسر، يتذكر بها الآخرة، والموت، ويستعد للآخرة، النبي  قال: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه، فيقول -عليه الصلاة والسلام- لهم: إذا زرتم القبور؛ قولوا السلام عليكم أهل الديار من المؤمنين، والمسلمين، وإنا  -إن شاء الله- بكم لاحقون، يرحم الله المستقدمين منا، والمستأخرين، نسأل الله لنا، ولكم العافية وكان يزور البقيع ﷺ ويدعو لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، غدًا مؤجلون، اللهم اغفر لأهل بقيع الغرقد هذه زيارته -عليه الصلاة والسلام-. والمقصود منها ذكر الآخرة، ذكر الموت، والإحسان للموتى، والدعاء لهم، والترحم عليهم، هذا المقصود حتى يستعد للآخرة، وحتى يستعد للموت قبل نزوله. السؤال: في بعض البلاد يزورنها ليلة العيد إذا أعلن فجأة رمضان، ليلة العيد، أو صباح العيد، زيارة جماعية؟ الجواب: لا نعلم لهذا أصلًا، هذا بدعة، هذا ليس له أصل، كونه يخص ليلة العيد، أو ليلة من الليالي، جماعيًا يقصدونها، لا أصل له، ولا ينبغي له، إذا أراد هذا يكون من البدعة، إذا أراد هذا خاص، وأنه قربة، وهذا ظاهر عمله. السؤال: والميت إذا وضع على عربة مدفع هل هذا جائز؟ الجواب: لماذا؟ السؤال: في بعض الدول الإسلامية يضعونها على عربة مدفع، ويدقون المزيكا يحملون...؟ الجواب: هذا ما له أصل، هذا ما له أصل، أما كونه يحمل في السيارة حتى لا يتعبوا ما في بأس.  السؤال: لا هم يحملونه فوق عربة مدفع؟ الجواب: أما على طريقة.. مالها أصل، إذا كان معه موسيقى؛ صار أقبح. السؤال: وستة خيول سود؟ الجواب: هذا غلط، هذا غلط.","link":"https://binbaz.org.sa/fatwas/2477/هل-لزيارة-القبور-وقت-معين-وحكم-الزيارة-ايام-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1004.mp3","categories":["زيارة القبور","حرمة الأموات","البدع والمحدثات"]},{"id":6877,"question":"قرأت لكم النهي عن زيارة المرأة لقبر النبي ﷺ لاعتبار عموم النهي، وقرأت في الروض المربع في كتاب الجنائز ما نصه: إلا للنساء فتكره لهن زيارتها، يعني القبور غير قبره ﷺ نرجو تعليق سماحتكم، والدعاء لنا..؟","title":"حكم زيارة المرأة لقبر النبي صلى الله عليه وسلم","answer":"الجواب: هذا الاستثناء لا وجه له، قول بعض الحنابلة، وغيرهم إلا قبر النبي ﷺ وقبر صاحبيه، فإن النساء يزرنه هذا لا أصل له، الرسول ﷺ عمم لعن زائرات القبور مطلقًا، فلا يزرن قبر النبي، ولا غير قبر النبي، ولكن يصلين على النبي ﷺ في كل مكان. النبي  قال: لا تجعلوا قبري عيدًا، وصلوا علي، فإن صلاتكم تبلغني حيث كنتم فيصلين عليه ﷺ في بيوتهن، وفي الطريق، وفي مسجده ﷺ وفي كل مكان، ولا حاجة إلى زيارة القبر، ولا القبور الأخرى، يدعى للأموات، ويترحم عليهم من النساء، ولا حاجة إلى الزيارة. أما الرجل فيزور، ويدعو، ويصلي على النبي في كل مكان -عليه الصلاة والسلام- يصلي عليه في بيته، وفي الطريق، وفي المسجد، وفي السفر، وفي الإقامة، وفي الطائرة، وفي السيارة، وفي القطار، وفي كل مكان، يكثر من الصلاة عليه ﷺ: إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] هذا يعم الرجال، والنساء جميعًا في كل مكان.  وقال -عليه الصلاة والسلام-: من صل علي واحدة؛ صلى الله عليه بها عشرًا فأنت تكثر الصلاة على النبي ﷺ في كل مكان، وهكذا النساء يكثرن من الصلاة والسلام على الرسول ﷺ في كل مكان، كما يكثر الجميع من ذكر الله، يقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر في كل مكان، هكذا الصلاة على النبي ﷺ.  هذه أعمال صالحة يقولها المؤمن، ويأتي بها في مسجده، في طريقه، في بيته، في الطائرة، في الجو، في السيارة، في القطار، في الباخرة، في كل مكان، له عمله، وأجر عظيم في ذلك لتسبيحه، وتهليله، وتحميده، وتكبيره، واستغفاره، وصلاته، وسلامه على رسوله -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/2762/حكم-زيارة-المراة-لقبر-النبي-صلى-الله-عليه-وسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1254.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":7941,"question":"يقول: في حضرموت يذهب الناس في وقت محدود من كل سنة إلى زيارة أحد القبور يقولون: إنه قبر النبي هود الكائن في شعب هود ، وهناك تتم الصلاة وتتم الزيارة والقراءة والبيع والشراء فما حقيقة ذلك، وهل قبر النبي هود هناك أم لا؟","title":"حكم زيارة القبور والطواف حولها ودعاء أصحابها والبناء عليها","answer":"الجواب: لا شك أن هود عليه الصلاة والسلام كان في الأحقاف وكان منزلهم هناك بعثه الله إلى قومه هناك، ولكن لا يعلم قبره ولا يدرى عنه، وليس هناك ما يدل على وجوده هناك، فالذين يقصدون قبراً هناك ليس معهم حجة على أنه قبر هود ولا يحفظ قبر معلوم للأنبياء سوى قبر نبينا محمد ﷺ فهو المحفوظ في المدينة، وهكذا قبر إبراهيم في المغارة في الشام في محله المعروف هناك من دون أن يعلم عينه لكنه موجود في المغارة المعروفة هناك في الخليل، وأما بقية الأنبياء فلا تعلم قبورهم لا هود ولا صالح ولا نوح ولا غيرهم كلهم لا تعلم قبورهم، فمن زعم أن قبر هود في بقعة معينة هناك وأشار إليه بأنه هذا المحل المعين فليس معه حجة وليس معه دليل، فقبور الأنبياء لا تعرف ما عدا قبر نبينا ﷺ وقبر إبراهيم عليه الصلاة والسلام.\nثم لو فرضنا أنه صحيح وأنه قبر هود فإنه لا يجوز شد الرحال إليه للسلام عليه أو الصلاة عنده أو غير ذلك، لكن لو مر إنسان به وهو يعلم أنه قبره وسلم عليه فلا بأس، كما يسلم على نبينا محمد عليه الصلاة والسلام، أما أن يزار بشد الرحال فلا، قال النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام ومسجدي هذا، والمسجد الأقصى.\nفلا يشد الرحل لقبر أي أحد لا قبر هود ولا غيره، ثم لو فرض أنه مر عليه وزاره فليس له أن يصلي عند القبر، الصلاة لا تجوز عند القبور، الرسول ﷺ نهى عن ذلك قال: ألا وإن من كان قبلكم كانوا يتخذونن قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك، فالصلاة عند القبر اتخاذ له مسجد، فلا يجوز الصلاة عند القبور ولا اتخاذها مساجد.\nلو فرضنا أنه علم أنه قبر هود أو غيره فلا يجوز للمسلمين أن يشدوا الرحال من أجل زيارة القبور لا قبر هود ولا غيره، وليس للمسلمين أيضاً أن يصلوا عند القبور، ولا أن يتخذوا عليها مساجد؛ لأن الرسول زجر عن ذلك عليه الصلاة والسلام فقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يحذر ما صنعوا، وقال أيضاً عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك.\nفصرح ﷺ أنه ينهى عن اتخاذ القبور مساجد، والصلاة عندها اتخاذ لها مساجد، فلا يجوز لأي مسلم أن يفعل ذلك، فلا يشد الرحل إلى القبر -أي قبر كان- ولا يصلي عنده، أما إذا مر عليه أو صار في البلد وزاره للسلام على القبور فهذا سنة، النبي عليه السلام قال: زوروا القبور فإنها تذكركم الآخرة، لكن من دون شد رحل، ومن دون أن تتخذ مساجد ويصلى عندها أو تجعل محل قراءة والدعاء لا، يزورها ويسلم على المقبورين ويدعو لهم وينصرف.\nكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي لفظ: يرحم الله المستقدمين منا والمستأخرين، فهذه السنة أن تزار القبور من دون شد رحل، يسلم عليهم ويدعى لهم بالرحمة والمغفرة، ولك معهم، وفي زيارة القبور ذكرى وعبرة، فإن الزائر يتذكر الموت وما بعد الموت ويعتبر ويدعوه هذا إلى إعداد العدة، والتأهب إلى الآخرة، أما اتخاذها مساجد أو اتخاذها محلاً للدعاء والقراءة فلا، هذا لا يجوز وليست محلاً للدعاء ولا للقراءة ولا الصلاة، ولكن يسلم عليهم ويدعو لهم بعرض السلام، ويكفي ذلك كما علمنا الرسول ﷺ وبين لنا وحذرنا من خلاف ذلك، فشد الرحال للقبور منكر ولا يجوز، وهكذا الصلاة عندها واتخاذها مساجد والبناء عليها، واتخاذ القباب عليها كل هذا منكر.\nولا ينبغي لك أيها السائل ولا لغيرك أن يغتر بالناس، فإن أكثر الناس اليوم ليس عندهم بصيرة وإنما تحكمهم العادات وما ورثوه عن الآباء والأجداد، فاتخاذ المساجد على القبور اليوم في بعض الدول الإسلامية واتخاذ القباب عليها كله منكر كله من وسائل الشرك، النبي ﷺ نهى عن هذا قال: لعن اللهه اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، يحذرنا من أعمالهم.\nوكذلك نهى عن تجصيص القبور والقعود عليها والبناء عليها، فلا يجوز أن تجصص ولا أن يبنى عليها قبة ولا غيرها، ولا يتخذ عليها مسجد؛ لأن هذا كله مصادم لما جاء عنه عليه الصلاة والسلام؛ ولأنه أيضاً وسيلة من وسائل الشرك والغلو في القبور.\nفالواجب على رؤساء الدول الإسلامية الواجب عليهم أن يزيلوا ما على القبور من أبنية من قباب ومساجد وأن تكون القبور بارزة ليس عليها قبة وليس عليها مسجد، هذا هو الواجب في جميع الدول الإسلامية، الواجب عليهم جميعاً أن يبرزوا القبور وأن يزيلوا ما عليها من مساجد وقباب وأبنية طاعة للرسول صلى الله عليه وسلم، وامتثالاً لأمره، وعملاً بشرعه عليه الصلاة والسلام.\nوأيضاً في ذلك سد ذرائع الشرك وحسم موادها؛ لأن الناس إذا رأوا قبراً مشيداً معظماً بالقباب والبناء والفرش غلت فيه العامة وظنت أنه ينفع ويضر، وأنه يستجيب الداعي، وأنه يشفي المريض، وأنه يتوسط بينه وبين الله؛ فيقع الشرك بالله نعوذ بالله كما قد وقع لعباد القبور في الزمن الأول، فإنهم عظموا القبور وزعموا أن أهلها شفعاء عند الله، ودعوهم واستغاثوا بهم، وهذا هو الشرك الأكبر نسأل الله العافية.\nوهذا واقع اليوم في كثير من البلاد الإسلامية، واقع فيها هذا الغلو في القبور كما يقع في مصر عند قبر البدوي والحسين وغيرهما، وكما قد يقع في الشام عند قبر ابن عربي وغيره، وكما قد يقع في العراق عند قبر موسى الكاظم وأبي حنيفة وغيرهما، وكما قد يقع من بعض الجهال عند قبر النبي في المدينة عليه الصلاة والسلام، بعض الجهال من الحجاج والزوار، قد يقع منهم الشرك عند قبر النبي ﷺ يقول: يا رسول الله! اشف مريضي.. انصرني.. المدد المدد.. اشفع لي، وهذا لا يجوز، لا مع النبي ولا مع غيره من الأموات عليه الصلاة والسلام، وإنما هذا في حياته، في حياته يقال: اشفع لي يا رسول الله، يعني: ادعوا لنا، وهكذا يوم القيامة إذا قام الناس من قبورهم يأتيه المؤمنون ويسألونه أن يشفع لهم إلى الله، حتى يحكم بينهم وحتى يدخلوا الجنة، أما بعد الموت وقبل البعث في حال البرزح فلا، لا يطلب منه الشفاعة، ولا يجوز أن يطلب منه المدد ولا غوث ولا نصر على الأعداء؛ لأن هذا بيد الله سبحانه وتعالى، ليس بيد الأنبياء ولا غيرهم، بل النصر والشفاء للمرضى والغوث والمدد كله بيد الله سبحانه وتعالى.\nوهكذا قد يقع من بعض الجهلة عند قبر خديجة في المحلاة في مكة المكرمة إلا إذا لوحظوا ووجهوا وبين لهم ما يجب عليهم، فأنت -أيها السائل- ينبغي لك أن تحذر هذه المسائل وأن تكون على بينة، وأن تعلم أن القبور -لا قبر هود ولا غيره- لا يجوز أن تتخذ معابد مصلى مساجد، لا، ولا أن تدعى مع الله، ولا أن يستغاث بأهلها، ولا يطاف بقبورهم، ولا أن يبنى عليها قبة، ولا أن تفرش، ولا أن تطيب، كل هذا لا يجوز؛ لأنه من وسائل الشرك، ودعاء الميت وطلب الغوث منه والمدد وشفاء المريض هذا كله شرك بالله عز وجل. نعم.","link":"https://binbaz.org.sa/fatwas/5467/حكم-زيارة-القبور-والطواف-حولها-ودعاء-اصحابها-والبناء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_067/06705.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":7970,"question":"هذه رسالة وردتنا من جمهورية مصر العربية محمود حامد يقول في رسالته: السلام عليكم ورحمة الله وبركاته.وبعد: أصحاب الفضيلة! لقد استمعنا إلى برنامجكم في السعودية كثيراً، والبرنامج هو نور على الدرب، وحسسنا على تركيزكم الكبير على زيارة القبور والتبرك بما فيها من أهل الخير، وهم بلا شك فيهم الخير الكثير وخاصة أنهم يعيشون في كنف الله سبحانه وتعالى، وهم أقرب إليه من غيرهم؛ لأنهم في حضرته، لكن كثرة كلامكم عن عدم جدواهم جعلتنا نضع عدة أسئلة عندما نريد أن نقوم بزيارة هؤلاء، نرجو منكم أن تصدقونا القول وفقنا الله وإياكم؛ لأننا نريد إذا لم نكن على الصواب أن نتجنب ما نحن عليه؟","title":"زيارة القبور بين المشروع والممنوع","answer":"الجواب: السائل مشكور على طلبه الحق، وهذا هو الذي ينبغي لكل مؤمن أن يسأل عما أشكل عليه وألا يبقى على الجهل؛ لأن الله سبحانه يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، والموتى في القبور أقسام:\nمنهم من هو قريب من الله وفي كنف الله ومرحوم، وهم أهل التقوى والإيمان.\nومنهم المعذب المغضوب عليه من أهل الكفر والفسق، فليسوا على حد سواء، المؤمن الطيب الذي مات على طاعة الله ورسوله على خير عظيم، وموعود بالجنة، وقبره روضة من رياض الجنة، أما الذي مات على الكفر بالله كالذين يدعون الأموات ويستغيثون بالأموات، ويطلبون منهم المدد، هذا كفر وضلال، هذا على خطر عظيم وهو متوعد بالنار والعذاب الأليم لكفره بالله وشركه بالله.\nوهكذا من مات على المعاصي غير تائب كالذي يموت على الزنا وعقوق الوالدين، أو على أكل الربا، أو على شهادة الزور، أو على شرب الخمور، وسرقة أموال الناس ونحو ذلك، هؤلاء على خطر عظيم من دخول النار، وعلى خطر أن تكون قبورهم حفرة من حفر النار نعوذ بالله، فليس الموتى على حد سواء.\nفينبغي أن تعلم -أيها السائل- أن الأموات أقسام:\nمنهم المرضي عنه المستقيم الذي مات على تقوى وإيمان، هذا له الجنة والكرامة، وقبره روضة من رياض الجنة.\nومنهم من مات على الكفر والضلال كالذي يستهزئ بالدين ويسب الدين، أو يدع الصلاة، أو يسأل الموتى ويستغيث بهم وينذر لهم ويطلبهم المدد وما أشبه ذلك هذا من الكفر بالله عز وجل، والكفار متوعدون بالنار إذا ماتوا على كفرهم.\nومنهم من مات على المعاصي، هو مسلم لكن مات على المعاصي، مات على شرب الخمر، مات على الربا، مات على الزنا، مات على السرقة، مات عاقاً لوالديه، هذا على خطر من دخول النار، وإن كان لا يخلد في النار إذا دخلها لكنه على خطر، وعلى خطر من العذاب في قبره بسبب معاصيه، فينبغي لك أن تحذر وأن تكون على بينة.\nأما زيارة القبور فهي أقسام: إن كانوا مسلمين يزارون للدعاء لهم والترحم عليهم والاستغفار لهم، وتذكر الآخرة والزهد في الدنيا، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين وكان يقول: اللهم اغفر لأهل بقيع الغرقد، فأنت تسأل الله لهم المغفرة والرحمة والعافية إذا زرتهم.\nأما دعاؤهم تقول: يا سيدي فلان! اقض حاجتي، اشف مريضي، المدد المدد، هذا شرك بالله، هذا لا يجوز، هذا من عمل الجاهلية من عمل أبي جهل وأشباهه من كفار الجاهلية كفار قريش وأشباههم، الموتى لا يطلبون شيء لا يقال لهم: المدد، ولا أغيثونا، ولا انصرونا، ولا اشفوا مرضانا، لا. هذا يطلب من الله سبحانه وتعالى لا منهم، فهو القادر على كل شيء جل وعلا، ولا يقال: اشفعوا لنا، لا يطلب منهم هذا، وإنما يستغفر لهم.. يدعى لهم بالرحمة والمغفرة، فينبغي أن تعلم ذلك وأن تكون على بينة.\nأما الكفار لا يزارون، مثل النصارى ، قبور اليهود ، قبور النصارى ، قبور المشركين الذين يعبدون غير الله، يستغيثون بالأموات وينذرون لهم، هؤلاء لا تزار قبورهم ومن زارها لقصد الاعتبار فلا بأس، إذا زارها للاعتبار، يعني: ليعتبر ويتذكر الآخرة لكن لا يدعى لهم، لا يترحم عليهم، فقد زار النبي صلى الله عليه وسلم قبر أمه وهي ماتت على الجاهلية، زار قبر أمه واستأذن ربه أن يستغفر لها فلم يأذن له أن يستغفر لها عليه الصلاة والسلام، لكن زارها للاعتبار والذكرى فقط.\nفإذا زرت القبور قبور الكفار من النصارى وغيرهم للذكرى والاعتبار والزهد في الدنيا والرغبة في الآخرة فلا بأس، لكن لا تسلم عليهم ولا تدع لهم، أما المسلمون فتزار قبورهم، ويدعى لهم بالمغفرة والرحمة، ولا يدعون مع الله ولا يستغاث بهم ولا ينذر لهم، ولا يسألون الشفاعة، ولا الغوث، ولا النصر ولا المدد كل هذا لا يجوز، كل هذا من الشرك الذي حرمه الله، وهو من عمل أهل الجاهلية.\nفينبغي لك -أيها السائل- أن تحفظ هذا، وأن تبلغه من وراءك من الإخوان، ينبغي أن تحفظ هذا جيداً، وأن تبلغه من حولك من جيرانك وأصحابك وجلسائك حتى تكونوا على بينة.. على بصيرة؛ لأن الله يقول: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، سبحانه وتعالى، فالموتى لا يدعون، وهكذا الملائكة، هكذا الأنبياء بعد موتهم.. هكذا الكواكب.. هكذا الأشجار والأحجار.. هكذا الأصنام، كلها لا تدعى من دون الله، ولا يستغاث بها، ولا ينذر لها، ولا يتمسح بها، أما النبي الحي والصالح الحي الذي يسمع كلامك لا بأس أن تقول له: اشفع لي، ادع الله لي كما كان الصحابة في حياة النبي ﷺ يدعونه، يقولون له: اشفع لنا يا رسول الله، في حياته ﷺ قبل أن يموت كان الصحابة يطلبون منه الدعاء والشفاعة عليه الصلاة والسلام، لا بأس، أما بعد الموت فلا، هكذا إخوانك، مثل رجل صالح من إخوانك صاحب صلاة وصاحب عبادة تقول: ادع الله لي يا أخي، وهو يسمع كلامك، حي، يطلب من الله لك.. أن الله يغفر لك.. أن الله يصلح حالك، يصلح ذريتك، لا بأس.\nفالمقصود: أن الحي الحاضر القادر لا بأس أن تطلبه ما يستطيعه كأن يدعو لك، كأن يقرضك شيئاً من ماله لحاجتك، كأن تعامله في شيء، لا بأس بهذه الأمور التي بينك وبين الحي الحاضر القادر، أما الموتى لا، الموتى لا يطلبون شيء، ولا يسألون، ولا يستغاث بهم، وهكذا الجمادات كالجبال والأصنام والكواكب وأشباه ذلك لا تسأل ولا يستغاث بها، وهكذا الغائبون من الجن والملائكة لا يسألون ولا يستغاث بهم، كل هذا من الشرك بالله عز وجل، لا يجوز فعله مع الملائكة ولا مع الجن ولا مع الأموات ولا مع الجمادات، ولكن تطلب ربك حاجتك تسأله سبحانه أن يشفي مريضك، أن ينصرك على عدوك، تسأله المدد من فضله بالعون والتوفيق والهداية، كل هذا يُطلب من الله سبحانه وتعالى، رزقنا الله وإياك الاستقامة والبصيرة.\nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5519/زيارة-القبور-بين-المشروع-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_070/07004.mp3","categories":["زيارة القبور"]},{"id":7972,"question":"هذه الرسالة وردتنا من العراق من مرسلها (ش. ع. س) يقول: نشاهد بعض الناس وخاصة في المناطق الريفية أيام الأعياد يذهبون إلى المقابر وهناك يجتمعون نساء ورجال، وهناك يعملون الدبكات والأغاني، وقسم يحمل المسجلات والكاميرات ليلتقطوا أصوات وصور النساء، فما حكم ذلك أثابكم الله، طبعاً هو يصور الحالة في بلاده؟","title":"حكم قصد القبور يوم العيد وختلاط الرجال والنساء عندها","answer":"الجواب: أما قصد القبور أيام الأعياد فلا أعلم له أصلاً، زيارة القبور سنة وليس لها حد محدود ولا وقت معين، بل يزورها ليلاً ونهاراً في العيد وفي غيره ما لها وقت محدود، أما تخصيص زيارة بأيام العيد أو بيوم معين فليس له أصل، ولكن متى تيسرت الزيارة شرعت الزيارة في ليل أو نهار وفي أي يوم؛ لأنها تذكر الآخرة كما قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون،، نسأل الله لنا ولكم العافية -وفي لفظ: يرحم الله المستقدمين منا والمستأخرين، فالسنة أن يزور القبور وأن يدعو لأهلها بالمغفرة والرحمة، هذا هو السنة، وفي زيارتها ذكرى للمؤمن، يذكر الموت، ويذكر الآخرة، يستعد للقاء الله عز وجل، وهذا للرجال خاصة، أما النساء فلا يشرع لهن زيارة القبور بل ينهين عن ذلك.\nوأما اجتماع النساء والرجال عند القبور وتعاطي الأغاني وأشباه ذلك هذا لا يجوز، اختلاط الرجال بالنساء أمر مطلقاً لا يجوز لا في القبور ولا في غير القبور؛ لأن هذا يسبب الفتنة والشر، كذلك كونهن يحضرن في القبور أو غير القبور بالأغاني وآلات الملاهي هذا منكر سواء كان عند القبور أو في محل آخر، لا يجوز هذا، كذلك تصوير النساء، وتصويرهن في هذه الحال أو في أي حال كان، تصوير النساء كاشفات أو شبه عاريات كل هذا فتنة، أو تصوير وجوههن، كل هذا لا يجوز، بل يجب الحذر من ذلك؛ لأن هذا التصوير يجر إلى شر كثير، وربما صور فلانة وفلانة فحصل بها فتنة.\nفالحاصل أن هذا لا يجوز مطلقاً لا في القبور ولا في غيرها، ولا يجوز للنساء الخروج إلى المقابر بالأغاني وآلات الملاهي، ولا للرجال أيضاً، كل هذا منكر يجب الحذر منه والتناصح في ذلك.","link":"https://binbaz.org.sa/fatwas/5521/حكم-قصد-القبور-يوم-العيد-وختلاط-الرجال-والنساء-عندها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_071/07102.mp3","categories":["زيارة القبور"]},{"id":8031,"question":"هذه الرسالة وردت للبرنامج من الجمهورية العراقية من محافظة التأميم، يسأل مرسلها (ع. ي. م) أو المرسلة (ع. ي. م) عن قبور الأولياء، تقول: سؤالي هو: يوجد عندنا في العراق بدع، وهي: أن بعض الناس يقصدون إلى قبور أولياء الله والصالحين من مكان بعيد، وعند زيارة القبر يخلعون أحذيتهم، والقبور مبني عليها، تقول في رسالتها: إنه مبني عليها شبه المساجد، هل هذا جائز؟ وعند دخولهم يصلون ركعتين وهي صلاة الزيارة تقال: سنة، هل هذا جائز أم لا، أفيدونا وفقكم الله لما فيه الخير وجزاكم الله عنا خيراً؟","title":"نصيحة جامعة في أحكام زيارة القبور","answer":"الجواب: هذا سؤال مهم وله شأنه العظيم، وهو تعظيم القبور بالزيارة البدعية والبناء على القبور واتخاذ المساجد عليها، هذه مسائل ذات أهمية، ينبغي أن يعلم أن زيارة القبور سنة؛ لأن النبي عليه السلام قال زوروا القبور تذكركم الآخرة.\nولكن ليس المقصود من الزيارة أن يدعى الميت أو يستغاث به أو يطلب منه المدد أو يتمسح بالقبر أو ما أشبه ذلك، لا، المقصود من الزيارة: ذكر الآخرة .. ذكر الموت، والدعاء للميت والترحم عليه إذا كان مسلماً، هذا المقصود؛ ولهذا قال عليه الصلاة والسلام: زوروا القبور فإنها تذكركم الآخرة وفي اللفظ الآخر: تذكركم الموت فالسنة للزائر إذا زار أن يسلم على المقبورين وأن يدعو لهم بالمغفرة والرحمة، وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي لفظ: يرحم الله المستقدمين منا والمستأخرين وكان يقول إذا زار البقيع: اللهم اغفر لأهل بقيع الغرقد فالسنة إذا زار القبور هكذا أن يدعو لهم بالمغفرة والرحمة .. يسلم عليهم ويدعو لهم هذا هو المشروع، أما أن يزورهم ليدعوهم من دون الله، ليطلب منهم المدد.. ليستغيث بهم .. لينذر لهم، هذا من الشرك الأكبر والعياذ بالله وهذا من عمل الجاهلية أبي جهل وأصحابه عند القبور، فهذا لا يجوز بل هو من الشرك الأكبر.\nوهكذا الصلاة عند القبور لا تجوز، النبي ﷺ قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد.\nفلا يجوز الصلاة في القبور، ولا العكوف عندها، ولا سؤال أهلها، ولا الاستغاثة بهم، ولا النذر لهم كما تقدم، ولما رأت أم حبيبة وأم سلمة كنيسة في الحبشة وما فيها من الصور أخبرتا بذلك النبي ﷺ ، فقال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدا وصوروا بتلك الصور، أولئك شرار الخلق عند الله، فأخبر أنهم شرار الخلق بسبب تعظيمهم للقبور بالبناء عليها واتخاذ المساجد عليها ونحو ذلك، فالذي يفعله بعض الناس من اتخاذ المساجد قبور أو اتخاذ القباب على القبور المزينة بالذهب والفضة وغير ذلك كل هذا منكر، وقد ثبت عنه ﷺ أنه نهى عن تجصيص القبور، وعن القعود عليها، وعن البناء عليها، فلا يجوز للمسلمين أن يبنوا على القبور المساجد، ولا القباب ولا غيرها من الأبنية، بل تبقى ضاحية مكشوفة في الجبانة في المقابر، يأتي إليها الزائر ويسلم عليهم وهو واقف ثم ينصرف، ولا يجوز الصلاة عندها، ولا بين القبور، ولا التمسح بالتراب، ولا الجلوس عندها للقراءة أو الدعاء، كل هذا منكر، وإنما يسلم عليهم ويدعو لهم وينصرف كما فعله النبي ﷺ وكما فعله أصحابه، وكما علمهم النبي ﷺ ذلك عليه الصلاة والسلام.\nوالصلاة عند القبور من البدع ومن وسائل الشرك أيضاً، النبي ﷺ قال: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورا، دل ذلك على أن القبور لا يصلى فيها، ولا يصلى عندها، إنما الصلاة في المساجد .. في البيوت، أما القبور فلا؛ لأن الصلاة عندها من وسائل الشرك ومن وسائل العبادة من دون الله.\nوهكذا البناء عليها، وهكذا اتخاذ المساجد عليها، وهكذا اتخاذ القباب عليها، وفرشها تطييبها، كل هذا من وسائل الشرك، ولا ينبغي للعاقل أن يغتر بما يفعله الناس الجهلة من هذا الشيء كما في بلاد كثيرة يعظمون القبور ويبنون عليها المساجد والقباب، وهذا من المنكرات العظيمة، ومن وسائل الشرك كما لا يخفى عند أهل العلم.\nفوصيتي ونصيحتي للسائل أن يحذر هذا، فإذا زار القبور يزورها زيارة شرعية، يسلم عليهم ويدعو لهم إذا كانوا مسلمين وينصرف، أما الصلاة في المسجد الذي على القبر أو عند القبور فهذا منكر.\nكذلك الجلوس عندها للدعاء أو القراءة كذلك لا يجوز، وهكذا أعظم وأكبر دعاؤها، والاستغاثة بها، والنذر لها، وطلبها المدد، هذا يفعله بعض الجهلة وهو من الشرك الأكبر.\nفالواجب الحذر من ذلك غاية الحذر، وكثير من المسلمين عندهم جهل كثير في هذه المسائل، يفعلون ما يرون العامة يفعلونه عند القبور ولا يعلمون أحكام الشرع في ذلك.\nوالواجب على العلماء في كل بلاد أن يعلموا الناس وأن يرشدوا الناس إلى سنة نبيهم عليه الصلاة والسلام، وأن يحذروهم من الشرك والبدع، هذا هو الواجب على أهل العلم في كل مكان، ولكن بسبب قلة العلماء وقلة أهل التحقيق كثر هذا الشر في بلدان كثيرة، وظنوه ديناً وظنوه شيئاً مشروعاً، فصاروا يسارعون إليه يحسبون أنهم على هدى وعلى حق في ذلك، وهذه مصيبة يجب التنبيه عليها، ويجب على كل مسلم أن يسأل عما أشكل عليه، وألا يتساهل بالأمور العادية التي جرى عليها آباؤه وأسلافه، لا، بل يسأل، فإن الكفار كان من عادتهم اتباع أسلافهم على غير بصيرة كما حكى الله عنهم أنهم يقولون: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23]، فلا ينبغي التأسي بالكفرة في ذلك، بل تسأل أهل العلم إن كانوا عندك أو تكتب إليهم في أي بلاد، تسألهم عما أشكل عليك من أمور دينك حتى تكون على بصيرة؛ لأن الله قال: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43].\nفالواجب على أهل الإسلام إذا كان ما عندهم علم أن يسألوا، يعني: كل إنسان ما عنده علم يسأل عما أشكل عليه في أمور القبور .. في أمور صلاته .. في زكاته .. في صيامه .. في معاملاته، في كل شيء.\nالمقدم: شكراً لفضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/5648/نصيحة-جامعة-في-احكام-زيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_079/07904.mp3","categories":["زيارة القبور"]},{"id":8272,"question":"وزيارة قبر النبي ﷺ والصلاة في المسجد النبوي الشريف؟","title":"حكم زيارة قبر النبي عليه الصلاة والسلام","answer":"الجواب: زيارة قبر النبي ﷺ سنة وقربة، إذا كانت زيارة القبور الأخرى سنة فمن باب أولى زيارة قبره عليه الصلاة والسلام.\nوالصلاة في مسجده ﷺ سنة وقربة، ومن أجلها تشد الرحال إلى مسجده ﷺ وإلى المسجد الحرام وإلى المسجد الأقصى كما قال النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام.\nإنما الذي يمنع في أصح قولي العلماء شد الرحال من أجل القبر وحده.\nكونه يشد الرحل من أجل القبر لا من أجل المسجد ولا من أجلهما معاً ولكن من أجل القبر وحده، هذا هو الذي يمنع في أصح قولي العلماء لهذا الحديث، لقوله ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد ... فإذا منع شد الرحال إلى مسجد غير هذه الثلاثة فمن باب أولى شد الرحال إلى بقعة أخرى أو إلى قبر، من باب أولى أن يمنع؛ لأن المساجد أفضل بقاع الأرض، كما صح عن النبي ﷺ أنه قال: خير بقاع الأرض مساجدها وشرها أسواقها.\nفإذا كانت المساجد التي هي خير بقاع الأرض لا تشد الرحال إليها للتقرب فيها إلا هذه الثلاثة المساجد، فهكذا يمنع من باب أولى أن تشد الرحال إلى قبر من القبور لا قبر النبي ﷺ ولا غيره، أو إلى بقعة يقال أنه جلس فيها رجل صالح، أو صلى فيها أو نحو ذلك، لماذا؟ لأن شد الرحل للقبر يتخذ وسيلة إلى الغلو ودعاء صاحب القبر والاستغاثة به، أو النذر له، أو الصلاة عند قبره، أو الدعاء عنده، وهذه وسائل للشرك، الصلاة عند القبر أو الدعاء عنده أو القراءة من وسائل الشرك.\nأما دعاء القبر؛ دعاء صاحب القبر والاستغاثة بصاحب القبر هذا نفس الشرك وعين الشرك الذي حرمه الله عز وجل، فمن أجل هذا والله أعلم حرم الله شد الرحال إلى غير الثلاثة المساجد سداً لذرائع الشرك، وحسماً لوسائله، فإذا شد الرحل ليصلي في المسجد وليسلم على النبي صلى الله عليه وسلم فلا بأس، دخلت الزيارة تبعاً، أما أن يكون شده للرحل من أجل القبر فقط فهذا هو الذي يمنع.\nولكن لا أظن مسلماً يقصد هذا، فإن المسلم الذي يفهم الإسلام لا يقصد القبر وحده وإنما يشد الرحل ليصلي في المسجد وليسلم على النبي صلى الله عليه وسلم فتكون الزيارة تابعة للمسجد، فلا حرج في ذلك.\nوأما من كان في المدينة مقيماً فهذا يشرع له أن يزور بين وقت وآخر، ويسلم على النبي ﷺوعلى صاحبيه، كما يزور البقيع وشهداء أحد ويسلم عليهم بين وقت وآخر، لقوله ﷺ: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه  إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وغيره في حديث عائشة: يرحم الله المستقدمين منا والمستأخرين.\nوكان إذا زار البقيع يقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، غداً مؤجلون، اللهم اغفر لأهل بقيع الغرقد فيدعو لهم عليه الصلاة والسلام، هذه هي السنة؛ زيارة القبور للدعاء لهم، للترحم على الموتى ولذكر الآخرة والزهد في الدنيا، لا تزار القبور لدعاء أهلها أو الاستغاثة بهم، أو الدعاء عند قبورهم، أو الصلاة عندها، أو القراءة عندها، لا، ولكن تزار للاستغفار لهم والترحم عليهم، والدعاء لهم بالرحمة والمغفرة، ولذكر الآخرة وذكر الموت والزهد في الدنيا هذه هي المقاصد لزيارة القبور.\nلكن أهل الجهل ولكن الغلاة يزورون القبور ليدعوا الموتى، ليدعوهم من دون الله، ليستغيثوا بهم، ليطلبوهم المدد والعون، وهذا هو الشرك الأكبر، أو يزوروهم من أجل البدع كالصلاة عند قبورهم يظنون أنها أجوب وأنفع وأفضل، أو الدعاء عند القبور، أو القراءة عندها، وهذا أيضاً بدعة؛ لأنه وسيلة إلى الشرك، اليوم يصلي عندها لله وفي يوم آخر قد يصلي لأهلها، قد يجعل الصلاة للميت والسجود له فيقع في الشرك.\nوهكذا الدعاء عندها وهكذا القراءة عندها، هذه بدعة وقد تجر هذه البدعة إلى أن يقصد الميت بأن يدعوه من دون الله أو يستغيث به من دون الله أو نحو ذلك من أنواع الشرك، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيراً.\nإذن زيارة أخينا هذا وإن كان في فمه بخر ليس فيها شيء من ناحية الشرع؟\nالشيخ: نعم، ليس فيها شيء.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6081/حكم-زيارة-قبر-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_099/09904.mp3","categories":["زيارة القبور"]},{"id":8288,"question":"الرسالة التالية وصلت إلى البرنامج من العراق بغداد الأعظمية منطقة الرصافة، باعثة الرسالة إحدى الأخوات من هناك تقول (مها . ع. ز) ، لها مجموعة من الأسئلة من بينها سؤال: قال رسول الله ﷺ: ليس للنساء نصيب في الجنازة ما هي الأمور التي تجتنبها المرأة في موضوع الجنازة؟","title":"ما الأمور التي تجتنبها المرأة في الجنازة؟","answer":"الجواب: هذا الحديث الذي ذكرته السائلة: ليس للمرأة نصيب في الجنازة لا نعلم له أصلاً، ولا نعلم أحداً أخرجه من أهل العلم، وإنما الوارد عن الرسول ﷺ في هذا: أنه ﷺ لعن زائرات القبور والمتخذين عليها المساجد والسرج، ولعن أناساً آخرين كالبناء على المساجد كبناء مسجد على القبور ونحو ذلك، ونهى عن اتباع الجنائز للنساء من دون لعن، بل نهى عن اتباع الجنائز، قالت أم عطية رضي الله عنها: نهينا عن اتباع الجنائز، ولم يعزم علينا يعني: لم يؤكد علينا، فدل ذلك على أنها لا تتبع الجنازة إلى المقبرة، ولا تزور القبور، وإنما هذا من خصائص الرجال، لكنها تصلي على الجنازة، إذا صلي عليها في البيت أو في المسجد تصلي المرأة مع الرجال على الجنائز، كما صلت عائشة رضي الله عنها على جنازة سعد بن أبي وقاص في مسجد النبي ﷺ.\nفالحاصل أن المرأة تصلي على الجنائز مع الرجال لا بأس، أما ذهابها مع الجنازة إلى المقبرة أو زيارة القبور فهذا هو الذي نهي عنه فلا يجوز لها ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/6099/ما-الامور-التي-تجتنبها-المراة-في-الجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10704.mp3","categories":["زيارة القبور"]},{"id":8290,"question":"لها سؤال آخر سماحة الشيخ تقول فيه: هل يحرم على النساء زيارة القبور إذا كان المتوفى أعز شخص، قال رسول الله ﷺ: لعن الله المرأة النائحة والمستمعة صدق رسول الله، لكنني في الحقيقة لم أفهم معنى المستمعة في هذا الحديث، هل يقصد المرأة الفضولية التي تتنصت على كلام الناس، أم المرأة التي تستمع الأغاني، أم التي تستمع التلفاز والراديو، نرجو التوضيح عن هذا جزاكم الله خيراً؟","title":"حكم زيارة المرأة للقبور ومعنى النائحة والمستمعة","answer":"الجواب: زيارة القبور للنساء تقدم أنها لا تجوز، النبي ﷺ قال: زوروا القبور فإنها تذكركم الآخرة يعني: به الرجال، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي حديث عائشة: يرحم الله المستقدمين منا والمستأخرين، أما النساء فنهاهن عن هذا، جاء في الأحاديث: لعن زائرات القبور، فلا يجوز لهن زيارة القبور، ولكن يشرع لهن الدعاء لموتاهن بالمغفرة والرحمة ودخول الجنة والنجاة من النار من غير زيارة للقبور، وهن في بيوتهن، ولا مانع أن يصلين على الموتى كما تقدم في المساجد أو في المصلى، كما صلى النساء على الجنائز في عهده ﷺ وفي عهد أصحابه، أما النائحة والمستمعة فقد نهى النبي عن النوح عليه الصلاة والسلام، وقال: أربع في أمتي من أمر الجاهلية لا يتركونهن: الفخر بالأحساب، والطعن في الأنساب، والاستسقاء بالنجوم، والنياحة على الميت، وقال: النائحة إذا لم تتب قبل موتها تقام يوم القيامة وعليها سربال من قطران ودرع من جرب خرجه مسلم في صحيحه، فبين ﷺ أن النياحة على الموتى من أمر الجاهلية المذموم، فالواجب تركه، وقالت أم عطية: أخذ علينا الرسول ﷺ في البيعة أن لا ننوح، وروى أبو داود رحمه الله في سننه عن أبي سعيد ، عن النبي ﷺ أنه: لعن النائحة والمستمعة وفي سنده ضعف، في سنده ضعف، ولكن معناه له شواهد وهي أن النوح محرم ومنكر، فلا يجوز للمرأة أن تتعاطى النوح ولا للرجل أيضاً، ليس للرجال ولا للنساء النياحة، والنياحة: رفع الصوت بالبكاء هذه النياحة، وهكذا قوله بـ: واعضداه واكاسياه واحر قلباه برفع الصوت، كل هذا من النياحة، وأما المستمعة: فهي التي تستمع للنوح وتشجع على النوح، تجلس معهن تستمع نياحتهن وتشجعهن على النياحة، هذه داخلة في ذلك؛ لأن جلوسها نوع من التشجيع فلا يجوز لها أن تستمع، بل إذا لم تسكت النائحة وجب أن تفارق وأن لا يجلس معها، من باب الهجر لها ومن باب الإنكار عليها، فإذا جلست تستمع صار في ذلك نوع من المساعدة، ونوع من التشجيع، فلا يجوز أن تستمع للنائحة، بل تنكر عليها وتنهاها، فإن أقلعت وإلا تركتها ولم تجلس معها تستمع لها، أما سماع الأغاني والأشياء الأخرى هذا فيها بحث آخر غير سماع النياحة، سماع الأغاني منكر على الرجال والنساء، الأغاني من المنكرات ومن أسباب مرض القلوب وقسوتها والضلال عن الحق كما قال الله عز وجل في كتابه العظيم: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6] هذا دليل على أن اشتراء لهو الحديث يعني: اعتياضه سواءً بغير ثمن أو بالثمن أنه من المنكر المذموم، فالله ذكر هذا على سبيل الذم لهم والعيب لهم وَمِنَ النَّاسِ مَنْ يَشْتَرِي [لقمان:6]يعني: لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6] قرئ (ليضل) بالضم، وقرئ (ليضل) بالفتح، هذا يدل على أن اشتراء لهو الحديث من أسباب الضلال والإضلال بغير علم، ومن أسباب اتخاذ آيات الله هزواً، ولهذا قال بعده: وَيَتَّخِذَهَا هُزُوًا [لقمان:6] يعني: سبيل الله يعني: دين الله، وهذا خطر عظيم، ولهو الحديث هو الغناء كما قال جمهور أهل العلم، قال أكثر أهل العلم من المفسرين وغيرهم إنه الغناء، وإذا كان معه آلة عزف كالعود أو الكمان أو الدف أو الطبل كان التحريم أشد كان الإثم أكبر، فلا يجوز ذلك، وليس للمرأة ولا للرجل تعاطي ذلك، سواءً كان ذلك في التلفاز أو في الإذاعة أو في المسجلات أو غير ذلك أو في الفيديو كل هذا ممنوع، وإذا كان مع ذلك الفيديو مرائي منكرة كاجتماع النساء والرجال اختلاط النساء بالرجال، أو رؤية الرجل مع زوجته أو ما أشبه ذلك كان التحريم أكثر وكان الإثم أعظم، فلا يجوز مثل هذا أبداً لا للرجال ولا للنساء، ولكن مسألة النياحة شيء آخر، فالنياحة لها تعلق بالميت سواء كان ناح عليه في البيت أو عند القبر أو في أي مكان، فلا يجوز الاستماع للنائحة ولا تشجيعها على عملها السيئ، بل يجب الإنكار عليها وتحذيرها ومنعها من ذلك، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6103/حكم-زيارة-المراة-للقبور-ومعنى-الناىحة-والمستمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10706.mp3","categories":["زيارة القبور"]},{"id":8761,"question":"إذا توفي واحد عندنا عادة بالسودان بعد أربعين تقوم الأسرة بزيارة للقبر، الحريم والأولاد، ويفتحون القبر ومعهم حبوب ذرة ينشرونها على الميت ويرمون -فيما أعتقد- حجارة على جانبي الميت، هل هذا جائز؟ وهل الحريم يزورون القبور؟","title":"حكم فتح القبور لغير الحاجة والضرورة","answer":"الجواب: هذا العمل بدعة لا أصل له في الشرع، فتح القبر ووضع الحبوب عليه، أو الطيب، أو ملابس، أو غير ذلك كله منكر لا أصل له، بل هو من البدع، والقبر لا يفتح بعد ذلك إلا لحاجة كأن ينسى العَمَلة أدواتهم كالمسحاة ونحوها فيفتح لأجل ذلك، أو يسقط من أحدهم شيء له أهمية فيفتح لأجل ذلك، أما يفتح لرؤية الميت أو لإدخال ملابس عليه أو أطياب أو حبوب، كل هذا بدعة لا أصل له،\nوليس للنساء زيارة القبور أيضًا لقول أبي هريرة وابن عباس وغيرهما: لعن رسول الله ﷺ زائرات القبور، فالرسول ﷺ لعن زائرات القبور، روى ذلك أبو هريرة وابن عباس وحسان بن ثابت رضي الله عنهم، وكان أولًا أذن للجميع في الزيارة، ثم نهى النساء وأقر الرجال وقال لهم: زوروا القبور فإنها تذكركم الآخرة، فأقر الرجال ونهى النساء عن الزيارة، والحكمة في ذلك والله أعلم لأنهن فتنة، ولقلة صبرهن، فكان من حكمة الله أن نهاهن عن الزيارة حتى لا يفتتن ولا يفتن غيرهن. نعم.","link":"https://binbaz.org.sa/fatwas/6907/حكم-فتح-القبور-لغير-الحاجة-والضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16209.mp3","categories":["زيارة القبور","حرمة الأموات","البدع والمحدثات"]},{"id":8776,"question":"هذه رسالة وردتنا من المرسلة صباح محمد علي يونس من العراق من محافظة نينوى، تقول: ذكرتم في حلقات سابقة من هذا البرنامج عدم زيارة الأضرحة وأنها من الشرك بالله، فهل زيارة النبي يونس والنبي جرجيس في نينوى تدخل ضمن ذلك؟ وهل الصلاة فيها غير جائزة؟","title":"حكم زيارة الأضرحة","answer":"الجواب: الزيارة قسمان، زيارة القبور قسمان:\nزيارة شرعية، وزيارة بدعية شركية، أما الزيارة الشرعية فهذه مشروعة لقبور الصالحين والمسلمين جميعاً، وإذا عرف قبر من قبور الأنبياء كقبر نبينا ﷺ تشرع له الزيارة من دون شد الرحل، شد الرحل لا يشد الرحال للقبور لا تشد إلا للمساجد الثلاثة: المسجد الحرام، ومسجد النبي صلى الله عليه وسلم، والمسجد الأقصى، هؤلاء الثلاثة تشد لهم الرحال، أما القبور لا تشد لها الرحال، لكن إذا كان الإنسان في البلد قصدها زائراً فهذا سنة؛ قال النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة، واللفظ الآخر: تذكركم الموت، فزيارة القبور سنة وقربى وقد فعلها النبي ﷺوفعلها أصحابه  وأرضاهم، فإذا زار المسلم قبور المسلمين في بلده ودعا لهم واستغفر لهم كان هذا قربة وطاعة، وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية، هكذا علمهم النبي ﷺ، وكان يزور القبور ﷺ بنفسه ويدعو للموتى ويستغفر لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد، وفي لفظ يقول: نسأل الله لنا ولكم العافية، فعلى المؤمن أن يفعل مثلما فعله النبي ﷺ إذا زار القبور ومثلما علم أصحابه، يسلم عليهم ويدعو لهم بالمغفرة والرحمة ويستغفر لهم يقول: نسأل الله لنا ولكم العافية، هذه الزيارة الشرعية.\nوهكذا إذا زار قبر النبي ﷺ في المدينة إذا زار المسجد ثم زار قبر النبي ﷺ يسلم عليه ويدعو له يقول: صلى الله وسلم عليك وعلى آلك وأصحابك، جزاك الله عن أمتك خيراً.\nوهكذا إذا زار قبور الصالحين في أي مكان يدعو لهم بالمغفرة والرحمة ويستغفر لهم ويسأل الله لهم العافية.\nأما قبر يونس فلا يعلم بنينوى، جميع قبور الأنبياء لا تعلم ولا تعرف، فدعوى أنه موجود في نينوى أو في غيرها أمر باطل لا أصل له، ذكر العلماء أنه لا يوجد قبر معروف من قبور الأنبياء ألبتة إلا قبر نبينا محمد صلى الله عليه وسلم في المدينة وإلا قبر الخليل في الخليل في المغارة المعروفة، هذا هو المعروف، أما قبور بقية الأنبياء فغير معروفة، لا يونس ولا غيرهم من الأنبياء والرسل، قبورهم الآن غير معلومة، ومن ادعى أن قبر يونس موجود أو فلان أو فلان كله كذب لا صحة له، ولا نعلم نبياً يقال له: جرجيس ، ولا يعرف في الأنبياء من يسمى جرجيس .\nفالمقصود أنه ليس هناك قبر نبي معروف غير قبر نبينا محمد ﷺ في المدينة وغير قبر الخليل في بلد الخليل في المغارة المعروفة.\nالمقدم: وهذه الزيارة التي ذكرتم للرجال والنساء؟\nالشيخ: أما هذه الزيارة الشرعية للرجال، أما النساء فلا يشرع لهم الزيارة على الصحيح، النبي صلى الله عليه وسلم لعن زائرات القبور، فدل ذلك على أن النساء لا يزرن القبور وإنما الزيارة للرجال خاصة في أصح قولي العلماء؛ لما جاءت به الأحاديث الصحيحة عن رسول الله ﷺأنه لعن زائرات القبور، جاء هذا من حديث أبي هريرة ، ومن حديث حسان بن ثابت ، ومن حديث ابن عباس ، فلا يشرع لهن الزيارة ولا تجوز لهن الزيارة، ولكن يدعون للموتى المسلمين في بيوتهم في المساجد في البيوت، وإذا زاروا المدينة دعوا للنبي ﷺ وهم في المسجد أو في بيوتهم، صلوا عليه وسلموا عليه في أي مكان عليه الصلاة والسلام، مثلما قال عليه الصلاة والسلام: لا تتخذوا قبري عيداً ولا بيوتكم قبورا، وصلوا علي فإن صلاتكم تبلغني حيث كنتم عليه الصلاة والسلام، فإذا صلى عليه المؤمن والمؤمنة في أي مكان بلغ ذلك، يقول ﷺ: إن لله ملائكة سياحين يبلغوني عن أمتي السلام عليه الصلاة والسلام.\nفالمشروع لك -أيها السائلة- أن تصلي عليه صلى الله عليه وسلم في أي مكان وعلى بقية الأنبياء عليهم الصلاة والسلام، وأما زيارة هذا القبر الذي يقال له: قبر يونس هذا لا أصل له، ثم النساء لا يزرن القبور على الصحيح، ولكن يدعون لموتى المسلمين ويستغفرون لموتى المسلمين في أي مكان. نعم..","link":"https://binbaz.org.sa/fatwas/6937/حكم-زيارة-الاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21910.mp3","categories":["زيارة القبور","نواقض الإسلام","البدع والمحدثات"]},{"id":8804,"question":"السؤال الثاني في رسالة الأخ أحمد محمد حسين من العراق، يقول فيه: هل يجوز للرجال زيارة القبور أم لا أفيدوني أفادكم الله؟","title":"المشروع والممنوع في زيارة القبور","answer":"الجواب: زيارة القبور سنة مؤكدة ثابتة عن نبينا ﷺ فقد كان ﷺ يزور القبور، ويقول: زوروا القبور فإنها تذكركم الآخرة وكان عليه الصلاة والسلام يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي رواية أخرى كان يقول ﷺ: يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد.\nفالسنة للرجال أن يزوروا القبور ؛ لأنها تذكر الآخرة وتذكر الموت، وتعين على الاستعداد للآخرة، ويستحب له أن يقول ما علمه النبي أصحابه عليه الصلاة والسلام، فيقول الزائر: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية غفر الله لنا ولكم ورحمنا وإياكم وما أشبه من هذا الدعاء الطيب.\nأما النساء فلا، النساء لا يزرن القبور؛ لأنه ﷺ لعن زائرات القبور، فالنساء لا يزرن القبور، وأما الرجال فيشرع لهم زيارة القبور ولكن لا يقولوا هزواً، يعني: لا يقولوا كلاماً سيئاً، فلا يجوز دعاء الأموات ولا الاستغاثة بالأموات ولا طلبهم المدد كما يفعله بعض الجهال، هذا منكر وشرك، فلا يجوز للمسلم ولا لغيره أن يدعو الأموات أو يستغيث بهم ؛ لأن الميت قد انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له، أما كونه يسأل المدد أو العون أو الغوث سواء كان نبياً أو ولياً أو غيرهما فلا يجوز ذلك، بل هذا يختص بالله وحده هو الذي يدعى ويسأل، وهكذا يجوز مع المخلوق الحي الحاضر لا بأس، تقول لأخيك الحاضر: أعطني كذا.. ساعدني بكذا، أقرضني، ساعدني على بناء بيتي.. على إصلاح سيارتي لا بأس، أما الميت فلا يسأل، قال الرسول ﷺ إذا سألت فاسأل الله وإذا استعنت فاستعن بالله والله يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] وأما ما يفعله بعض الجهال عند بعض القبور، يقول: يا سيدي فلان المدد المدد أو أغثني أو اشف مريضي، هذا كله منكر وكله من الشرك الأكبر كما بين ذلك أهل العلم، والله المستعان.\nوالمقصود من هذا أنه يزور القبور ويدعو لهم بالمغفرة والرحمة ولا يزيد على ذلك في طلبهم شيئاً من عندهم، أن يقول: اشفعوا لي أو اشفوا مريضي أو المدد المدد، أو ما أشبه ذلك.\nولا يجوز أن يتخذ القبور محلاً للصلاة عندها، أو الطواف بها، أو الدعاء عندها لا، إنما يزورهم كما زارهم النبي ﷺ، وكما زارهم أصحاب النبي ﷺ يسلمون عليهم، ويدعون لهم بالمغفرة والرحمة، ويحصل في هذا ذكر الموت وذكر الآخرة، هكذا ثبتت السنة عن رسول الله عليه الصلاة والسلام والله ولي التوفيق.\nأما تخصيص زيارة القبور بعد صلاة العيد كأنه يزور الأحياء والأموات ما أعرف لهذا أصلاً، ولم أعلم عن النبي ﷺ ولا عن الصحابة أنهم كانوا يخرجون إلى البقيع بعد صلاة العيد، والخير في اتباع السلف الصالح، الخير في اتباع الرسول صلى الله عليه وسلم وأصحابه، قال الله : قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31] فكونه يعني يتخذ زيارة للقبور بعد صلاة العيد طريقة متبعة، الذي أرى ترك ذلك.\nأما إذا كان أفرغ له يعني يكون فارغ ذلك الوقت وزارهم لا لقصد أن هذا سنة أو أن هذا وقت مناسب هذا لا بأس به، يزورهم يزور صباحاً أو مساءً أو في الليل أو بعد صلاة الفجر كل هذا لا بأس به، لكن كونه يخصص بعد صلاة العيد ويرى أن هذا قربة أو سنة خاصة هذا لا نعلم له أصلاً، أما إذا جاءهم وزارهم من غير قصد مرة يوم العيد أو بعد صلاة العيد أو في آخر نهار العيد وزار القبور لا لقصد أن هذا سنة أو أن هذا الوقت مناسب لها، فلا حرج في هذا. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6955/المشروع-والممنوع-في-زيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_222/22202.mp3","categories":["زيارة القبور"]},{"id":9369,"question":"أخ مصري يسأل ويقول: يوجد في بلدتنا رجل متوفى صالح ويبنى له مقام على قبره، وله عادة عندنا في كل عام نذهب مع الناس إليه رجالاً ونساء ويقيمون عنده ثلاثة أيام بالمدح والتهاليل والأذكار، ويستمر في الأوصاف المعروفة سماحة الشيخ ويرجو التوجيه والإرشاد جزاكم الله خيراً؟","title":"حكم زيارة القبور والمكوث فيها للأكل والشرب وقراءة الأذكار","answer":"الجواب: هذا العمل لا يجوز بل هو من البدع التي أحدثها الناس، فلا يجوز أن يقام على قبره بناء سواء سمي مقاماً أو سمي قبة أو سمي غير ذلك، كانت القبور في عهد النبي ﷺ وعهد الصحابة مكشوفة ليس عليها بناء، والنبي ﷺ نهى أن يبنى على القبر وأن يجصص وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد متفق على صحته، وقال جابر بن عبد الله الأنصاري : نهى رسول الله ﷺ أن يجصص القبر وأن يقعد عليه وأن يبنى عليه فالبناء على القبور منكر وهكذا تجصيصها ووضع الزينات عليها أو الستور كله منكر ووسيلة إلى الشرك، فلا يجوز وضع القباب أو الستور أو المساجد عليها.\nوهكذا زيارتها على الوجه الذي ذكره السائل من الجلوس عندها والتهاليل وأكل الطعام والتمسح بالقبر أو الدعاء عند القبر أو الصلاة عند القبر كل هذا منكر، كله بدعة لا يجوز، إنما المشروع زيارة القبور كونه يزورها ويدعو لهم ثم ينصرف، يمر على القبور ويقول: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين. وما أشبه من الدعوات فقط، هذا هو المشروع الذي علمه النبي أصحابه عليه الصلاة والسلام كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وحديث عائشة: يرحم الله المستقدمين منا والمستأخرين، وحديث ابن عباس: السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر، هذا المشروع.\nوأما الإقامة عند القبر للأكل والشرب أو للتهاليل أو للصلاة أو لقراءة القرآن كل هذا منكر، يسلم ويذهب، ويدعو للميت ويترحم عليه، أما اتخاذه محل دعاء أو محل قراءة أو محل طواف أو محل تهاليل والجلوس عنده، أو أكل يوم أو يومين أو ثلاثة هذا ماله أصل، هذا بدعة ومن وسائل الشرك فيجب الحذر من ذلك ويجب ترك ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7533/حكم-زيارة-القبور-والمكوث-فيها-للاكل-والشرب-وقراءة-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15608.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":9453,"question":"الرسالة الثالثة وردتنا من سائلة من العراق من دهوك رمزت لنفسها بـ (س. س) تقول الأخت من العراق في رسالتها: ورد في الحديث الشريف عن رسول الله ﷺ قوله: لعن الله زائرات القبور، فأرجو التوضيح هل يقصد بها النساء جميعاً، أم هناك نساء معينات؟ وكيف الحال عند زيارة قبر الرسول ﷺ؟ وما هي الأدعية التي تقال عند زيارة القبور أفيدونا بارك الله فيكم؟","title":"الخلاف والترجيح في زيارة النساء للقبور","answer":"الجواب: اختلف العلماء في زيارة النساء للقبور بعدما أجمعوا على سنيتها للرجال، وكان النبي ﷺ قد نهى عن زيارة القبور في أول الإسلام خشية الفتنة بالقبور؛ لأن الجاهلية كانت تعظم القبور، وربما عبدت بعض المقبورين من دون الله، فنهاهم عن زيارة القبور حماية للتوحيد وسداً لذرائع الشرك، ثم أذن للرجال في الزيارة، قال عليه الصلاة والسلام: كنت نهيتكم عن زيارة القبور فزوروها؛ فإنها تذكركم الآخرة، وفي لفظ: تذكركم الموت .\nواختلف العلماء في النساء هل دخلن في هذا أم لا؟ على قولين لأهل العلم: والصواب أنهن لم يدخلن في الرخصة، بل ينهين عن زيارة القبور؛ لأنه ورد عنه ﷺ من عدة طرق: أنه لعن زائرات القبور، وفي لفظ: زوارات القبور، من حديث أبي هريرة ، ومن حديث ابن عباس ، ومن حديث حسان بن ثابت ، وفيها لعن زائرات القبور.\nفالصواب أنهن لا يزرن القبور مطلقاً، هذا هو الأرجح من قولي العلماء، حتى قبر النبي ﷺ لا يزرنه ولا يقفن عليه، ولكن يصلين على النبي ﷺ في كل مكان، في المسجد النبوي وفي البيت، وفي الطريق، وفي بيوتهن وفي كل مكان، النبي عليه السلام قال: لا تجعلوا قبري عيداً، وصلوا علي فإن صلاتكم تبلغني حيث كنتم، فالرسول ﷺ حثنا ورغبنا في الصلاة عليه والسلام عليه، كما أمر الله بذلك في كتابه العظيم حيث قال سبحانه: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56]، صلى الله وسلم عليه وعلى آله وأصحابه صلاة وسلاماً دائمين إلى يوم الدين.\nفالمشروع للنساء الصلاة عليه والسلام عليه في كل مكان كالرجال، ولا يشرع لهن زيارة القبر، ولا قبور الناس الآخرين، لا في بلدهن ولا في غير بلدهن، هذا هو المعتمد والأرجح من قولي العلماء في هذه المسألة، وإذا كانت المرأة في المدينة سائرة تصلي في المسجد مع الناس، وتصلي على النبي ﷺ وهي في المسجد، ما في حاجة إلى أن تذهب إلى عند القبر تصلي عليه في محلها، وتسلم عليه تقول: اللهم صل وسلم على رسول الله، عليك الصلاة والسلام يا رسول الله! ونحو ذلك، ويكفي هذا والحمد لله احتياطاً وبعداً عما حرم الله. نعم.","link":"https://binbaz.org.sa/fatwas/7626/الخلاف-والترجيح-في-زيارة-النساء-للقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24004.mp3","categories":["زيارة القبور"]},{"id":9456,"question":"الرسالة الثالثة وردتنا من سائلة من العراق من دهوك رمزت لنفسها بـ (س. س) تقول الأخت من العراق في رسالتها: ورد في الحديث الشريف عن رسول الله ﷺ قوله: لعن الله زائرات القبور، فأرجو التوضيح هل يقصد بها النساء جميعاً، أم هناك نساء معينات؟ وكيف الحال عند زيارة قبر الرسول ﷺ؟ وما هي الأدعية التي تقال عند زيارة القبور أفيدونا بارك الله فيكم؟","title":"الخلاف والترجيح في زيارة النساء للقبور","answer":"الجواب: اختلف العلماء في زيارة النساء للقبور بعدما أجمعوا على سنيتها للرجال، وكان النبي ﷺ قد نهى عن زيارة القبور في أول الإسلام خشية الفتنة بالقبور؛ لأن الجاهلية كانت تعظم القبور، وربما عبدت بعض المقبورين من دون الله، فنهاهم عن زيارة القبور حماية للتوحيد وسداً لذرائع الشرك، ثم أذن للرجال في الزيارة، قال عليه الصلاة والسلام: كنت نهيتكم عن زيارة القبور فزوروها؛ فإنها تذكركم الآخرة، وفي لفظ: تذكركم الموت .\nواختلف العلماء في النساء هل دخلن في هذا أم لا؟ على قولين لأهل العلم: والصواب أنهن لم يدخلن في الرخصة، بل ينهين عن زيارة القبور؛ لأنه ورد عنه ﷺ من عدة طرق: أنه لعن زائرات القبور، وفي لفظ: زوارات القبور، من حديث أبي هريرة ، ومن حديث ابن عباس ، ومن حديث حسان بن ثابت ، وفيها لعن زائرات القبور.\nفالصواب أنهن لا يزرن القبور مطلقاً، هذا هو الأرجح من قولي العلماء، حتى قبر النبي ﷺ لا يزرنه ولا يقفن عليه، ولكن يصلين على النبي ﷺ في كل مكان، في المسجد النبوي وفي البيت، وفي الطريق، وفي بيوتهن وفي كل مكان، النبي عليه السلام قال: لا تجعلوا قبري عيداً، وصلوا علي فإن صلاتكم تبلغني حيث كنتم، فالرسول ﷺ حثنا ورغبنا في الصلاة عليه والسلام عليه، كما أمر الله بذلك في كتابه العظيم حيث قال سبحانه: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56]، صلى الله وسلم عليه وعلى آله وأصحابه صلاة وسلاماً دائمين إلى يوم الدين.\nفالمشروع للنساء الصلاة عليه والسلام عليه في كل مكان كالرجال، ولا يشرع لهن زيارة القبر، ولا قبور الناس الآخرين، لا في بلدهن ولا في غير بلدهن، هذا هو المعتمد والأرجح من قولي العلماء في هذه المسألة، وإذا كانت المرأة في المدينة سائرة تصلي في المسجد مع الناس، وتصلي على النبي ﷺ وهي في المسجد، ما في حاجة إلى أن تذهب إلى عند القبر تصلي عليه في محلها، وتسلم عليه تقول: اللهم صل وسلم على رسول الله، عليك الصلاة والسلام يا رسول الله! ونحو ذلك، ويكفي هذا والحمد لله احتياطاً وبعداً عما حرم الله. نعم.","link":"https://binbaz.org.sa/fatwas/7626/الخلاف-والترجيح-في-زيارة-النساء-للقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24004.mp3","categories":["زيارة القبور"]},{"id":9581,"question":"أول سؤال في هذه الحلقة هو تكملة لأسئلة تقدم بها الأخ (م. ب) من جامعة البترول والمعادن بالظهران، وقد سبق أن عرضنا له سؤالاً على سماحة الشيخ عن موضوع، أو مسألة التداوي، وفي هذه الحلقة يقول في سؤاله: قالوا: تكره زيارة القبور للنساء لحديث أم عطية، وإن علم وقوع محرم منهن حرمت، وعليه يحمل قوله ﷺ : لعن الله زوارات القبور إلا لغير النبي ﷺ وقبري صاحبيه رضي الله عنهما فتسن زيارتها للرجال والنساء، لعموم الأدلة في طلب زيارته ﷺ، ما هذه الأدلة، وما رأي سماحتكم في المسألة عامة وفقكم الله؟","title":"حكم زيارة القبور للنساء وزيارتها المشروعة والممنوعة للرجال","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وصحبه ومن اهتدى بهداه. أما بعد: فقد ثبت عن رسول الله ﷺ أنه لعن زائرات القبور، وثبت ذلك من حديث ابن عباس، ومن حديث أبي هريرة، ومن حديث حسان بن ثابت الأنصاري. وأخذ العلماء من ذلك أن الزيارة للنساء محرمة؛ لأن اللعن لا يكون إلا على محرم، بل يدل على أنه من الكبائر؛ لأن العلماء ذكروا أن المعصية التي يكون فيها لعن أو فيها وعيد بالنار هذه تكون من الكبائر. فالصواب أن زيارة النساء للقبور محرمة، لا مكروهة، والسبب في ذلك والله أعلم أنهن في الغالب قليلات الصبر، وهن فتنة، فزيارتهن للقبور، واتباعهن للجنائز قد يفتن الناس وقد يسبب مشاكل على الرجال، فكان من رحمة الله  أن منعهن من الزيارة، وحرم عليهن زيارة القبور سداً لذريعة الفتنة بهن أو منهن. وقد صح عن رسول الله ﷺ أنه قال: ما تركت بعدي فتنة أضر على الرجال من النساء، وقول بعض الفقهاء: إنه يستثنى من ذلك قبر النبي ﷺ، وقبر صاحبيه رضي الله عنهما؛ قول بلا دليل، والصواب أن المنع يعم جميع القبور، حتى قبر النبي ﷺ، وحتى قبر صاحبيه رضي الله عنهما، هذا هو المعتمد من حيث الدليل. وأما الرجال فيستحب لهم زيارة القبور، وزيارة قبر النبي ﷺ، وقبر صاحبيه ﷺ، لكن بدون شد الرحل فالسنة أن تزار القبور في البلد من دون شد الرحل، لا يسافر لأجل الزيارة، ولكن إذا كان في المدينة زار قبر النبي ﷺ، وقبر صاحبيه، وزار البقيع، والشهداء. أما أن يشد الرحال من بعيد لأجل الزيارة فقط، فهذا لا يجوز على الصحيح من قولي العلماء، لقول النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد المسجد الحرام ومسجدي هذا والمسجد الأقصى. أما إذا شد الرحل إلى المسجد النبوي، فإن الزيارة تدخل تبعاً لذلك. فإذا وصل المسجد صلى فيه ما تيسر، ثم زار قبر النبي ﷺ، وزار قبر صاحبيه، ودعا له ﷺ، وصلى وسلم عليه ثم سلم على الصديق  ودعا له، ثم على الفاروق ودعا له. وهكذا السنة. وهكذا في القبور الأخرى، فلو زار مثلا دمشق، أو القاهرة، أو الرياض، أو أي بلد.. يستحب له زيارة القبور لما فيها من العظة. والنبي ﷺ قال: زوروا القبور فإنها تذكركم الآخرة فيزورها للذكرى، والعبرة، والدعاء للموتى، والترحم عليهم. وهذه هي السنة، من دون شد الرحل. ولكن لا يزورهم لدعائهم من دون الله. فدعاؤهم من دون الله شرك بالله . فكونه يدعوهم، أو يستغيث بهم، أو يذبح لهم، أو يتقرب إليهم بشيء من العبادة، أو يطلب منهم المدد، فهذا لا يجوز، وهذا من الشرك بالله ، فكما أنه لا يجوز مع الأصنام، ومع الأشجار والأحجار، فهكذا لا يجوز مع الموتى. فلا يدعو الصنم ولا يستجير به ولا يستغيث به، ولا الشجر، ولا الحجر، ولا الكوكب، وهكذا أصحاب القبور، لا يدعون مع الله، ولا يستغاث بهم، ولا يطلب منهم المدد. بل هذا شرك بالله ، كما قال الله : وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلَا تَدْعُوا مَعَ اللَّهِ أَحَدًا[الجن:18]، وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ  ۝  إِنْ تَدْعُوهُمْ لَا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ[فاطر:13-14]. فبين  أن دعاء العباد للموتى ونحوهم شرك به ، لقوله : وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ.. فجعل دعاءهم إياهم، أي: دعاء الموتى والاستغاثة بأصحاب القبور، شركاً بالله ، وهكذا قوله : وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ[المؤمنون:117]، فسمى دعاء غير الله كفراً، وحكم على أهله بأنهم كافرون وغير مفلحين فيجب على المسلم أن يحذر هذا، ويجب على العلماء أن يبينوا هذه الأمور، حتى يحذر الناس الشرك بالله. وكثير من العامة إذا مر بقبور من يعظمهم استغاث بهم، وقال المدد المدد يا فلان، أو يا سيدي فلان، المدد، المدد، أغثني، انصرني، اشف مريضي، وهذا هو الشرك الأكبر والعياذ بالله، وهذا إنما يطلب من الله ، لا من الموتى، ولا من الأصنام، ولا من الكواكب، وإنما يطلب من الله . أما الحي فإنه يطلب منه ما يقدر عليه، إذا كان حاضراً يسمع كلامه، أو عن طريق الكتابة، أو الهاتف، أو الإبراق، أو التلكس، أو ما أشبه ذلك من الأمور الحسية فيطلب منه ما يقدر عليه؛ تبرق له، أو تكتب له، أو تكلمه بالهاتف، وتقول: أقرضني كذا وكذا، أو ساعدني على عمارة بيتي، أو على إصلاح مزرعتي، فإذا كان بينك وبينه شيء من التعاون فلا بأس. أما أن تطلب من الميت أو الحي ما لا يقدر عليه، أو الغائب بدون الآلات الحسية، فهذا شرك به ؛ لأن دعاء الغائب من غير الآلات الحسية معناه اعتقاد أنه يعلم، وأنه يسمع دعاءك وإن بعدت، وهذا اعتقاد باطل، واعتقاد كفري، من اعتقد أن غير الله يعلم الغيب فهذا كفر أكبر. يقول الله جل وعلا: قُلْ لَا يَعْلَمُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ[النمل:65]، أو تعتقد أن الله جعل له سراً في الكون، فيتصرف؛ يعطي من يشاء، ويحرم من يشاء. كما يظنه بعض الجهلة، فهذا أيضاً شرك أكبر. فالزيارة للموتى زيارة إحسان، وزيارة ترحم عليهم، وتذكر للآخرة، والاستعداد لها. تذكر أنك ميت كما ماتوا فتستعد للآخرة، وتدعو لإخوانك المسلمين الميتين، وتترحم عليهم، وتستغفر لهم. وهذه هي الفائدة من الزيارة؛ ففيها عظة وذكرى ودعاء للموتى. كذلك لا يزور القبور من أجل أن يدعو عندها، فيجلس عندها ويدعو، أو من أجل الصدقة عندها، أو للقراءة عندها، فهذا غير مشروع، بل هذا من البدع. لكن يزورها للسلام عليهم، والدعاء لهم، والترحم عليهم؛ ولهذا كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، هكذا كان يعلمهم ﷺ. وكان إذا زار القبور هو ﷺ، قال: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون اللهم اغفر لأهل بقيع الغرقد هكذا جاء في حديث عائشة ما هذا معناه. والمقصود أن الزيارة للقبور في الحقيقة إحسان للموتى، وطلب للمغفرة لهم، والرحمة لهم، وإحسان لنفسك لأنك تذكر بهذا الآخرة، وتذكر الموت حتى تستعد للقاء الله . ولكن تكون هذه الزيارة كما تقدم بدون شد الرحل، بل تزور قبور أهل البلد التي أنت فيها، ويكون شد الرحل لغير ذلك، للمدينة يكون شد الرحل للمسجد، والصلاة فيه، والقراءة فيه، ونحو ذلك وإذا زار المسجد زار قبر النبي ﷺ، وسلم عليه وعلى صاحبيه، ويستحب له أن يزور البقيع كذلك، وقبور الشهداء، ويزور مسجد قباء ويصلي فيه أيضاً كل هذا مشروع. وهكذا إذا زار بعض البلاد الأخرى لتجارة، أو لصديق، أو لقريب، يستحب له أن يزور القبور حتى يدعو لأهلها، وحتى يترحم عليهم، وحتى يتذكر بهم الآخرة، وحتى يستعد لها، وحتى يتذكر الموت، هكذا بين أهل العلم، ودلت عليه الأحاديث الصحيحة عن رسول الله ﷺ. والخلاصة: أن زيارة القبور بالنسبة للنساء ممنوعة مطلقاً وهذا هو الصواب؛ لصحة الأحاديث بمنعهن وعدم الدليل على الاستثناء.","link":"https://binbaz.org.sa/fatwas/7751/حكم-زيارة-القبور-للنساء-وزيارتها-المشروعة-والممنوعة-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27101.mp3","categories":["زيارة القبور"]},{"id":9693,"question":"السؤال الثاني في رسالتهم: ما حكم الدين في زيارة القبور والتوسل بالأضرحة وأخذ خروف وأموال للتوسل بها كزيارة السيد البدوي والحسين والسيدة زينب أفيدونا أفادكم الله؟","title":"حكم زيارة القبور والأضرحة والتوسل بها","answer":"الجواب: زيارة القبور نوعان:\nأحدهما: سنة ومشروع ومطلوب، وهو أن يزورها للدعاء لهم والترحم عليهم وذكر الموت وذكر الآخرة هذا سنة، لقول النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة وكان النبي يزورها ﷺ، وهذا للرجال خاصة لا للنساء.\nالنوع الثاني: أن يزورها لدعاء أهلها والاستغاثة بهم أو للذبح لهم أو يولم بالذبائح هذا منكر وشرك أكبر نسأل الله العافية، ويلتحق بذلك أن يزورها للدعاء عندها والصلاة عندها والقراءة عندها هذا بدعة غير مشروع، فصارت في الحقيقة ثلاثة أنواع:\nالنوع الأول مشروع: وهو أن يزورها للذكرى والدعاء وتذكر الآخرة، هذه سنة.\nوالثاني: أن يزورها للقراءة عندها أو الصلاة عندها أو الذبح عندها لله هذه بدعة.\nالثالث: أن يزورها ليذبح للميت ويتقرب إليه بالذبائح، أو ليدعوه من دون الله ليطلبه المدد أو الغوث والنصر هذا شرك أكبر نسأل الله العافية فيجب الحذر من هذه الزيارات الخبيثة. نعم.","link":"https://binbaz.org.sa/fatwas/7839/حكم-زيارة-القبور-والاضرحة-والتوسل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19421.mp3","categories":["زيارة القبور","التوسل والشفاعة"]},{"id":9984,"question":"يسأل ثانية ويقول: إذا خرجت النساء إلى زيارة المقابر مع ذي محرم، فهل في هذا شيء، وهل قول الله  حَتَّى زُرْتُمُ الْمَقَابِرَ [التكاثر:2] من سورة التكاثر يخصص الزيارة للرجال فقط دون النساء، أفيدونا أفادكم الله؟","title":"حكم زيارة المرأة للمقابر، ومعنى: {حَتَّى زُرْتُمُ الْمَقَابِرَ}","answer":"الجواب: الزيارة تختص بالرجال، والرسول ﷺ نهى عن زيارة النساء للقبور وعن اتباعهن للجنائز، وصح عنه عليه السلام أنه لعن زائرات القبور، فليس للمرأة أن تزور القبور ولا أن تتبع الجنائز إلى المقبرة، نعم تصلي على الميت مع الناس في المسجد أو في المصلى أو في البيت تصلي على الميت لا بأس، أما الزيارة للمقابر أو الذهاب مع الناس إلى المقابر فلا يجوز لها ذلك، هذا هو الصحيح من أقوال أهل العلم.\nوأما قوله : أَلْهَاكُمُ التَّكَاثُرُ ۝ حَتَّى زُرْتُمُ الْمَقَابِرَ [التكاثر:1-2] فهذا المراد به الموت يعني: حتى نقلتم إلى المقابر ميتين، ليس المراد بالزيارة المعروفة، المقصود تحذير الناس من أن يشتغلوا بالتكاثر حتى يموتوا؛ فسماها زيارة لأن الإنسان ما يقيم في القبر دائماً هي زيارة ثم يخرج يوم القيامة إلى الجنة أو إلى النار.\nفالمقابر ما هي ... بالمحل الأخير، بل المحل الأخير الجنة أو النار، فالموتى زاروا القبور وبقوا في القبور حتى البعث والنشور، فإذا كان يوم القيامة أخرجوا من قبورهم وحاسبهم وجازاهم الله على أعمالهم، فالمتقون للجنة والكرامة، والكافرون للنار، والعصاة على خطر قد يعفى عنهم فيدخلوا الجنة، وقد يعاقبون على قدر معاصيهم ثم بعد المعاقبة وبعد التعذيب الذي يستحقونه يخرجهم الله من النار إلى الجنة عند أهل السنة والجماعة .\nفالحاصل أن قوله تعالى: أَلْهَاكُمُ التَّكَاثُرُ ۝ حَتَّى زُرْتُمُ الْمَقَابِرَ [التكاثر:1-2] ليس المراد به الزيارة المعروفة، المراد به هنا الموت، يعني: ألهاكم تكاثركم في الدنيا وحرصكم عليها حتى متم ونقلتم إلى القبور، الله سماها زيارة؛ لأنهم لا يقيمون في القبور أبداً بل هم زائرون وسوف يخرجون من القبور يوم القيامة إلى الجنة أو النار كما دلت عليه الآيات الكريمات والأحاديث الصحيحة، كما قال جل وعلا في كتابه العظيم: زَعَمَ الَّذِينَ كَفَرُوا أَنْ لَنْ يُبْعَثُوا قُلْ بَلَى وَرَبِّي لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ وَذَلِكَ عَلَى اللَّهِ يَسِيرٌ[التغابن:7] فالله يجمع الناس يوم القيامة ويبعثهم من قبورهم ثم يجازيهم بأعمالهم إن خيرًا فخير وإن شرًا فشر.\nفالواجب على كل مسلم وكل مسلمة الاستعداد لهذا اليوم، والحرص على الأعمال الصالحات حتى يسعد ويفوز بالنجاة يوم القيامة، وهذا واجب كل إنسان كل مكلف من أهل الأرض، يجب على جميع المكلفين من العرب والعجم والجن والإنس والكفار والمسلمين، يجب عليهم أن يستعدوا لهذا اليوم، وأن يدخلوا في الإسلام وأن يستقيموا على الإسلام حتى يفوزوا بالنجاة يوم القيامة، الله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/8148/حكم-زيارة-المراة-للمقابر-ومعنى-حتى-زرتم-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27413.mp3","categories":["زيارة القبور"]},{"id":10112,"question":"سماحة الشيخ! تفضلتم وقلتم: إن القبور تزار، هل ذلك مطلقًا، أم أنه للرجال فقط، أم أنه للرجال والنساء؟","title":"حكم زيارة القبور للنساء والرجال","answer":"الجواب: الزيارة للرجال، أما النساء فلا يشرع لهن الزيارة، بل لعن الرسول ﷺ زائرات القبور، فالواجب على النساء ترك ذلك؛ لأنهن فتنة، فالواجب عليهن ترك ما نهى عنه الرسول ﷺ، وإنما الزيارة للرجال خاصة، يقول ﷺ: زوروا القبور فإنها تذكركم الآخرة، وكان يزورها ﷺ، ويعلم أصحابه أن يزوروها، وكان يعلمهم ويقول عليه الصلاة والسلام، إذا زاروا القبور يقول لهم: قولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي حديث عائشة: يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد، كان إذا زارهم دعا لهم، والبقيع في المدينة مقبرة في المدينة، وقال في الحديث الصحيح: لعن الرسول ﷺ زوارات القبور، وفي الرواية الأخرى: لعن زائرات القبور.\nفالحاصل أن القبور يزورها الرجال للذكرى والترحم على أهلها والدعاء لهم، وذكر الموت وذكر الآخرة، ولا يدعون مع الله ولا يستغاث بهم، ولا ينذر لهم، ولا يذبح لهم، ولا يطلب منهم المدد والعون، كل هذا لا يجوز، بل هو من الشرك الأكبر، أما النساء فلا يزرن القبور، لكن الدعاء.. تدعو لأمواتها في بيتها في كل مكان، لكن لا تزور القبور، تدعو لهم بالمغفرة والرحمة في بيتها وفي مسجدها وفي كل مكان، أما القبور فلا تزار للنساء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8283/حكم-زيارة-القبور-للنساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33402.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":10434,"question":"حكم زيارة القبور للنساء، هل هو حلال أم حرام؟ وتقول: إنها سألت إمام الجامع لديهم عن الزيارة فقال: إنها حلال، ولكن بشرط أن يكون مع الزائرة محرم كالأخ والأب؟","title":"حكم زيارة المقابر للنساء","answer":"الجواب: الصواب: أنه لا تجوز الزيارة للنساء، وهذا الذي قاله من أفتاك قول ضعيف مرجوح، والصواب: أنها لا تجوز، لأن الرسولﷺ لعن زائرات القبور، فلا يجوز للمرأة أن تزور القبور والرسول ﷺ لعن من فعل ذلك من النساء، وإنما الزيارة من اختصاص الرجال، هذا هو الواجب. أما الصلاة على الميت فلا بأس تصلي على الأموات لا بأس، كان النساء يصلين على الأموات مع النبي ﷺ ولا حرج في هذا. وهكذا إذا صلى المسلمون على الغائب تصلي على الغائب إذا كان غائبًا صلوا عليه المسلمون؛ لأنه معروف بالعلم والفضل أو لأنه أمير مصلح نافع للمسلمين فصلى عليه المسلمون من أجل أنه قد حصل منه ما ينفع المسلمين واشتهر بالخير، كما صلى النبي ﷺ على النجاشي ملك الحبشة لما كان مسلمًا قد ساعد المسلمين وحماهم لما هاجروا إليه ونصرهم وآواهم.\nفإذا مات عالم مشهور نافع للمسلمين أو أمير صالح وملك صالح نافع للمسلمين، فلا مانع من الصلاة عليه صلاة الغائب وتصلي المرأة عليه مع الناس، أو في بيتها إذا صلى عليه المسلمون صلاة الغائب لا مانع أن تصلي عليه مثلهم. لكن لا تصلي على أحد لم يصل عليه المسلمون ولم يتقرر في الشرع أنه يصلى عليه؛ لأن ليس كل غائب يصلى عليه، إنما يصلى على الرجل الذي اشتهر بالنفع للمسلمين من أمير وحاكم وعالم ونحو ذلك. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8607/حكم-زيارة-المقابر-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34110.mp3","categories":["زيارة القبور"]},{"id":10562,"question":"من جمهورية مصر العربية محافظة سيناء أحد الإخوة المستمعين بعث برسالة يقول: إن عندنا أناس يزورون القبور وخاصة قبور الأولياء ويذبحون عندها الذبائح، فإذا قلت: هذه بدعة يقولون: ليست بدعة، نحن نعملها لله، هل هذا العمل وارد في السنة؟ وهل هو صحيح؟ أفيدونا أفادكم الله؟ وجزاكم الله خيراً.","title":"صفة الزيارة الشرعية للقبور","answer":"الجواب: زيارة القبور على الوجه الشرعي سنة، النبي عليه الصلاة والسلام قال: زوروا القبور فإنها تذكركم الآخرة فإذا زار القبر ليدعو له أو ليتذكر الآخرة والموت فهذا كله طيب، وقد زار النبي القبور عليه الصلاة والسلام ودعا لأهلها، وأمر الناس بالزيارة قال: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي حديث عائشة رضي الله عنه كان يقول: يرحم الله المستقدمين منا والمستأخرين.\nأما زيارتها لغير ذلك زيارتها لدعاء الموتى والاستغاثة بهم وطلب الشفاء منهم، أو النصر على الأعداء، فهذا يقال لها: زيارة شركية هذه زيارة منكرة، بل هي شرك أكبر؛ لأن دعاء الأموات والاستغاثة بالأموات والنذر لهم شرك أكبر، وهكذا الذبح لهم، كونه يذبح بقرة أو بعير أو شاة أو دجاجة يتقرب بها إلى الميت يرجو شفاعته أو يرجو بركته هذا شرك أكبر؛ لأن الله يقول سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] والنسك: يطلق على الذبح والعبادة، ويقول جل وعلا: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، ويقول النبي ﷺ: لعن الله من ذبح لغير الله.\nفليس لأحد أن يذبح للأصنام أو للأولياء أو للجن لقصد التقرب إليهم لطلب شفاعتهم أو نصرهم على الأعداء، أو لطلب إغاثتهم، أو ليشفوا مريضه، أو يردوا غائبه، أو يعطوه الولد أو ما أشبه هذا مما يفعله عباد القبور وعباد الأولياء وعباد الأصنام.\nأما الذبح عند القبور لله لا للأولياء لله يتقرب إلى الله فهذه بدعة، القبور ما هي محل ذبح عندها هذا توسيخ لها وتقذير وإيذاء، الذبح يذبح في بيته أو في المجزرة، ويوزع على الفقراء اللحوم هذا لا بأس به إن أراد بذلك الصدقة على الفقراء والتقرب إلى الله بما يذبحه، الضحية والهدية في منى، والضحية في بيته هذا لا بأس، أما أن يأتي بالذبيحة عند القبور هذا بدعة، وتلويث للقبور وإيذاء لها وإيذاء للزوار أيضاً، والغالب على هؤلاء أنهم ما يأتون بها إلى القبور إلا لاعتقادهم في هذه القبور وقصد التقرب إليهم بهذا، لكن إذا كانوا صادقين وأنهم ما قصدوا إلا التقرب إلى الله والذبح لله لا للأموات فهذا يكون بدعة، أما إن أرادوا بالذبيحة التقرب للميت ليشفع لهم، أو ليشفي مريضهم، أو ليعطيهم كذا، هذا الشرك الأكبر، العقيدة فاسدة والذبح شرك كله، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8737/صفة-الزيارة-الشرعية-للقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32207.mp3","categories":["زيارة القبور"]},{"id":10565,"question":"من جمهورية مصر العربية محافظة سيناء أحد الإخوة المستمعين بعث برسالة يقول: إن عندنا أناس يزورون القبور وخاصة قبور الأولياء ويذبحون عندها الذبائح، فإذا قلت: هذه بدعة يقولون: ليست بدعة، نحن نعملها لله، هل هذا العمل وارد في السنة؟ وهل هو صحيح؟ أفيدونا أفادكم الله؟ وجزاكم الله خيراً.","title":"صفة الزيارة الشرعية للقبور","answer":"الجواب: زيارة القبور على الوجه الشرعي سنة، النبي عليه الصلاة والسلام قال: زوروا القبور فإنها تذكركم الآخرة فإذا زار القبر ليدعو له أو ليتذكر الآخرة والموت فهذا كله طيب، وقد زار النبي القبور عليه الصلاة والسلام ودعا لأهلها، وأمر الناس بالزيارة قال: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وفي حديث عائشة رضي الله عنه كان يقول: يرحم الله المستقدمين منا والمستأخرين.\nأما زيارتها لغير ذلك زيارتها لدعاء الموتى والاستغاثة بهم وطلب الشفاء منهم، أو النصر على الأعداء، فهذا يقال لها: زيارة شركية هذه زيارة منكرة، بل هي شرك أكبر؛ لأن دعاء الأموات والاستغاثة بالأموات والنذر لهم شرك أكبر، وهكذا الذبح لهم، كونه يذبح بقرة أو بعير أو شاة أو دجاجة يتقرب بها إلى الميت يرجو شفاعته أو يرجو بركته هذا شرك أكبر؛ لأن الله يقول سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] والنسك: يطلق على الذبح والعبادة، ويقول جل وعلا: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، ويقول النبي ﷺ: لعن الله من ذبح لغير الله.\nفليس لأحد أن يذبح للأصنام أو للأولياء أو للجن لقصد التقرب إليهم لطلب شفاعتهم أو نصرهم على الأعداء، أو لطلب إغاثتهم، أو ليشفوا مريضه، أو يردوا غائبه، أو يعطوه الولد أو ما أشبه هذا مما يفعله عباد القبور وعباد الأولياء وعباد الأصنام.\nأما الذبح عند القبور لله لا للأولياء لله يتقرب إلى الله فهذه بدعة، القبور ما هي محل ذبح عندها هذا توسيخ لها وتقذير وإيذاء، الذبح يذبح في بيته أو في المجزرة، ويوزع على الفقراء اللحوم هذا لا بأس به إن أراد بذلك الصدقة على الفقراء والتقرب إلى الله بما يذبحه، الضحية والهدية في منى، والضحية في بيته هذا لا بأس، أما أن يأتي بالذبيحة عند القبور هذا بدعة، وتلويث للقبور وإيذاء لها وإيذاء للزوار أيضاً، والغالب على هؤلاء أنهم ما يأتون بها إلى القبور إلا لاعتقادهم في هذه القبور وقصد التقرب إليهم بهذا، لكن إذا كانوا صادقين وأنهم ما قصدوا إلا التقرب إلى الله والذبح لله لا للأموات فهذا يكون بدعة، أما إن أرادوا بالذبيحة التقرب للميت ليشفع لهم، أو ليشفي مريضهم، أو ليعطيهم كذا، هذا الشرك الأكبر، العقيدة فاسدة والذبح شرك كله، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8737/صفة-الزيارة-الشرعية-للقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32207.mp3","categories":["زيارة القبور"]},{"id":10796,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول: تقوم بعض النساء عندنا بزيارة القبور والمساجد، ومن خلال الزيارة يقمن بجمع الأطفال داخل المسجد، أو على القبور، ويفرقن عليهم خبزًا، وبعض الأشياء، ويقلن: لوجه الله، ثم يقمن بدعاء الولي الذي زرن لأجله، ويقلن: يا ولي عافني، واحفظ أولادي، وكثيرًا من الدعاء، فما رأيكم -يا سماحة الشيخ- في هذا العمل؟","title":"حكم زيارة المرأة للمشاهد والقبور ودعائها الأولياء","answer":"الجواب:  هذا عمل خطير، يجب الحذر منه، النساء ممنوعات من زيارة القبور، وإنما الإذن للرجال، يقول ﷺ: زوروا القبور فإنها تذكركم الآخرة ولعن زائرات القبور من النساء؛ لأنهن فتنة، وصبرهن قليل، أما إذا كان مع ذلك دعوة الموتى، والاستغاثة بالموتى صار شركًا أكبر، صار الشرك الأكبر، هكذا الذبح لهم، طلبهم المدد، هذا شرك أكبر من الرجال والنساء جميعًا، فالذي يأتي القبور ليدعوها من دون الله، ويطلبها النصر والمدد والعون، هذا أتى شركًا عظيمًا من الرجال والنساء جميعًا، وهذا شرك المشركين، هذا شرك عباد القبور، كـأبي جهل، وأصحابه من عباد القبور، وهكذا توزيع الصدقات إذا كان يقصد بهذا التقرب إلى الموتى بذلك، وأنه يتصدق، ينوي التقرب بالصدقة لهم، يعتقد أنهم ينفعونه، يتصدق عند قبورهم، وأنهم بهذه الصدقة التي يتقرب بها إليهم ينفعونه؛ مثل لو صلى لهم. وأما إن كان لا، صدقة يطلب من الله ثوابها، ولكن يظن ويعتقد أنها عند القبور أفضل، هذه بدعة، ما هي عند القبور أفضل، الصدقة يتصدق في بيته في أي محل، وإذا كانت عن طريق السر كان أفضل إلا إذا دعت الحاجة إلى الجهر، ولكن ليس محلها القبور؛ في الأسواق.. البيت.. في أي مكان في المسجد لمن سأل لا بأس. والخلاصة أن زيارة النساء للقبور لا تجوز، وكونهن يذبحن للأموات، أو يطلبن منهم المدد، أو الغوث، أو شفاء المرضى، هذا شرك أكبر، سواء وقع من امرأة، أو من الرجل، حتى ولو فعله في بيته، ما هو بعند القبور، يا سيدي فلان! يا عبدالقادر! يا حسين! يا علي! يا رسول الله! ولو في بيته، ولو في أي مكان بعيد عن المدن والقبور فهو شرك أكبر، ولو أنه في الصحراء ما عنده أحد، إذا قال: يا رسول الله! انصرني، أو يا رسول الله! اشف مريضي، أو ما أشبه ذلك فقد عبده من دون الله بهذا الدعاء، أو قال: يا سيدي الحسين! أو يا سيدي الحسن! أو يا سيدي علي! أو يا سيدي عبدالقادر! أو أحمد البدوي، أو ما أشبه ذلك، يطلبه المدد والعون، والغوث، هذا من الشرك الأكبر. وهكذا إذا تقرب له بالذبائح، سواء عند قبره، أو بعيدًا عن قبره، يذبح من أجل التقرب إليه، يرى أنه إذا ذبح له يمده بأشياء، أو يعطيه أشياء، أو يحصل له أشياء، فالذبح لغير الله شرك أكبر، قال تعالى: قُلْ إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ [الأنعام:162] لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:163] قال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] فأمر بالصلاة والنحر لله . وقال -عليه الصلاة والسلام-: لعن الله من ذبح لغير الله فالذبح عبادة عظيمة كالصلاة، فإذا ذبح لأصحاب القبور، وتقرب إليهم بذلك يرجو شفاعتهم، ويرجو أنهم يقربونه من الله زلفى، أو تصدق يطلب الأجر منهم، والثواب منهم، أو حج لقبورهم، أو ما أشبه ذلك من المقاصد التي يفعلها، يتقرب بها إلى أصحاب القبور، هو يكون بهذا قد عبدهم، وجعلهم آلهة يعبدهم مع الله بصلاته لهم، أو دعائه لهم، أو ذبحه لهم، أو نذره لهم، أو غير ذلك، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8977/حكم-زيارة-المراة-للمشاهد-والقبور-ودعاىها-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35207.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":10811,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمعة أم هديل من العراق محافظة نينوى، أم هديل عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: إنني أصوم وأصلي وأقرأ القرآن، وعندي إيمان قوي بالله، ولكني عندما أتذكر زوجي وابنتي التي تسأل عن أبيها أبكي بكاء بشدة، وقد أخبرتكم أن زوجي قتل في الحرب، أذهب إلى قبره هل هذا حرام على المرأة أن تزور القبور؟ علمًا بأنني عندما أذهب إلى قبره أرتاح، وأكف عن البكاء، هل الموتى يرون الأحياء كما يقال؟ وجهوني حول هذه القضايا، جزاكم الله خيرًا.","title":"حكم زيارة النساء للقبور والبكاء على الميت","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فأسأل الله لك الثبات على الحق، قد سرني كثيرًا ما ذكرت من استقامتك على طاعة الله، وأبشري بالخير، وعليك بالثبات على الحق، والاستقامة على توحيد الله، والإخلاص له، والمحافظة على الصلاة في أوقاتها، وصوم رمضان، وأداء الزكاة، وغير هذا مما أوجب الله عليك، مع الحفاظ على الحجاب، والبعد عن أسباب الفتنة. أما زيارة القبر.. زيارة قبر زوجك، وزيارة القبور الصواب أنها لا تشرع للنساء، بل تمنع عنها النساء، وإنما تشرع للرجال، لقوله ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة ولعن زائرات القبور -عليه الصلاة والسلام- من النساء. فالواجب عدم الذهاب إلى القبور، وادعي له كثيرًا في بيتك، وأحسني إليه بالدعاء والصدقة عنه، وأما زيارة قبره فلا حاجة إلى ذلك، والنياحة على الميت من الكبائر، وتضره أيضًا، أما دمع العين فلا يضر، دمع العين بدون صوت لا بأس عند التذكر، تدمع العين لا بأس، النبي ﷺ لما مات ابنه إبراهيم دمعت عينه، وقال: العين تدمع، والقلب يحزن، ولا نقول إلا ما يرضي الرب، وإنا بفراقك يا إبراهيم! لمحزونون.  فنوصيك بالصبر الجميل، والدعاء له بالمغفرة والرحمة إذا كان مات على خير، وعلى صلاة، وعلى صلاح والحمد لله، احمدي الله أنه مات على الإسلام، وعلى المحافظة على الصلاة، ولا تجزعي، بل سلي الله له العفو والمغفرة والرحمة، وأحسني التربية لابنته، وأبشري بالخير العظيم، والثواب الجزيل، والصدقة كذلك تنفعه من مالك، نعم. المقدم: جزاكم الله خيرًا! هذا إن كان لا يصلي كما ذكرت في سؤال سابق سماحة الشيخ؟  الشيخ: هذا غيره، لا، هذا غيره. المقدم: لا هذا نفس الرسالة. الشيخ: نعم. المقدم: نفس الرسالة. الشيخ: أما إذا كان لا يصلي لا، أما إذا كان لا يصلي فإنها لا تدعو له، ولا تتصدق عنه؛ لأن الذي يترك الصلاة سبق أنه كافر في أصح قولي العلماء، ولو أقر بالوجوب، لقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة فالأمر خطير وعظيم، ولا حول ولا قوة إلا بالله. وعليها هي.. عليك أنت أيها السائلة! الحرص على أداء الصلاة، والمحافظة عليها، وسؤال الله الثبات، والتوبة عما سلف من التساهل مع زوجك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8979/حكم-زيارة-النساء-للقبور-والبكاء-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35301.mp3","categories":["زيارة القبور"]},{"id":10943,"question":"المستمع محمود مظهور حمد من العراق نينوى بعث يسأل ويقول: لزيارة القبور هل يجوز قراءة الفاتحة عند وصولي إلى المقبرة، أو قراءة الفاتحة بعد الزيارة؟","title":"ما يشرع عند زيارة القبور وما لا يشرع","answer":"الجواب:  لا تشرع قراءة الفاتحة ولا غيرها من السور، إذا زار المؤمن القبور يسلم عليها فقط هذا المشروع، أما كونه يقرأ الفاتحة أو غيرها من القرآن فليس لهذا أصل، والرسول -عليه الصلاة والسلام- قال: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا، فالقبور ليست محل صلاة، ولا محل قراءة، وقال: إن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة، فالقرآن محله المساجد والبيوت، وليس محله القبور، فلا يقرأ في المقبرة لا الفاتحة ولا غيرها.  والأحاديث التي يرويها بعض الناس في القراءة في المقابر، وأنها تنفع الموتى، كل هذا لا أصل له، كل ذلك لا أصل له، كلها غير صحيحة، وإنما السنة لمن زار القبور أن يسلم عليهم السلام المشروع، وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية ولم يعلمهم أن يقرؤوا الفاتحة أو غيرها من القرآن، هكذا كان يعلمهم ويقول لهم: قولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، وكان -عليه الصلاة والسلام- إذا زارها يقول: السلام عليكم دار قوم مؤمنين وإنا -إن شاء الله- بكم لاحقون، يغفر الله لنا ولكم، وفي رواية: يرحم الله المستقدمين منا والمستأخرين هذه الدعوات التي تقال عند الزيارة: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية، غفر الله لنا ولكم، وما أشبه هذا الكلام، هذا هو السنة، أما القراءة فلا، فلا أصل لها ولا تشرع، نعم. المقدم: لا قبل الزيارة، ولا بعدها؟ الشيخ: لا عند الزيارة، ولا في حال الزيارة، ولا بعد الزيارة بالمقبرة يعني. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9124/ما-يشرع-عند-زيارة-القبور-وما-لا-يشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36308.mp3","categories":["زيارة القبور"]},{"id":10946,"question":"يسأل سؤالًا آخر حول الموضوع تقريبًا، يقول: هل الشخص الميت يراك أثناء زيارتك إلى قبره، أم لا؟ وهل الزيارة يوم الإثنين أو الخميس؟ وهل تجوز في باقي الأيام؟","title":"هل الموتى يرون من زارهم وقت الزيارة؟","answer":"الجواب:  الزيارة في كل وقت، جميع الأوقات ليس لها وقت معين، في جميع أيام الأسبوع في الليل والنهار، متى تيسر له الزيارة زار. أما كون الميت يراه فلا أصل لهذا، الميت انتهى أمره، وحيل بينه وبين ذلك، وروحه إما في الجنة إن كان مؤمنًا، وإما في النار إن كان كافرًا، والعاصي على خطر من ذلك، وليس هناك دليل على أن الميت يرى زائره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9125/هل-الموتى-يرون-من-زارهم-وقت-الزيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36309.mp3","categories":["زيارة القبور","عذاب القبر ونعيمه "]},{"id":11105,"question":"له الفقرة الثانية -يا سماحة الشيخ- يقول: هل من الجائز قيام النساء بزيارة للقبور؟","title":"زيارة النساء للقبور منكر","answer":"الجواب:  لا. ليس من الجائز، بل منكر، الرسول ﷺ لعن زائرات القبور، فزيارتهن ما تسمى بدعة، لكن إذا كن قصدن التقرب بذلك يكون بدعة من هذه الحيثية، وإلا هي معصية؛ لأنها وقوع فيما نهى عنه الرسول ﷺ فالنساء منهيات عن زيارة القبور، بل ملعونات، فلا يجوز لهن زيارة القبور، ولو تقربن بهذا لكانت القربة بدعة؛ لأنه تقرب بشيء نهى الله عنه. نعم.","link":"https://binbaz.org.sa/fatwas/9282/زيارة-النساء-للقبور-منكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29012.mp3","categories":["زيارة القبور"]},{"id":11121,"question":"له الفقرة الثانية -يا سماحة الشيخ- يقول: هل من الجائز قيام النساء بزيارة للقبور؟","title":"زيارة النساء للقبور منكر","answer":"الجواب:  لا. ليس من الجائز، بل منكر، الرسول ﷺ لعن زائرات القبور، فزيارتهن ما تسمى بدعة، لكن إذا كن قصدن التقرب بذلك يكون بدعة من هذه الحيثية، وإلا هي معصية؛ لأنها وقوع فيما نهى عنه الرسول ﷺ فالنساء منهيات عن زيارة القبور، بل ملعونات، فلا يجوز لهن زيارة القبور، ولو تقربن بهذا لكانت القربة بدعة؛ لأنه تقرب بشيء نهى الله عنه. نعم.","link":"https://binbaz.org.sa/fatwas/9282/زيارة-النساء-للقبور-منكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29012.mp3","categories":["زيارة القبور"]},{"id":11393,"question":"هل يجوز للنساء أن تزور القبور من أجل الزيارة فقط والتسليم على أهلهم الذين سبقوهم مع عدم البكاء عليهم؟ أفيدونا أفادكم الله.","title":"لعن الرسول صلى الله عليه وسلم زائرات القبور","answer":"الجواب:  الزيارة للنساء لا تجوز، إنما يصلين على الميت مع الناس ما يخالف، الصلاة على الميت لا بأس بها، قد صلى النساء على الميت مع النبي ﷺ، لكن زيارة القبور منهي عنها، ليس للنساء أن يزرن القبور؛ لأن الرسول لعن زائرات القبور -عليه الصلاة والسلام- قال: لعن الله زائرات القبور فلا يجوز لهن الزيارة، ولكن يدعون لأمواتهم في البيت، والطريق، وفي كل مكان، الدعاء مطلوب، أما الزيارة للقبور فلا، نعم.","link":"https://binbaz.org.sa/fatwas/9565/لعن-الرسول-صلى-الله-عليه-وسلم-زاىرات-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29313.mp3","categories":["زيارة القبور"]},{"id":11680,"question":"يسأل أخونا عن الآداب التي يجب الإحاطة بها عند زيارة المقابر، وهل حث الإسلام على زيارة القبور، وزارها النبي ﷺ والصحابة، وأجاز للنساء زيارة القبور؟ وهل جاء في القرآن الكريم شيء عن زيارة قبور الصالحين، كما قال تعالى: وَلا تُصَلِّ عَلَى أَحَدٍ مِنْهُمْ مَاتَ أَبَدًا وَلا تَقُمْ عَلَى قَبْرِهِ [التوبة:84]؟ وجهونا جزاكم الله خيرًا.","title":"آداب زيارة القبور ومشروعية زيارتها وبيان الزيارة المحرمة","answer":"الجواب:  زيارة القبور سنة مؤكدة من فعل النبي وقوله -عليه الصلاة والسلام- لما فيها من التذكير بالموت، والتذكير بالآخرة، والسنة أن يزورها المؤمن بخشوع ورغبة في الآخرة، وقصد للاعتبار والذكر، ورحمة الأموات والدعاء لهم؛ لقوله ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة خرجه مسلم في صحيحه: زوروا القبور، فإنها تذكركم الآخرة. وكان النبي -عليه الصلاة والسلام- يزورها بين وقت وآخر في الليل، والنهار يزورها، ويسلم عليهم -عليه الصلاة والسلام- ويدعو لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية، يغفر الله لنا ولكم كان هذا من فعله -عليه الصلاة والسلام-فالمؤمن يسن له أن يزورها؛ لفعل النبي ﷺ ولقوله، قوله: زوروا القبور، فإنها تذكركم الآخرة. والمقصود من الزيارة الدعاء لهم الدعاء للميتين بالمغفرة والرحمة، وذكر الآخرة، وذكر الموت، والتأهب لذلك، هذا المقصود. ومن آدابها: أنه لا يصلي عند القبور، ولا يجلس عندها للدعاء والقراءة، إنما يسلم بخشوع ورغبة في الآخرة، وخوف من عذاب الله، وقصد علاج قلبه حتى لا يموت؛ لأنه إذا تذكر الموت والقبور؛ صار هذا أدعى لاستعداده للآخرة، وألين للقلب، يذكر الموت، ويذكر الآخرة، ويذكر جمع الناس يوم القيامة، فيلين قلبه، فزيارة القبور تلين القلوب، وتذكرها بالآخرة وبالموت، فيكون ذلك من أسباب الاستعداد، والحذر من الركون إلى الدنيا، لكن لا يصلي عندها، ولا يطوف بها، ولا يسأل أهلها شيئًا، الصلاة عندها بدعة، من وسائل الشرك، والقراءة عندها بدعة، والجلوس عندها للدعاء بدعة، أما الطواف بها فشرك بالله، إذا طاف يتقرب إلى أصحاب القبور فهذا شرك أكبر، كالدعاء، كدعائها والاستغاثة بأهلها، والنذر لهم، والذبح لهم هذا شرك أكبر، كما يفعل عند بعض القبور. يقول: يا سيدي انصرني، أو اشف مريضي، أو أنا في حسبك، أو اشفع لي، أو ما أشبه ذلك، كل هذا من الشرك الأكبر، لا عند قبر النبي ﷺ ولا عند قبر الصحابة، ولا عند غيرهم، إنما يسلم عليهم، ويدعو لهم، يقول: السلام عليكم أهل القبور .. السلام عليكم دار قوم مؤمنين وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية هكذا. وليس للمؤمن أن يسألهم، أو يستغيث بهم، أو ينذر لهم، أو يذبح لهم، كل هذا من الشرك الأكبر، ولا يطوف تقربًا إليهم، فهذا شركاً أكبر، أما لو طاف يحسب أنه مشروع، يقصد التقرب إلى الله بالطواف، هذا بدعة منكر؛ لأنه من وسائل الشرك الطواف خاص بالكعبة. أما إذا طاف يتقرب إليهم، ويريد شفاعتهم، أو من أجل ينفعوه؛ فهذا شرك أكبر، كدعائهم من دون الله، والاستغاثة بهم، والنذر لهم، كله شرك أكبر، كما يفعل عند البدوي، وعند الشيخ عبدالقادر في العراق، أو عند قبر أبي حنيفة، أو عند قبر الحسن والحسين، عند قبر الحسين في مصر، كل هذا شرك أكبر، دعاؤهم والاستغاثة بهم والنذر لهم،. وهكذا ما يفعله بعض الجهال عند قبر النبي ﷺ من دعائه، والاستغاثة به، وطلبه النصر، طلبه شفاء المرضى كل ذلك من الشرك الأكبر، نسأل الله العافية، أما النساء فلا، أما النساء فليس لهم زيارة القبور، النساء لا يزرن القبور؛ لأن الرسول ﷺ نهاهن عن هذا، ولعن زائرات القبور؛ ولأنهن فتنة وصبرهن قليل. وأما قوله: وَلا تَقُمْ عَلَى قَبْرِهِ [التوبة:84] فهذا نهي للرسول ﷺ عن الوقوف على قبور المنافقين، والصلاة عليهم، أما المسلم يوقف على قبره، ويدعى له بعد الدفن، إذا دفن يوقف عليه، ويسأل له التثبيت والمغفرة، لقول النبي ﷺ.. لأنه كان إذا فرغ من دفن الميت -عليه الصلاة والسلام- قال: استغفروا لأخيكم، واسألوا له التثبيت كان هذا يفعله ﷺ فإذا فرغ من دفن الميت، وقف عليه، وقال: استغفروا لأخيكم، واسألوا له التثبيت، فإنه الآن يسأل. فالمؤمن يوقف عند قبره، ويسأل له المغفرة والثبات، أما المنافق فلا، لا يصلى عليه، ولا يوقف عند قبره، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9866/اداب-زيارة-القبور-ومشروعية-زيارتها-وبيان-الزيارة-المحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39014.mp3","categories":["زيارة القبور"]},{"id":12258,"question":"مستمع من العراق بعث يسأل ويقول: إني المستمع نشوان عبدالحميد من العراق، نينوى، أرجو الإجابة عن هذه الأسئلة، جزاكم الله خيرًا عند زيارتي للقبور، أجد بعض الأشخاص يقرؤون القرآن عند قبور موتاهم، فهل تجوز قراءة القرآن عند القبر، أم لا؟","title":"هل تجوز قراءة القرآن عند القبر، أم لا؟","answer":"الجواب:  لا تجوز القراءة عند قبره، ولا دليل عليها، ولهذا قال -عليه الصلاة والسلام-: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة فدل على أن القبور لا تتخذ مصلى، ولا مسجدًا، ولا محلًا للقراءة، وإنما يسلم عليهم المؤمن، يقول: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم اللهه المستقدمين منا والمستأخرين، اللهم اغفر لهم وارحمهم هكذا يسلم عليهم: السلام عليكم دار قوم مؤمنين أو يقول: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين ويدعو لهم بالمغفرة والرحمة، هذا هو المشروع. أما أنه يأتي بقراءة عند القبور، أو يجلس عندها للصلاة، أو يتخذها محلًا للدعاء، يرى أن الدعاء عندها أفضل من غيره، أو أقرب للإجابة، هذا غلط، إنما يدعو لهم فقط وينصرف. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10458/هل-تجوز-قراءة-القران-عند-القبر-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44909.mp3","categories":["زيارة القبور"]},{"id":12335,"question":"المستمع (ماهر . ع. ح) من محافظة المنيا بمصر بعث برسالة يقول فيها: بعض الناس عندنا يؤكدون أن زيارة قبور المشايخ حلال، وليس فيها شيء من البدعة، وأقصد بقبور المشايخ: الشيخ البدوي، والإمام الحسين، والعباس، والسيدة زينب، والشيخ عبدالقادر الجيلاني، وغيرهم، وليس هذا فحسب، بل إنهم يروجون بعض الحكايات عن الإمام الحسين بأنه يرد السلام بصوت جهوري، ويعتذر عندما لا يرد السلام، ويبين السبب الذي غالبًا ما يكون اجتماعه مع رسول الله ﷺ والناس عندنا يصدقون ذلك، وينساقون وراء زيارتهم، والتبرك بهم، ونريد إلى جانب الإجابة على سؤالنا وهو موقف الإسلام من زيارة قبور المشايخ والصالحين، كلمة توجيهية لمن يقومون بزيارة هذه القبور، ويتبركون بأصحابها، جزاكم الله خيرًا.","title":"أنواع زيارة القبور وأحكامها","answer":"الجواب:  الزيارة زيارتان: زيارة بدعية، وزيارة شرعية، أما زيارة القبور للدعاء للميت، والترحم عليه، وذكر الآخرة، فهذا شيء مشروع، يقول النبي ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة وكان النبي يزور البقيع، ويدعو لأهل البقيع -عليه الصلاة والسلام- ويزور الشهداء، ويدعو لهم، فزيارة المشايخ من العلماء والأخيار، أو عموم المسلمين زيارة القبور للدعاء لهم، والترحم عليهم، وذكر الآخرة أمر مشروع؛ لأن الإنسان إذا زار القبور؛ يتذكر الموت؛ يتذكر الآخرة، يحصل له بذلك إعداد للآخرة، ونشاطه في الخير، والعمل الصالح، ولا فرق في ذلك بين زيارة قبور العلماء، أو عامة الناس، فإذا زار قبر الحسين، أو قبر البدوي، أو قبر الست زينب، أو غير ذلك للذكرى، ذكر الآخرة، والدعاء لهم، والترحم عليهم، هذا من الزيارة الشرعية. أما الزيارة الثانية البدعية: فهي التي تقع من أجل التبرك بالمزور، والتمسح بقبره، أو الطواف بقبره، أو الاستغاثة به، بأن يقول: يا سيدي المدد المدد، أو الشفاعة الشفاعة، أو الغوث الغوث، هذه زيارة بدعية منكرة، بل شركية إن صار فيها دعاء، أو استغاثة؛ صار شركًا أكبر، وهذا دين المشركين، دين أبي جهل وأشباهه، مع اللات والعزى ومناة يدعونهم ويستغيثون بهم هذا هو الشرك الأكبر، فالذي يزور الحسين ليدعوه مع الله، ليستغيث به، الذي ينذر له، الذي يطلبه المدد، أو البدوي، أو العباس، أو زينب، أو غير ذلك؛ فهذا كله شرك أكبر، والذي يسمع من الصوت ليس صوت الحسين، ولا صوت البدوي، ولا غيره، ولكنهم الشياطين يدعونهم إلى الغلو في هؤلاء، فيسمعون أصوات الشياطين الذين يدعون إلى الشر، من شياطين الجن التي تدعو إلى الشرك بالله، وعبادة غير الله.  فرد السلام من الميت ليس معناه أنه يسمع، وفي رده خلاف بين أهل العلم، منهم من أثبت رده، ولكنه شيء لا يسمع، ومنهم من لم يثبت ذلك، قد صح عنه ﷺ أنه قال: ما من أحد يسلم علي إلا رد الله علي روحي حتى أرد عليه السلام والناس لا يسمعون رد السلام منه -عليه الصلاة والسلام- وفي الحديث الآخر: إن لله ملائكة يبلغوني عن أمتي السلام -عليه الصلاة والسلام- فهو يرد عليهم وإن لم يسمعوه.  وهكذا الميت جاء في بعض الروايات أن العبد إذا زار ميتًا كان يعرفه في الدنيا، وسلم عليه؛ فرد عليه السلام، لكن ليس معنى هذا أنه يسمع صوته، وإنما الروح ترد السلام، وأما الجسد قد فني، وأتى عليه البلى، أو أتى على بعضه البلى، وإنما هي الأرواح. ورد السلام ليس يسمع من الميت، ورد السلام أيضًا لا يوجب دعاءه، والاستغاثة به، فإذا رد السلام، أو ما رد السلام هذا لا يتعلق به حكم شرعي، وإنما الحكم يتعلق بدعائك الميت والاستغاثة بالميت، هذا شرك أكبر، أو طلبه المدد، أو العون، أو الشفاعة هذا من الشرك الأكبر، حتى ولو رد السلام حتى لو قدرنا أنك سمعت رد السلام، لا يجوز لك أن تدعوه من دون الله، ولا أن تستغيث به، ولا أن تنذر له، ولا أن تطلبه المدد والعون، كل هذا عبادة لغير الله من الأموات، أو من الأصنام، أو الأشجار، أو الأحجار، كل هذا لا يجوز، وهذا هو عمل المشركين الأولين، فالواجب الحذر من ذلك. وهكذا التبرك بالقبور بترابها، وأحجارها، وشبكها لا يجوز، وإن أراد بهذا طلب البركة منهم، وأنهم يعطونه بركة، ويمدونه بالبركة؛ صار هذا نوعًا من عبادتهم من دون الله، ونوعًا من طلب البركة بالفعل، فلا يجوز ذلك، وإنما الزيارة لذكر الآخرة، والترحم على الميت، كما قال النبي ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة. فالمؤمن يزورها ليتذكر الآخرة، وليدعو لهم، هم في حاجة إلى الدعاء، يدعو لهم، يترحم عليهم، يسأل الله لهم المغفرة والرحمة والعفو، هكذا الزيارة الشرعية. فيجب على كل من يدعي الإسلام أن يحذر ما ينقض إسلامه، ويفسد عليه إسلامه من الشرك بالله  ويجب على الجاهل أن يسأل أهل العلم، ويبصروه، وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكمم العافية، يرحم الله المستقدمين منا والمستأخرين ويقول عند زيارة أهل البقيع: اللهم اغفر لأهل بقيع الغرقد يدعو لهم، ويترحم عليهم، هذه الزيارة الشرعية.  فالواجب على كل مسلم أن يلتزم بهذه الزيارة الشرعية، وأن يحذر الزيارات البدعية، والشركية التي يفعلها الجهال مع كثير من القبور، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10535/انواع-زيارة-القبور-واحكامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45408.mp3","categories":["زيارة القبور"]},{"id":12383,"question":"يقول: أمي تذهب إلى المقابر مع جمع من النساء، وهذا في كل عام، ويذهبون بالأكل والأطعمة، وما أشبه ذلك، وقد غضبت من هذا العمل، ونصحتها، ولكنها لم تنته، بماذا توجهونني؟ جزاكم الله خيرًا.","title":"حكم زيارة المقابر للنساء","answer":"الجواب:  نوصيك بالاستمرار في النصيحة، وطلب النصيحة من أهل العلم عندكم حتى ينصحوهم، حتى ينصحوا أمك ومن معها، لأن الرسول ﷺ: لعن زائرات القبور فلا يجوز للنساء زيارة القبور، لا في السنة، ولا في أقل من السنة. الرسول ﷺ: لعن زائرات القبور فأنت تنصحهن، وتقول: ليس لهن الزيارة للقبور، ولكن يشرع لهن الدعاء للأموات في بيوتهن، وفي كل مكان، الدعاء طيب، أما زيارة القبور للنساء فهذه منهي عنها، والرسول ﷺ: لعن زائرات القبور فأنت تستمر في النصيحة، وتطلب من إخوانك، أو جيرانك الطيبين، أو بعض أهل العلم الذين عندكم أن ينصحوهن، وأن يبينوا لهن أن ذلك لا يجوز، ولا مانع أن تقرأ عليهن بعض الكتب التي تتحدث ذلك بيان منع الزيارة للنساء، وعندكم كتابي التحقيق والإيضاح لو قرأت عليهن ما ذكرته فيه لعلهن يستجبن لذلك، وكذلك ما يذاع في إذاعة القرآن في هذا البرنامج إذا أسمعتهن إياه؛ لعل الله يهديهن بذلك، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10584/حكم-زيارة-المقابر-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40103.mp3","categories":["زيارة القبور","النظر والخلوة والاختلاط"]},{"id":12551,"question":"تسأل سماحة الشيخ وتقول: هل زيارة المقبرة جائزة للنساء، أم لا؟ لأنني سمعت من خلال هذا البرنامج أنه لا يجوز، هل ما سمعته صحيح؟","title":"هل زيارة المقبرة جائزة للنساء، أم لا؟","answer":"الجواب:\n\nنعم صحيح، ليس للنساء زيارة القبور، الرسول ﷺ لعن زائرات القبور -عليه الصلاة والسلام- وإنما الزيارة للرجال قال: زوروا القبور؛ فإنها تذكركم الآخرة أما النساء فلا، فنهاهن عن الزيارة، قال: لعن رسول الله ﷺ زائرت القبور فلا يجوز لهن زيارة القبور، لكن يصلين على الجنائز مع الناس لا بأس، الصلاة مشروعة للرجال والنساء على الجنائز، فإذا حضرن مع الناس، وصلين على الجنائز في المسجد، أو في المصلى؛ فهذا مطلوب، أما الذهاب إلى المقابر، وزيارة القبور فهذا للرجال خاصة. نعم.\n\nالمقدم: جزاكم الله خيرًا، هل تذكرون الناس بالحكمة في هذا لو تكرمتم شيخ عبدالعزيز ؟\n\nالشيخ: الحكمة -والله أعلم- أنهن فتنة، فإذا اعتدن زيارة القبور قد يحصل بها الفتنة للزوار من الرجال بسبب الاختلاط؛ ولأنهن في الغالب قليلات الصبر إذا تذكرن أولادهن أو آباءهن أو أمهاتهن أو إخوانهن، فربما جزعن، وقل صبرهن، وحدث منهن ما لا ينبغي من النياحة، أو شق الثياب، أو لطم الخدود، أو التعري، فكان من حكمة الله أن منعهن من الزيارة؛ سدًا لباب الفتنة، وحذرًا من أن يقع منهن ما لا تحمد عقباه، لعل هذا هو الحكمة -والله أعلم- نعم.\n\nالمقدم: كأن حركة النساء مطلوب الإقلال منها سماحة الشيخ؟ هل توجهون الناس إلى شيءٍ من هذا ؟\n\nالشيخ: نعم، الله -جل وعلا- يقول: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب: 33] السنة لزوم البيوت، وعدم التجول، والخروج إلا من حاجة؛ لأن هذا من أسباب السلامة والعصمة والعافية، والخروج إلى الأسواق، والزيارات الكثيرة من أسباب الفتنة، فالأفضل للمرأة، والأجود لها لزوم بيتها، وقلة الخروج إلا من حاجة.\n\nالشيخ: كلمة للرجال حول هذا الموضوع أولياء الأمور؟\n\nالشيخ: كذلك، نوصي الرجال أن يحرصوا على توصية النساء بقلة الخروج، والحرص على منعهن من الخروج إلا من حاجةٍ وفائدة، وإلا فينبغي تقليل الخروج، ولا سيما في الأسواق، أسواق البيع والشراء، فإن ذلك قد يسبب فتنًا كثيرة، وإذا خرجت؛ فليكن معها امرأة صالحة أو أكثر؛ حتى يتعاونا على أسباب الستر والعافية، وعلى البعد عن أسباب الفتنة.\n\nالمقدم: شيخ عبدالعزيز هناك بعض الأغراض بإمكان الرجل أن يحضرها إلى المرأة، وهي في بيتها، لماذا لا يقوم الرجال بمثل هذا؟\n\nالشيخ: كذلك إذا تيسر ذلك، فينبغي له أن يقوم مقامها، وأن يحضر حاجتها حتى لا تحتاج إلى الخروج، ولا ينبغي له الكسل، بل ينبغي له أن يقوم بالمهمة، وينبغي لها هي أن ترضى بذلك، وأن تقتنع حتى يكفيها المؤونة، والله يهدي الجميع.\n\nالمقدم: آمين، جزاكم الله خيرًا، الواقع هذا الموضوع يحتاج إلى تنبيهٍ باستمرار، ولا سيما أنك ترى بعض الناس وعليهم سمات الصلاح يتجولون بنسائهم في المكتبات، في معارض الكتب، في معارض الأقمشة، والرجل في إمكانه أن يحضر هذه الأشياء، ولا أدري كيف يصطحبون النساء معهم؟\n\nالشيخ: الله يهديهم، الله يهديهم، نسأل الله لنا ولهم الهداية والتوفيق.\n\nالمقدم: آمين جزاكم الله خيرًا، إذًا تنكرون مثل هذا شيخ عبدالعزيز؟ \n\nالشيخ: نعم، ندعو إلى الترك، والحرص على عدم الخروج إلا من حاجة، عدم خروج المرأة إلا من حاجة، لا يكفي فيها الرجل، ويقوم مقامها.\n\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم، الموضوع يحتاج إلى كثير من الأسئلة، لكنا نتركه الآن، ونعود -إن شاء الله- في مناسبات أخرى.","link":"https://binbaz.org.sa/fatwas/10764/هل-زيارة-المقبرة-جاىزة-للنساء-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41009.mp3","categories":["زيارة القبور"]},{"id":12703,"question":"يسأل ويقول: هل زيارة القبور في أيام العيد من الحلال، أم من الحرام؟","title":"حكم تخصيص يوم العيد بزيارة المقابر","answer":"الجواب:  لا حرج في ذلك في أي وقت، لكن تخصيصها بوقت العيد ما يصلح إذا كان لقصد أن يوم العيد أفضل، أو كذا، أما إذا كان التخصيص من أجل الفراغ؛ لأنه لا يفرغ إلا في تلك الأيام؛ فلا حرج، وإلا فالزيارة ليس لها وقت معلوم. يزورها في الليل، أو في النهار، في أيام العيد، أو في غيره، ليس لها حد محدود، ولا زمان معلوم، الرسول  قال: زوروا القبور؛ فإنها تذكركم الآخرة ولم يحدد وقتًا، فالمؤمن يزورها في كل وقت، في الليل والنهار، في أيام العيد وغيرها ولا يخصص يومًا معينًا لذلك، لقصد أنه أفضل من غيره، أما إذا خصصه لأنه أفرغ له، ما عنده وقت إلا ذلك الوقت؛ فلا بأس بذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10913/حكم-تخصيص-يوم-العيد-بزيارة-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45908.mp3","categories":["زيارة القبور"]},{"id":12804,"question":"يقول في سؤال له: إذا كانت زيارة القبور حرام فكيف للناس أن يزوروا الأضرحة من أولياء الله الصالحين؟","title":"حكم زيارة أضرحة الأولياء والصالحين","answer":"الجواب:  زيارة القبور سنة، ما هي بحرام، لكن إذا كانت على الوجه الشرعي، فالزيارة زيارتان: بدعية، وسنية. فالزيارة التي مقصودها الدعاء للأموات، والترحم عليهم، وتذكر الآخرة والموت، هذه مطلوبة، سنة وقربة، أمر بها النبي ﷺ فقال -عليه الصلاة والسلام-: زوروا القبور؛ فإنها تذكركم الآخرة وفي لفظ: تذكركم الموت وكان يعلم أصحابه -عليه الصلاة والسلام- إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين ويدعو لهم يقول: يغفر الله لنا ولكم اللهم اغفر لأهل بقيع الغرقد.  هكذا المؤمن يسلم عليهم، ويدعو لهم، أما أنه يدعوهم مع الله يقول: يا سيدي اقض حاجتي، انصرني، هذا شرك أكبر، يا سيدي انصرنا على فلان وفلان، انصرنا على الكافرين، أغثني، اشف مريضي، أنا في حسبك وجوارك، هذا منكر، هذا من المحرمات الشركية لا يجوز، وهذا فعل المشركين الأولين، نسأل الله العافية، وهذه زيارة بدعية شركية. وهكذا لو زارهم، يطوف على قبورهم، هذا أيضًا من الشرك الأكبر، إذا كان يطوف، يتقرب إليهم بذلك، أما إن كان يظن أن الطواف بقبورهم قربة إلى الله؛ فهذا بدعة، لا يجوز أيضًا، وهكذا الصلاة عندها بدعة، وهكذا الجلوس عندها للقراءة بدعة. أما دعاؤهم، ودعاء الأموات، والاستغاثة بالأموات، والنذر لهم، والذبح لهم هذا من الشرك الأكبر، نسأل الله العافية، فينبغي للمؤمن، بل يجب عليه أن يتبصر، وأن يسأل أهل العلم بالسنة، أهل العقيدة الطيبة يسألهم عما أشكل عليه، وأن يحذر ما حرم الله عليه. نعم. المقدم: جزاكم الله خيرًا، كأن أخانا سماحة الشيخ خلط في الحكم بين النساء والرجال؟ الشيخ: النساء لا يزرن القبور، القبور للرجال بس يزورهن الرجال القبور، أما النساء فالرسول ﷺ لعن زائرات القبور؛ لأنهن فتنة، وصبرهن قليل؛ فلا يجوز لهن زيارة القبور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11018/حكم-زيارة-اضرحة-الاولياء-والصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46209.mp3","categories":["زيارة القبور"]},{"id":12901,"question":"يقول أيضًا في موضوع القبور: يوضع أزهار على القبور، وخاصة يوم الأعياد، هل هذا جائز؟","title":"حكم وضع الزهور على القبور في الأعياد","answer":"الجواب:  ليس بجائز ولا مشروع، لا يوضع على القبور لا أزهار ولا غيرها، إنما وضع النبي ﷺ جريدتين على قبرين معذبين، أطلع الله نبيه على أنهما يعذبان؛ فوضع عليهما جريدتين، وقال: لعله يخفف عنهما ما لم تيبسا ولم يأمر بوضع الجريدة على القبور الأخرى، إنما وضعها على قبرين اطلع على عذاب أصحابهما، قال: أما أحدهما فكان لا يستنزه من البول، وأما الآخر فكان يمشي بالنميمة فهذا يبين لنا عظم الخطر في عدم التنزه من البول، وعظم الخطر في النميمة، نسأل الله العافية. فالواجب على كل مسلم، وعلى كل مسلمة العناية بالطهارة، والحرص على السلامة من الأبوال في البدن، وفي الثوب، وفي المصلى، كذلك الحذر من النميمة والغيبة، يجب على كل مسلم ومسلمة أن يحذر من الغيبة والنميمة، والغيبة: ذكرك أخاك بما يكره؛ فلان بخيل، فلان كذا، فلان كذا، فلانة كذا بما تكره، والنميمة نقل الكلام السيئ من فلان إلى فلان، فلان يقول: فيك كذا، وفلان يقول: فيك كذا، فلانة تقول: فيك كذا، فلانة تقول: فيك كذا، هذه هي النميمة، وهي من الكبائر، ومن أسباب البغضاء والشحناء بين المسلمين، فالواجب الحذر منها. وقد قال ﷺ: لا يدخل الجنة نمام، ولما سئل عن الغيبة؟ قال: ذكرك أخاك بما يكره، قيل: يا رسول الله إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول؛ فقد اغتبته، وإن لم يكن فيه؛ فقد بهته فالواجب الحذر، والله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12]، ويقول سبحانه: وَلا تُطِعْ كُلَّ حَلَّافٍ مَهِينٍ ۝ هَمَّازٍ مَشَّاءٍ بِنَمِيمٍ [القلم:10-11]، نسأل الله للمسلمين العافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11116/حكم-وضع-الزهور-على-القبور-في-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46803.mp3","categories":["زيارة القبور"]},{"id":13053,"question":"هذا السائل يقول: إذا مررت بالمقابر هل أسلم عليهم، وأنا مثلًا في سيارتي، وبيني وبينهم سور المقبرة، أم لابد من السلام عند الوقوف عليهم داخل المقابر؟","title":"حكم السلام على المقابر عند المرور بالسيارة من أمامها","answer":"الجواب:  إذا تيسر الوقوف عليهم يكون أولى وأكمل، تنزل وتقف على المقابر، وتسلم، وإن سلمت من بعيد؛ فلا بأس -إن شاء الله-إذا كنت قريبًا منهم يسمعون بحيث يسمعون، وإن نزلت ووقفت على الجدار، وتكلمت يكون هذا أكمل وأبلغ، تقول: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية اللهم اغفر لهم، اللهم ارحمهم، كل هذا طيب عند الجدار، تقف على الجدار وتتكلم، أو تدخل تسلم عليهم من داخل، كله طيب، الرسول ﷺ قال: زوروا القبور؛ فإنها تذكركم الآخرة وإذا مر الإنسان بها وسلم؛ له أجر كبير. المقدم: طيب، وإذا كان أيضًا في السيارة -يا سماحة الشيخ- وسلم وهو في سيارته؟ الشيخ: إذا كان قريبًا من الجدار، قريبًا منهم، يسلم بحيث يسمعهم صوته، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11270/حكم-السلام-على-المقابر-عند-المرور-بالسيارة-من-امامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50513.mp3","categories":["زيارة القبور"]},{"id":13321,"question":"هذا السائل من اليمن يقول في هذا  أهل مسجدنا يخرجون جميعًا بعد كل صلاة عيد إلى زيارة القبور جماعة، ما الحكم في هذا مأجورين؟","title":"حكم زيارة القبور بعد صلاة العيد","answer":"الجواب: ليس لهذا أصل، الخروج للقبور صلاة العيد إنما هي عادة لبعض الناس، فإذا زاروا القبور يوم العيد، أو يوم الجمعة، أو في أي يوم ما في يوم مخصوص، تخصيص يوم العيد، أو تخصيص الجمعة، أو تخصيص يوم آخر لا، ليس له أصل، ولكن السنة أن يزوروا القبور دائمًا بين وقت وآخر على حسب التيسير، إذا كان وقتهم يسمح في يوم الجمعة، في يوم العيد، في أوقات أخرى؛ يفعلون، أما أن يظنوا أن لهذا اليوم خصوصية؛ فلا، لكن السنة أن يزوروا القبور عندما يتيسر ذلك؛ لقوله ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة. وكان يزورها -عليه الصلاة والسلام- ويدعو لأهلها، فلا فرق بين يوم العيد، أو الجمعة، أو الخميس، أو غير ذلك، ليس لهذا وقت معروف فيما نعلم، ولكن المؤمن يتحرى الأوقات التي يحصل له فيها فرصة؛ لأن الإنسان قد تشغله المشاغل، فإذا تيسر له فرصة في الجمعة، أو في يوم العيد، أو في غير ذلك؛ فعل ذلك، زار القبور، وسلم عليها. وكان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذا تعليمه لأصحابه -عليه الصلاة والسلام- سواء كانت في الليل، أو في النهار، إذا زرتهم في الليل، أو في النهار، في أول النهار، في وسط النهار، في آخر النهار، في الليل، في أوله، في وسطه، في آخره حسب التيسير، نعم.  أما النساء لا، ليس لهن زيارة القبور، والرسول ﷺ لعن زائرات القبور، لكن يصلين على الميت في المساجد، في المصلى، لا بأس، يصلين مع الرجال على الموتى لا بأس، أما زيارة القبور فقد زجرهن عن ذلك -عليه الصلاة والسلام- ولعن زائرات القبور. والحكمة في ذلك -والله أعلم- لأنهن قليلات الصبر، ولأنهن فتنة، كما قال ﷺ: ما تركت بعدي فتنة أضر على الرجال من النساء. فالواجب عليهن طاعة الله ورسوله، وعدم الزيارة للقبور، لكن الدعاء مطلوب من الجميع، من الرجال والنساء، الدعاء لأموات المسلمين، الدعاء لأقاربهم، وأمواتهم: اللهم اغفر لهم، اللهم ارحمهم، اللهم أنجهم من النار، اللهم ارفع درجاتهم في الجنة.. إلى غير هذا من الدعوات الطيبة، اللهم كفر سيئاتهم، اللهم تقبل حسناتهم، اللهم لا تحرمنا أجرهم، ولا تفتنا بعدهم، الدعاء مطلوب في البيت.. في الطريق.. عند القبر.. كله طيب عند الزيارة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11607/حكم-زيارة-القبور-بعد-صلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54103.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":13505,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية اليمنية حضرموت، وباعثها المستمع عبد الحافظ عبدالرحمن باعباد، أخونا باعباد له سؤال يقول فيه: يوجد عندنا قبور يقال: إنها قبور بعض الصالحين، ويقوم بعض الناس بزيارتها لكي تبعد عنهم الشر، وتجلب لهم الخير، وتشفي مرضهم بزعمهم، ويقولون: إن هذا الصالح له شأن في هذا الشيء، وعند نهاية زيارتهم يضعون بعض النقود على هذا القبر، ما حكم عملهم هذا؟","title":"حكم الاستغاثة بأهل القبور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. أما بعد.  فإن الله  شرع لعباده زيارة القبور للذكرى والاستغفار للميتين، والدعاء لهم، كما قال ﷺ: زوروا القبور فإنها تذكركم الآخرة ويقول لأصحابه -عليه الصلاة والسلام- كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، ويقول -عليه الصلاة والسلام- إذا زار البقيع: اللهم اغفر لأهل بقيع الغرقد ويقول: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون ثم يقول: اللهم اغفر لأهل بقيع الغرقد هذه هي السنة أن يدعى لهم عند الزيارة، ويترحم عليهم؛ لأنهم في حاجة إلى الدعاء. أما زيارتهم لطلب الشفاء، للمرضى، أو لطلب المدد، والنصر على الأعداء، أو ما أشبه ذلك، فهذا من الشرك الأكبر، هذا كفر بالله، هذا لا يجوز، هذه حال عباد الأوثان يرجون الموتى والأصنام والأشجار والأحجار والكواكب، ويسألونهم قضاء الحاجات، تفريج الكروب، شفاء المرضى، ويسألونهم المدد لكل ما يعينهم، هذا كله من الشرك الأكبر، فالواجب الحذر من هذا العمل السيئ. قبور الصالحين تزار للدعاء لهم، والترحم عليهم، لا لدعائهم من دون الله، ولا فرق بين العيدروس، أو ابن علوان، أو غيرهما، جميع القبور حتى قبور الأنبياء حتى قبر النبي ﷺ وقبر الصديق وعمر وأهل البقيع كلهم لا يدعون مع الله، لا يستغاث بهم، لا ينذر لهم حتى النبي ﷺ يقول: (السلام عليك يا رسول الله! ورحمة الله وبركاته، جزاك الله عن أمتك أفضل الجزاء وأحسنه) ولا يدعى من دون الله، ولا يقال له المدد، ولا اشف مرضانا، ولا انصرنا، هذا شرك أكبر. وهكذا عند الصديق، وهكذا عند عمر، هكذا عند عثمان، هكذا عند علي، هكذا عند قبور أهل البيت جميعًا، لا يدعون مع الله، لا يقال: انصرونا، أو اشفوا مرضانا، أو أنتم تعلمون حاجاتنا هذا كله من الكفر الأكبر، والغيب لا يعلمه إلا الله  قال الله : قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] فهو الذي يعلم الغيب -جل وعلا-. ولما سقط عقد لعائشة في بعض الأسفار؛ أناخ النبي الناس -عليه الصلاة والسلام- وطلب العقد، وأرسل من يطلبه ويلتمسه، ولم يعرف أين مكانه -عليه الصلاة والسلام- وهو سيد الخلق، وأفضلهم، لم يعرف أين العق، طلب أن يلتمسوه؛ فلم يجدوه، فلما أقاموا البعير الذي عليه عائشة؛ وجدوه تحته. فلو كان يعلم الغيب؛ لقال: انظروه تحت البعير، ولم يحتج إلى أن يرسل من يطلبه. ولما قذف المنافقون عائشة، وبعض الناس قلدهم وقذفها لم يعلم الحقيقة، وتوقف حتى جاءه الوحي بسلامتها وبراءتها، رضي الله عنها وأرضاها. فالغيب لا يعلمه إلا الله، لا يعلمه نبي، ولا ملك، ولا غيرهما إلا ما علم الله عباده، إلا ما أوحى الله به إلى أنبيائه، وعلمهم إياه. هكذا لا يدعون مع الله، ولا يستغاث بهم، وهم أنبياء قال الله تعالى: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] هذا (أحدًا) هذا عام، نكرة في سياق النهي يعم الأنبياء وغيرهم، قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. فسمى دعاة غير الله كفره، يعني: دعاة الأموات والأنبياء، ودعاء الأشجار والأصنام، ونحو ذلك، وقال الله لنبيه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين. والمقصود: تحذيره ﷺ وتحذير الأمة فهو ﷺ لا يشرك، قد عصمه الله من هذا، لكن المقصود تحذير الأمة، وبيان أن هذا الأمر خطير، وأنه لا يجوز لأحد أن يفعله.  وهكذا قوله سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] أوحى الله إليه هذا الأمر؛ ليعلم الناس أن الشرك محرم، وأنه أعظم الذنوب، وأنه محرم على الأنبياء، وعلى غيرهم. وقال سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14]  فجعل دعاء غير الله كائنًا من كان من الشرك، وقد أخبر أن المدعوين لا يسمعون دعاء الداعين، وأنهم لو سمعوا ما استجابوا. فالواجب الحذر من هذا الشرك الوخيم، وتحذير الناس من ذلك، والواجب على العلماء في كل مكان أن يبينوا للناس هذا الأمر العظيم، وأن يحذروهم من التعلق على القبور، والتعلق على الأموات، والاستغاثة بهم، والنذر لهم، وطلب منهم المدد، والعون، كل هذا من المحرمات الشنيعة، بل من الشرك الأكبر، وإذا كان هذا لا يجوز مع النبي ﷺ ولا مع الخلفاء الراشدين، فكيف يجوز مع العيدروس، أو مع ابن علوان، أو مع الشيخ عبدالقادر، أو مع علي، أو مع الحسن، أو فاطمة، أو غيرهم، لا يجوز أبدًا مع أحد، العبادة حق الله وحده قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وقال: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] وقال: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] وقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] فهو المعبود بالحق وهو المستعان -جل وعلا- فلا يدعى معه أحد، لا ملك، ولا نبي، ولا صنم، ولا شجر، ولا حجر، ولا ميت، العبادة حق الله وحده -سبحانه وتعالى- قال تعالى: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقال سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2] وقال -جل وعلا-: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14]. أما الحي فلا بأس يقال له: يا عبدالله! أعني على كذا الحي الحاضر، تقول: أعني على إصلاح سيارتي، أقرضني كذا وكذا حي يسمعك ويقدر، تقول له: أعني على كذا، أعني على تعمير بيتي، على إمساك دابتي، على إصلاح سيارتي، هذا لا بأس، كما قال الله في قصة موسى : فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] لأنه حي قادر، أما الأموات فلا يدعون مع الله، وهكذا الأصنام، هكذا الأشجار والأحجار، هكذا النجوم، كل ذلك من الشرك الأكبر، نسأل الله العافية. فنصيحتي لكل مسلم أن يحذر هذا، وعلى العلماء أن يحذروا الناس من هذا الشرك الوخيم، على العلماء في كل مكان أن يتقوا الله، وأن يعنوا بهذا الأمر، بالكتابة، وفي خطب الجمعة، وفي غير ذلك، وهكذا زيارة القبور حتى ينبه الناس القبر الذي يدعى من دون الله، يزار حتى ينبه أهله، يزوره العالم يقول: يا ناس هذا لا يجوز، سلموا وادعوا له بالمغفرة والرحمة، أما أن تدعوه من دون الله المدد المدد يا سيدي فلان اشفع لنا، انصرنا هذا .... هذا الشرك الأكبر، نعوذ بالله، فيجب الحذر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11818/حكم-الاستغاثة-باهل-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47901.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":13526,"question":"يقول أخونا في سؤاله الأخير: نحن إذا خرجنا من المسجد بعد صلاة العشاء، أو صلاة الفجر، يوجد على طريقنا مقبرة، فيقف عندها إمام المسجد، ونقف حوله، ويقرأ الدعاء على أرواح أهل المقبرة، ونحن نؤمن على دعائه، ما رأيكم في هذا العمل؟","title":"حكم الدعاء والتأمين الجماعي عند المرور على المقابر","answer":"الجواب:  لا حرج في ذلك، لا حرج، الدعاء لهم هذه زيارة إذا مررتم عليهم، ودعوتم لهم جزاكم الله خيرًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11845/حكم-الدعاء-والتامين-الجماعي-عند-المرور-على-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47906.mp3","categories":["زيارة القبور"]},{"id":13772,"question":"هذه سائلة تقول في هذا  نعلم بأن زيارة القبور محرمة على النساء، ولكن السؤال يا سماحة الشيخ: إذا مرت المرأة في طريقها بالقبور فهل تقول دعاء المرور بالقبر؟ وما الحكمة من منع النساء في زيارة القبور؟","title":"الحكمة في منع النساء من زيارة القبور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد ثبت عن الرسول ﷺ أنه قال: زوروا القبور؛ فإنها تذكركم الآخرة وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا، والمستأخرين. والحكمة من الزيارة أنها تذكر الإنسان بالموت، تذكره بالآخرة مع ما فيها من الإحسان للموتى، والدعاء لهم، والترحم عليهم، أما النساء فقد منعهن الرسول ﷺ من ذلك، كان الرسول ﷺ منع الجميع من الزيارة سابقًا في أول الإسلام، لما كان الناس حديثي عهد بشرك؛ منعوا، ثم أذن للجميع بالزيارة، ثم خص الله -جل وعلا- الرجال بالزيارة، دون النساء، بل جاء في الحديث: لعن رسول الله زائرات القبور من النساء. والحكمة في ذلك كما قال أهل العلم -والله أعلم-: أنهن قليلات الصبر، وفتنة للرجال، فسد الله هذا الباب؛ لأنهن إذا زرن القبور قد لا يملكن أنفسهن من البكاء والعويل والصراخ، وقد يفتن الرجال الزائرين للقبور في الطريق، أو في المقبرة، أو في الرجوع، فالحكمة في ذلك -والله أعلم- كما قال أهل العلم أنهن فتنة، وأنهن قليلات الصبر، فلا يؤمن عليهن إذا شاهدن القبور -قبور آبائهم وأمهاتهم وإخوانهم وأزواجهم- أن يقع منهن ما لا ينبغي من الصراخ والنحيب والنياحة وشق الثياب ونحو ذلك، ولا أيضًا يؤمن أن يفتن الرجال، أو يفتتن بالرجال الزائرين، والله -جل وعلا- هو الحكيم العليم، لا يمنع شيء إلا لحكمة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12137/الحكمة-في-منع-النساء-من-زيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53601.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":13898,"question":"السائل حسين يقول في هذا  هل يجوز لي أن أقرأ القرآن على قبر والدي وأن أقرأ الفاتحة عليه؟ وهل يصل أجر قراءتي لهذا القرآن؟ أم أنني أكتفي بالدعاء؟","title":"حكم قراءة القرآن عند القبر","answer":"الجواب: ليس لك القراءة، لا تجوز القراءة على القبور ولكن الدعاء يكفي، النبي ﷺ دعا للموتى، وقال عليه الصلاة والسلام لأصحابه علمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون. نسأل الله لنا ولكم العافية، وفي اللفظ الآخر: يرحم الله المستقدمين منا والمستأخرين، هذا هو السنة، أما القراءة غير مشروعة بل بدعة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12273/حكم-قراءة-القران-عند-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53810.mp3","categories":["زيارة القبور"]},{"id":13993,"question":"السائلة فايزة يوسف من مصر - قنا تقول: هل يجوز لي أن أذهب إلى القبور وذلك للعبرة وليس للنياحة؛ لأنني أعلم بأنها محرمة على النساء، ولكنني أحب أن أتذكر الآخرة، وما الحكمة من منع النساء في زيارة القبور؟ جزاكم الله خيرًا.","title":"الحكمة في منع النساء من زيارة القبور","answer":"الجواب: الرسول ﷺ أمر بزيارة القبور قال: زوروا القبور فإنها تذكركم الآخرة، لعن زائرات القبور من النساء، ذكر أهل العلم أن الحكمة في ذلك أنهن في الغالب لا يصبرن؛ ولأنهن فتنة، فإذا زرن القبور قد يحصل منهن من البكاء والنياحة والشيء الذي لا ينبغي لقلة صبرهن في الغالب؛ ولأنهن قد يختلطن بالرجال ويكون فتنة، والله جل وعلا هو الحكيم العليم لا ينهى عن شيء إلا لحكمة بالغة ، فهو الحكيم في قوله وفعله وشرعه وقدره جل وعلا.\nومن حكمته سبحانه نهي النساء عن زيارة القبور إما لأنهن فتنة، وإما لقلة صبرهن، وإما للأمرين جميعًا، وإما لأمور أخرى أيضًا، لكن الحمد لله لهن الدعاء، يدعون لموتاهم في بيوتهم وفي كل مكان، ويصلين على الجنائز في المسجد أو في المصلى، هذا كله مسموح به والحمد لله، فهي تدعو لقريبها ولزوجها في بيتها وفي كل مكان، تستغفر له .. تتصدق عنه كل هذا طيب ينفع الميت، من الرجل والمرأة جميعًا.\nأما الزيارة للقبور فهي خاصة بالرجال؛ لأن الرسول عليه السلام قال: زوروا القبور فإنها تذكركم الآخرة، لعن زائرات القبور من النساء ومنعهن من ذلك قالت أم عطية: نهينا عن اتباع الجنائز. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12402/الحكمة-في-منع-النساء-من-زيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53913.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":14235,"question":"هذه السائلة أختكم في الإسلام أم أحمد لها مجموعة من الأسئلة، تقول: سماحة الشيخ! هل زيارة القبور حرام أم حلال؟ وماذا عن لبس الأسود على المتوفى بالنسبة للنساء؟ جزاكم الله خيرًا.","title":"حكم زيارة القبور للرجال والنساء","answer":"الجواب: الزيارة للنساء ممنوعة زيارة القبور، والرسول ﷺ نهاهن عن الزيارة ولعن زائرات القبور من النساء، أما للرجال فهي سنة، النبي  قال: زوروا القبور يعني: الرجال فإنها تذكركم الآخرة، وكان الرسول ﷺ قد نهى الجميع ثم رخص للجميع ثم جاء الوحي بتخصيص الرجال خاصة ومنع النساء من زيارة القبور لحكمة بالغة، ولعل من الحكمة أنهن فتنة وصبرهن قليل، فمن رحمة الله وإحسانه إليهن وإلى الناس أن منعهن من الزيارة للقبور. أما الصلاة على الميت فإنها مشروعة للجميع، الرجال يصلون على الميت والنساء كذلك يصلين على الميت، سواء في البيت أو في المصلى، أما زيارة القبور فهذه خاصة بالرجال. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12695/حكم-زيارة-القبور-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54906.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":14303,"question":"ما حكم زيارة القبور -قبور الأولياء- بالنسبة للرجال والنساء؟","title":"حكم زيارة قبور الأولياء للرجال والنساء","answer":"الجواب: زيارة القبور سنة، سواء كانوا أولياء أو ليسوا بأولياء عموم المسلمين، سواء كانوا من المعروفين بالاستقامة والعلم والفضل وهم المؤمنون ويسمون أولياء الله، كل مؤمن فهو ولي لله، أو كان فيهم بعض المعاصي، فإن القبور تزار للذكرى، ذكر الموت وذكر الآخرة، والدعاء لهم بالمغفرة والرحمة، والعاصي في حاجة أيضًا إلى الدعاء والترحم عليه والدعاء له. وكان النبي ﷺ يزور القبور ويدعو للموتى بالمغفرة والرحمة، ويقول عليه الصلاة والسلام: زوروا القبور فإنها تذكركم الآخرة وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية في الروايات الأخرى: يرحم الله المستقدمين منا والمستأخرين وكان يزور البقيع، ويقول: اللهم اغفر لأهل بقيع الغرقد، يقول: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون غدًا مؤجلون اللهم اغفر لأهل بقيع الغرقد، هذه سنته عليه الصلاة والسلام، الزيارة للقبور، والدعاء للموتى موتى المسلمين بالمغفرة والرحمة.\nأما النساء فلا يزرن القبور؛ لأن الرسول ﷺ لعن زائرات القبور؛ ولأنهن فتنة وصبرهن قليل في الغالب، فمن رحمة الله ومن إحسانه وفضله أنه لم يشرع لهن زيارة القبور، كانت الزيارة ممنوعة أولًا للجميع، ثم رخص فيها للجميع، ثم جاء النهي عن الزيارة للنساء خاصة واللعن على ذلك، فالواجب عليهن ترك الزيارة للقبور.\nأما الصلاة على الميت فيصلي عليه الجميع الرجل والمرأة لكن الزيارة للقبور واتباع الجنائز إلى المقبرة هذا خاص بالرجال، فالمرأة لا تتبع الجنازة إلى المقبرة ولا تزور القبور، هذا هو الصحيح من أقوال أهل العلم، والله جل وعلا المسئول أن يوفقنا والمسلمين لما فيه رضاه.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12804/حكم-زيارة-قبور-الاولياء-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62211.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":14394,"question":"هل يجوز للنساء زيارة القبور؟ علمًا بأن الزيارة تذكر الإنسان الآخرة.","title":"هل يجوز للنساء زيارة القبور؟","answer":"الجواب: النساء ليس عليهن زيارة، ليس لهن زيارة، الزيارة للرجال، يقول النبي ﷺ زوروا القبور، فإنها تذكركم الآخرة فيستحب للرجل أن يزور القبور من دون شد رحل، يزورها في البلد، يدعو الله لهم بالمغفرة والرحمة، ويتذكر بهذا أنه صائر إلى ما صاروا إليه، وأن الموت لا بد منه حتى يستعد، يقول النبي ﷺ: زوروا القبور، فإنها تذكركم الآخرة وكان يعلم أصحابه  يقول لهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي رواية: يرحم الله المستقدمين منا والمستأخرين ولا يشد الرحل، بل هذا في البلد؛ لأن الرسول ﷺ: نهى عن شد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى تعني: مسجد المدينة والمسجد الأقصى، هي التي تشد لها الرحال. فالقبور لا يشد لها الرحال، لكن إذا زار القبور في بلده، أو زار بلدًا للتجارة أو لغيرها فزار قبورها هذا مستحب وفيه خير عظيم.  أما النساء فقد جاء في الأحاديث: لعن زائرات القبور فلا يزرن القبور؛ لأنه جاء في الحديث لعنهن على ذلك؛ لأنهن فتنة، وصبرهن قليل، فلا يزرن القبور. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12876/هل-يجوز-للنساء-زيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48802.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":14589,"question":"تقول: إنها زارت قبر النبي ﷺ فلاحظت أن هناك أناسًا أنكروا عليها، ترجو توجيه سماحة الشيخ.","title":"ما حكم زيارة النساء لقبر النبي عليه الصلاة والسلام؟","answer":"الجواب: زيارة القبور للنساء فيها خلاف بين العلماء، من أهل العلم من قال: إن النساء يزرن القبور كالرجال، وهو قول بعض أهل العلم.  والقول الثاني: أنهن لا يزرن القبور، لا قبر النبي، ولا غيره -عليه الصلاة والسلام-.  وهذا القول أرجح القولين وأصح؛ لقوله ﷺ في الحديث الصحيح بأنه ﷺ: لعن زائرات القبور وفي اللفظ الآخر: زوارات القبور فدل ذلك على أنهن لا يزرن القبور، وكن أولًا مع الرجال يزرن القبور عمومًا، ثم نهى الله النساء، وبقيت الرخصة للرجال، والسر في ذلك -والله أعلم-: لأنهن فتنة وصبرهن قليل، فشرع الله لهن ترك ذلك لئلا يَفتِنَّ أو يُفتنَّ في زيارة القبور، فيدعون لأمواتهن بالمغفرة والرحمة في البيوت وفي الطرقات، وفي المساجد ولا حاجة إلى زيارة القبور، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13086/ما-حكم-زيارة-النساء-لقبر-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63509.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":14975,"question":"سؤال فلاح السويد من قرية الكوز التالي طويل ومتشعب أيضًا، لكن لا بد من قراءته، يقول فيه: أسألكم عن زيارة قبور الصالحين، وتقبيل الحجر، أي: النصائب، هل هذا يجوز أم لا؟ وعن مديح المشايخ هل يجوز أم لا؟ وعن المدد أو استمداد من غير الله مثل: مدد يا شيخ الفلاني مثلًا، هل هو من قبره يمدني أم لا؟أفيدونا، إننا غشماء عن هذه، ولا ندري إننا نسب عباد الله الصالحين، يقول أحد الناس: إن من عباد الله الصالحين يغني قسم من هذه الدنيا بكلمة واحدة، هل هذا يجوز القول أم لا حرام؟نرجو أن تجعلونا لله نهتدي إلى الخير بمشيئة الله.الجواب: أعد السؤال. يقول في سؤاله، نأخذه نقطة نقطة، يقول في سؤاله: نسألكم عن زيارة قبور الصالحين، وتقبيل الحجر، أي: النصائب، هل هذا يجوز أم لا؟","title":"حكم زيارة قبور الصالحين وتقبيل النصائب وطلب المدد","answer":"الجواب: زيارة القبور للصالحين للمسلمين أيضًا عمومًا سنة، قربة، الرسول ﷺ أمر بزيارة القبور، وحث عليها، وقال: إنها تذكر الآخرة، وتزهد في الدنيا، وتذكر الموت قال -عليه الصلاة والسلام-: زوروا القبور، فإنها تذكركم الآخرة وكان يعلم أصحابه -عليه الصلاة والسلام- إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية وفي حديث عائشة يقول: يرحم الله المستقدمين منا والمستأخرين. فعلينا معشر المسلمين أن نعلم هذا الحكم، ويشرع لنا أن نفعل ذلك؛ أن نزور القبور للذكرى والرغبة في الآخرة والزهد في الدنيا، والإحسان للموتى بالدعاء لهم، الإنسان يزورهم ليدعو لهم بالمغفرة والرحمة والعافية؛ وليتذكر الآخرة، وأنه صائر إلى ما صاروا إليه من هذا الموت حتى يستعد للآخرة. أما تقبيل القبور فلا، لا يقبل النصائب ولا التراب، ولا الجدران إن كان عليها جدران ولا القضبان إن كان هناك قضبان، كل هذا منكر لا يجوز، هذا من الغلو، ولا يجوز البناء على القبور، بل يجب أن تكون مكشوفة ليس عليها بناء، واتخاذ القباب عليها من البدع، وهكذا بناء المساجد عليها من البدع التي أنكرها الرسول ﷺ ونهى عنها، قال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد وقال جابر : \"نهى النبي ﷺ عن تجصيص القبور، والقعود عليها، والبناء عليها، والكتابة عليها\". فليس لأحد أن يبني على القبور لا قبابًا ولا مساجد ولا غير ذلك، وليس له أن يقبلها، ولا أن يتبرك بترابها، ولا أن يطلب الشيخ المدد كما يأتي، لا يجوز يقول: يا رسول الله، مدد مدد، ولا يا فلان كالشيخ عبدالقادر، أو يا شيخ البدوي السيد البدوي، أو يا الحسن أو يا سيدي الحسن أو الحسين، أو يا فلان أو يا أبا حنيفة، أو يا أبا فلان، كل هذا لا يجوز، المدد لا يطلب من الميت يطلب من الله -جل وعلا-: يا رب أغثني، يا رب ارحمني، يا رب اشف مريضي، يا رب ارزقني، أما طلب المدد من الموتى فهو من الشرك بالله  من الشرك الأكبر من عمل الجاهلية. فلا يقبل الحجارة، ولا النصائب ولا التراب، ولا يأخذ التراب للبركة، ولا يطلب مدد من المخلوق من الميت، أما الحي الحاضر تقول: يا أخي! ساعدني بكذا، أعني على كذا، وهو حي حاضر قادر لا بأس، الحي الحاضر القادر لا بأس، لكن الميت لا، لا تقل: المدد المدد، ولا تقل: اشف مريضي وانصرني على عدوي انصرنا على المشركين لا يقل هذا للميت، الميت انقطع عمله، وليس له التصرف في الكون، بل التصرف لله وحده  هو المالك لكل شيء، وهو القاهر فوق عباده، وهو النافع الضار، المعطي المانع، المدبر للكون ، وأما الميت فهو مرتهن بعمله ليس له تصرف، قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية مثل الأوقاف التي يوقفها في حياته أو علم ينتفع به كتب ألفها أو طلبة علمهم له أجر ذلك  أو ولد صالح يدعو له. أما كونه يتصرف في الكون، أو يمد هذا، أو ينصر هذا، هذا منكر لا حقيقة له ولا صحة له، بل الاستغاثة بالأموات والنذر لهم، والتقرب إليهم، بالذبائح، وطلبهم المدد والغوث كل هذا من فعل الجاهلية من عمل أهل الشرك، وهو شرك أكبر يجب الحذر منه، ويجب عليك -أيها السائل- أن تبلغ من يفعل هذا أن هذا منكر، وأنه شرك يجب ترك ذلك والتوبة إلى الله من ذلك؛ لأن هذا من عمل الجاهلية، نعم.","link":"https://binbaz.org.sa/fatwas/13482/حكم-زيارة-قبور-الصالحين-وتقبيل-النصاىب-وطلب-المدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_661/nour_66102.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":15351,"question":"في آخر أسئلة هذه السائلة تقول سماحة الشيخ: سمعت من إحدى صديقاتي بأنه عند المرور على القبور أنه يستحب للمسلم أن يقرأ سورة الإخلاص إحدى عشر مرة، وآية الكرسي في هذا اليوم، فيرفع عنهم العذاب، وعلى قدر عددهم يغفر الله لهم، هل هذا بدعة؟","title":"حكم قراءة الإخلاص وآية الكرسي عند المرور على القبور","answer":"الجواب: كل هذا باطل، لا أصل له، هذا باطل ليس له أصل، بدعة، بدعة ظاهرة، ليس له أصل، ولكن إذا مر عليهم يسلم عليهم، يقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذا الرجل، أما المرأة لا تزور القبور، لكن الرجل إذا مر عليها يسلم، أما قراءة قُلْ هُوَ اللَّهُ أَحَدٌ  [الإخلاص: 1] أو آية الكرسي كل هذا لا أصل له، نعم.","link":"https://binbaz.org.sa/fatwas/13854/حكم-قراءة-الاخلاص-واية-الكرسي-عند-المرور-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56624.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":15352,"question":"سماحة الشيخ، بالنسبة للسلام على الموتى، هل يشرع السلام داخل المقبرة أو المرور بالسيارة مثلاً؟","title":"مشروعية دخول المقبرة والسلام على أهلها","answer":"الجواب: إذا دخل فهو أفضل؛ لكونه يقف عليهم، ويسلم عليهم؛ لأنها أقرب إلى الخشوع والتأثر، وإن مر عليهم بالسيارة وسلم، أو على دابته وسلم، أو وقف على الجدار وسلم، كفى، لكن كونه يقصد القبور، ويدخل عليهم، ويسلم عليهم، ويدعو لهم، هذا أكمل وأشد في التأثر.","link":"https://binbaz.org.sa/fatwas/13855/مشروعية-دخول-المقبرة-والسلام-على-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56625.mp3","categories":["زيارة القبور"]},{"id":15623,"question":"إبراهيم أبو حامد له مجموعة من الأسئلة، يقول في سؤاله الأول: البعض من الناس يزورون قبر أم الرسول ﷺ في الأبواء، فهل هذا من السنة؟","title":"حكم زيارة قبر أم الرسول ﷺ","answer":"الجواب: ليست زيارتها من السنة، إنما زيارة القبور على العموم سنة، النبي  قال: زوروا القبور، فإنها تذكركم بالآخرة وأم النبي ﷺ ماتت في الجاهلية، زارها النبي ﷺ وسأل ربه أن يستغفر لها فلم يأذن له، بكى وأبكى -عليه الصلاة والسلام-، فدل ذلك على أن قبور أهل الجاهلية إذا زيرت فلا بأس، كما زار النبي ﷺ أمه، لكن لا يدعى لهم، إنما تزار للاعتبار فقط للاعتبار. وأما قبور المسلمين فالسنة أن تزار، ويدعى لهم، ويسلم عليهم، ويستغفر لهم، أما قبور أهل الجاهلية كأم النبي ﷺ وقبور الكفار فلا بأس بزيارتها، لكن ليست سنة، إنما تزار للاعتبار، ذكر الآخرة، ذكر الموت.  أما قبور المسلمين فتزار للدعاء لهم، والترحم عليهم، وذكر الآخرة، قال: زوروا القبور، فإنها تذكركم بالآخرة هكذا يقول ﷺ، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين والمستأخرين وربما قال: يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر. وإذا زار قبور الكفار كما تقدم للعبرة والاتعاظ فلا بأس، كما فعله النبي ﷺ، نعم. وقد يقال: إنه سنة للاعتبار؛ لأن النبي ﷺ زار قبر أمه، وهي ماتت في الجاهلية، قد يقال: إنه سنة أيضًا؛ يدخل في العموم من جهة الاعتبار فقط، من جهة الاعتبار والذكرى، وليس للدعاء لهم؛ لأنه لا يدعى لهم، لكن إذا  زارها للاعتبار فالقول بأنه سنة أيضًا قول له قوة تأسيًا بالنبي ﷺ في زيارته لقبر أمه، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14159/حكم-زيارة-قبر-ام-الرسول-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57106.mp3","categories":["زيارة القبور"]},{"id":16300,"question":"مستمع بعث برسالة وضمنها ثلاثة أسئلة، في أحدها يقول: ما حكم زيارة المقابر، وما هو المطلوب عند زيارتها؟","title":"حكم زيارة المقابر وما يندب عند زيارتها","answer":"الجواب: زيارة المقابر، سنة، قربة، طاعة لله -جل وعلا- لما فيها من التذكير بالموت، والتذكير بالآخرة، والدعاء للأموات، والترحم عليهم، فهي عبادة عظيمة، ولهذا قال ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة وكان يعلم أصحابه -عليه الصلاة والسلام-: إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، يرحم الله المستقدمين منا، والمستأخرين، نسأل الله لنا ولكم العافية. وكان يزور القبور ﷺ ويدعو لهم، ويقول: السلام عليكم دار قوم مؤمنين، وإنا -إن شاء الله- بكم لاحقون غدًا مؤجلون ويقول: اللهم اغفر لأهل بقيع الغرقد، يدعو لهم فالسنة الدعاء لهم بما تقدم، وهذه الزيارة فيها خير عظيم، وفضل كبير: هو تذكير بالآخرة، وبالموت، لكن هذا خاص بالرجال. أما النساء فلا يزرن القبور، الرسول لعن زائرات القبور، هذا هو الصواب الذي عليه أهل الحق: أن المرأة لا تزور القبور، ولا تتبع الجنائز إلى القبور، ولكن تصلي على الميت لا بأس، تصلي على الميت في المصلى، أو في المسجد لا بأس، وقد صلت عائشة -رضي الله عنها- على سعد بن أبي وقاص لما توفي في آخر حياتها، رضي الله عنها. المقصود: أن الصلاة على الموتى مشروعة للرجال والنساء جميعًا، لكن زيارة القبور خاصة بالرجال، لا للنساء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14997/حكم-زيارة-المقابر-وما-يندب-عند-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753010.mp3","categories":["زيارة القبور"]},{"id":16314,"question":"يسأل ويقول: ما حكم زيارة الأضرحة، والتبرك عند الأضرحة؟","title":"حكم زيارة الأضرحة والتبرك بها","answer":"الجواب: الزيارة تقدم الكلام فيها، الأضرحة هي القبور، فالسنة الزيارة للدعاء لهم، والترحم عليهم، والاعتبار والذكرى، أما للتبرك فلا يجوز، هذا شرك، التبرك بهم، ودعاؤهم من دون الله شرك أكبر، كونه يتبرك بقبورهم، أو بترابهم، أو يستغيث بهم، أو ينذر لهم، أو يقول: يا سيدي فلان: اقض حاجتي، أو انصرني، أو اشف مريضي، أو أنا في جوارك، أو أنا أرجو بركتك .. أو ما أشبه ذلك، كل هذا من الشرك الأكبر عند أهل العلم. ولكن يزور القبور للذكرى، والدعاء، الدعاء لهم يعني، يدعو لهم: اللهم اغفر لهم، اللهم ارحمهم، يذكر الموت مثلما قال ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة وفي اللفظ الآخر تذكر الموت نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15001/حكم-زيارة-الاضرحة-والتبرك-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753011.mp3","categories":["زيارة القبور","التبرك وأنواعه"]},{"id":16376,"question":"لي أخت أكبر مني بكثير، وزوجها متوفى، وتذهب إلى زيارته في المقبرة، وبحكم أنها أكبر مني بكثير لا أستطيع أن أطلب منها عدم زيارة زوجها في المقبرة كما يقول الشرع، فما هو الحكم؟ أفادكم الله.","title":"الواجب على من له أخت تزور قبر زوجها","answer":"الجواب: الواجب عليك أن تبلغها الشرع، وأن تنصحها؛ لأن الدين النصيحة، والله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3].  فالنصيحة من التواصي بالحق، وهكذا قوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] النصيحة من التعاون على البر والتقوى، والنبي  يقول: الدين النصيحة، الدين النصيحة، الدين النصيحة قيل: لمن يا رسول الله؟ قال: لله، ولكتابه، ولرسوله، ولأئمة المسلمين وعامتهم تنصحها تقول: يا أختي! لا يجوز لك أن تزوري القبور، لا زوجك ولا غيره؛ لأن الرسول ﷺ لعن زائرات القبور تنصحها تقول لها: إن الزيارة للنساء لا تجوز للقبور، لا للزوج، ولا غير الزوج، بل ظاهر الأحاديث أنها من الكبائر؛ لأن اللعن... اللعن إنما يكون على الذنوب العظيمة، لكن تدعو له في بيتها، وفي أي مكان، تدعو له.. تترحم عليه.. تتصدق عنه، هذا طيب. أما أن تزور المقابر؛ لأجل زيارته؛ فهذا ممنوع، وعليك أن تنصحها، وتعلمها، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15074/الواجب-على-من-له-اخت-تزور-قبر-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75406.mp3","categories":["زيارة القبور"]},{"id":16683,"question":"هذا سؤال من السائلة من قضاء الشرقاط من العراق تقول: والدتي تذهب كل يوم خميس إلى قبر والدي، فهل يجوز هذا، أم لا ؟","title":"هل يجوز للمرأة أن تزور قبر زوجها؟","answer":"الجواب: الصحيح من أقوال العلماء أن الزيارة تختص بالرجال، وأن النساء لا يزرن القبور؛ لأنه ﷺ لعن زائرات القبور، كان أولًا نهى عن زيارة القبور مطلقًا للرجال والنساء، ثم رخص للجميع -عليه الصلاة والسلام- لما في زيارتها من ذكرى الآخرة، ولما في ذلك من الإحسان للموتى بالدعاء لهم، ثم استقرت الشريعة على منع النساء، وعلى شرعيتها للرجال، وقال -عليه الصلاة والسلام- زوروا القبور؛ فإنها تذكركم الآخرة وفي لفظ تذكركم الموت فالزيارة فيها مصالح من تذكير الآخرة، تذكير الموت، والزهد في الدنيا، والدعاء للأموات، والترحم عليهم، لكن هذا في حق الرجال. وأما النساء فلا يزرن القبور، هذا هو الصحيح، هذا هو الصواب، لا يزرن القبور للنهي الأخير، ولعنه ﷺ زائرات القبور؛ ولأن في زيارتهن خطرًا؛ لأنهن فتنة، وربما سبب ذلك فتنة للزوار من الرجال، وربما أيضًا سبب ذلك أيضًا فتنة لها هي لشدة جزعها، وقلة صبرها إلا من رحم الله. فالمقصود: أن الزيارة للقبور مختصة بالرجال دون النساء في أصح قولي العلماء، فلا ينبغي لأم السائلة أن تزور قبر أبيها، ولا غيره، بل تدعو له في بيتها، وفي كل مكان تدعو له بالمغفرة، والرحمة إذا كان مات على الإسلام والحمد لله يكفي، تدعو له بالمغفرة، والرحمة، تتصدق عنه، هذا كله طيب، أما أنها تزور قبره لا، لأن الرسول نهى النساء عن ذلك -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/15432/هل-يجوز-للمراة-ان-تزور-قبر-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_819/nour_81905.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":16761,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين لم ألاحظ أنه ذكر اسمه في هذه الرسالة، لكنه يسأل ويقول: ما حكم زيارة قبر الميت في المناسبات مثل الأعياد، وخاصة النساء؟","title":"حكم زيارة القبور في المناسبات","answer":"الجواب: الزيارة ليس لها حد محدود، زيارة القبور سنة في أي وقت، ليلًا، أو نهارًا، في أي وقت ليس لها حد محدود، لا في يوم عيد، ولا غيره متى تيسر؛ يزورها، متى تيسر للمؤمن الزيارة؛ زارها؛ لقول النبي ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون نسأل الله لنا ولكم العافية وفي اللفظ الآخر: يرحم الله المستقدمين منا، والمستأخرين وكان يدعو لهم بالمغفرة. فالسنة الزيارة، والدعاء لهم في أي وقت، ولكن النساء لا يزرن القبور، النساء يمنعن من زيارة القبور؛ لأن الرسول نهاهن عن زيارة القبور -عليه الصلاة والسلام- بل لعن زائرات القبور، فالزيارة للقبور إنما هي للرجال، هذا هو الصواب، هذا هو الراجح من أقوال العلماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15520/حكم-زيارة-القبور-في-المناسبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76209.mp3","categories":["زيارة القبور"]},{"id":16910,"question":"يسألون سماحتكم عن رأيكم في الانتقال من بلدٍ إلى بلد؛ لزيارة ضريح أحد الأولياء؟ ولو كانت المسافة قصيرة، ولتكن المسافة مثلًا: مائة كيلو مترًا، وليكن مثلًا هذا الولي: هو أحد الصحابة؟ جزاكم الله خيرًا.","title":"حكم شد الرحال إلى القبور والأضرحة","answer":"الجواب: السفر لزيارة القبور ما يجوز، لكن تزار، وبدون سفر، الإنسان يزور القبور في بلده، يسلم عليهم، يدعو لهم، إذا كانوا مسلمين، وإن كانوا كفارًا يزورهم للاعتبار، والعظة فقط، ولا يسلم عليهم؛ لأن النبي ﷺ قال: زوروا القبور؛ فإنها تذكركم الآخرة هكذا قال ﷺ زوروا القبور؛ فإنها تذكركم الآخرة رواه مسلم في صحيحه. وكان يعلم أصحابه -رضي الله عنهم- إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين، والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين وربما قال في بعض كلماته إذا زار القبور: أنتم لنا سلف، ونحن بكم لاحقون، غدًا مؤجلون، اللهم اغفر لأهل بقيع الغرقد وربما قال: السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، أنتم سلفنا، ونحن بالأثر. فالإنسان يسلم عليهم نحو هذا، نحو ما جاء عن النبي ﷺ، ويدعو لهم، لكن من دون شد رحل، إذا كانوا بعيدين لا يشد الرحل، يزور القبور التي في بلده، من دون شد رحل، وإذا سافر إلى بلد لأجل مصلحة، للتجارة، أو زيارة أخٍ له، وأحب أن يزور قبورها؛ لا بأس، إذا كان السفر ليس لأجلها، بل لأجل التجارة، أو زيارة قريبٍ حي، أو صديق، أو لأسبابٍ أخرى، وأحب أن يزور القبور، فهي سنة، الزيارة سنة، فيها عظة، فيها مصالح، تذكر الموت، تذكر الآخرة، كما قاله النبي ﷺ لكن ليس له أن يشد الرحل إليها، إذا كانت بعيدة؛ لقول النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى. فهذه المساجد الثلاثة هي التي تشد لها الرحال، للصلاة فيها، والعبادة، وللحج في المسجد الحرام، أما غيرها من المساجد، والبقاع، والقبور؛ فلا يشد لها الرحال، لا تشد الرحال إلى بقعة من البقاع، لا مقبرة، ولا صخرة، ولا الطور الذي كلم الله فيه موسى ، ولا غير ذلك، أبدًا، لا تشد الرحال لهذه الأشياء. ولما سافر أبو هريرة إلى الطور أنكر عليه بصرة بن أبي بصرة الغفاري، وقال: لو علمت لما سافرت؛ لأن النبي ﷺ قال: لا تعمل المطي إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى. فأنت يا عبدالله عليك أن تتبع السنة، ولا تخرج عنها، فتزور القبور في بلدك، ولا تشد الرحال إليها، في أي مكان، لا تسافر إليها، وهذا للرجال خاصة، أما النساء؛ فليس لهن الزيارة، لقوله ﷺ.. لأنه ﷺ لعن زائرات القبور فلا يزرن القبور، وإنما يزورها الرجال فقط، هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15686/حكم-شد-الرحال-الى-القبور-والاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82606.mp3","categories":["زيارة القبور"]},{"id":17533,"question":"هذا سائل للبرنامج يستفسر في سؤاله عن حكم زيارة القبور بالنسبة للنساء سماحة الشيخ؟","title":"حكم زيارة القبور للنساء","answer":"الجواب: زيارة القبور سنة للرجال ممنوعة للنساء؛ لأن الرسول ﷺ قال: زوروا القبور فإنها تذكركم الآخرة، وكان يزورها ﷺ، والصحابة يزورونها، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون نسأل الله لنا ولكم العافية، وربما قال: يرحم الله المستقدمين منا والمستأخرين، وربما قال: اللهم اغفر لأهل بقيع الغرقد، وربما قال: يغفر الله لنا ولكم أنتم سلفنا ونحن بالأثر. أما النساء فلا، الرسول لعن زائرات القبور عليه الصلاة والسلام، فلا يجوز لهن زيارة القبور، هذا الأمر الذي استقرت عليه السنة، كان ﷺ نهى الجميع عن الزيارة للقبور في أول الإسلام ثم أذن للجميع بعد ذلك ثم نهى النساء وأقر الرجال فاستقرت الشريعة: على أن الزيارة للقبور سنة للرجال ممنوعة في حق النساء. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16452/حكم-زيارة-القبور-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77508.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":17536,"question":"هل يعلم الأموات بزيارة الأحياء وأين مقر الأرواح؟","title":"هل يعلم الأموات بزيارة الأحياء؟","answer":"الجواب: ليس في هذا ما يدل على علمهم من أدلة شرعية، لكن السنة أن يزوروهم ويزوروا القبور، ويدعوا لهم، ويسلموا عليهم، لكن ورد في بعض الأحاديث: ما من رجل يسلم على رجل كان يعرفه في الدنيا إلا رد الله عليه روحه فرد عليه السلام رواه ابن عبد البر وقواه، ولكن في سنده نظر، والمهم أن يسلم عليهم ويدعو لهم سواء عرفوه أو ما عرفوه، الحمد لله، ليس هناك أحاديث فيما نعلم صحيحة ثابتة تدل على أنهم يعلمون الزائر ولكن السنة أن تزور القبور وتسلم على أهلها إذا كانوا مسلمين وتدعو لهم، وسواء عرفوك وإلا ما عرفوك المهم الزيارة، والفضل، والدعاء لهم، والأجر الذي يحصل لك. نعم.\nأما الكافر لا يزار قبره للدعاء لكن يزار للعظة، إذا زار قبر قريب له كافر لا يسلم، يزورهم ويمر عليهم من باب العظة، كما زار النبي ﷺ قبر أمه واستأذن ربه أن يدعو لها فلم يأذن له، فإذا زار قبر من مات في الجاهلية أو على الكفر ولكن لا يدعو له، لا بأس أن يزور للتذكر ولكن لا يدعو له ولا يسلم. نعم.\nالمقدم: أحسن الله إليكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/16462/هل-يعلم-الاموات-بزيارة-الاحياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77511.mp3","categories":["زيارة القبور"]},{"id":17986,"question":"أرجو أن توضحوا لي هل يجوز زيارة القبور ووضع الشواهد وأخذ جزء من التراب والمسح على الجسم؟","title":"حكم زيارة القبور والتبرك بترابها ووضع الشواهد","answer":"الجواب: أما زيارة القبور فسنة، الرسول عليه السلام قال: زوروا القبور فإنها تذكركم الآخرة كان الرسول ﷺ نهى عن زيارة القبور أولًا؛ لأن الناس كانوا أهل شرك وتعلق بالقبور فنهاهم عنها، فلما استقر الإسلام في قلوبهم وعرفوا دين الله رخص لهم في زيارة القبور وقال ﷺ: زوروا القبور فإنها تذكركم الآخرة.\nأما أخذ التراب منها للبركة أو التمسح بها أو دعاء أهلها أو الاستغاثة بهم هذا منكر هذا من الشرك، أما وضع الشواهد فهذا الشيء مجمل ما نعرف ما معنى وضع الشواهد، إذا كان المقصود أن يضع عليها أعواد كالجريد أو يغرس عليها شجر هذا لا ينبغي، وإنما فعله النبي ﷺ في قبرين معذبين ولم يفعله ﷺ مع القبور الأخرى، فدل على أنه لا يشرع وضع الجرايد على القبور ولا غرس الشجر.\nأما إن كان وضع الشواهد يعني: علامة على قبر أن هذا قبر فلان، حجر أو قطعة حديدة أو عظم أو شيء علامة على أنه قبر فلان فلا بأس، تعليم القبر بما يدل على صاحبه من غير كتابة لا بأس بذلك.\nأما التمسح بالتراب ووضعه على الجسم تبركًا بهم هذا لا يجوز، هذا من الشرك، وهكذا إذا طلبوا البركة منهم ...: يا صاحب القبر أعطني بركتك، أو أرجو بركتك، أو اغفر لي أو انصرني أو اشف مريضي، أو انصرنا على أعدائنا أو أغثنا أو اشفع لنا، هذا كله من الشرك لا يجوز هذا مع القبور، الشفاعة بيد الله جل وعلا: قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44]، ، يقول: قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44]، تقول: يا رب! شفع في نبيك، يا رب شفع في ملائكتك وأنبياءك، ...: يا رب شفع في عبادك المؤمنين، أما الميت لا تسأله شيئًا إنما تدعو له، تستغفر له، تترحم عليه، ولا تقل: انصرنا أو اشف مرضانا، أو اشفع لنا أو أنت تعلم ما في نفوسنا أو تعلم حاجاتنا، كل هذا من الشرك الأكبر نعوذ بالله. نعم.\nالمقدم: نسأل الله السلامة، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17016/حكم-زيارة-القبور-والتبرك-بترابها-ووضع-الشواهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84904.mp3","categories":["زيارة القبور","التبرك وأنواعه"]},{"id":17998,"question":"السائل علي محمد يقول في سؤاله: إن والدي قد توفي منذ عشر سنوات وأنا دائمًا أذهب إلى قبره وأسلم عليه وأدعو له أثناء زيارتي، ولكن قال لي شخص بأن الأموات لا يسمعون الأحياء، والسؤال يبقى: هل عندما أذهب لزيارة أبي المتوفى أسلم عليه .. هل يسمع كلامي ويرد علي السلام؟ أفيدوني مأجورين.","title":"حكم زيارة القبور والسلام على أهلها والدعاء لهم","answer":"الجواب: الزيارة مشروعة له الرسول ﷺ قال: زوروا القبور فإنها تذكركم بالآخرة فالسنة زيارة القبور، والسلام عليهم، والدعاء لهم، كان النبي ﷺ يزورها، ويعلم أصحابه أن يزوروها، فالسنة أن تزور القبور أن تسلم على أبيك، وتدعو له. أما كونه يسمع كلامك أو يعلم هذا الله أعلم، هذا إلى الله جل وعلا، ليس في هذا حديث صحيح يدل على أنه يسمع كلامك، أو أنه يعلم بزيارتك، لكن ينتفع بهذه الزيارة وينتفع بالدعاء، إذا دعوت له في البيت، أو في المسجد، أو عند الزيارة، أو في أي مكان، الدعاء نافع، فيه فائدة كبيرة، والصدقة عنه كذلك، والحج عنه، والعمرة عنه، والضحية عنه؛ كل هذا شيء نافع، يفيده، أما كونه يعلمك ويسمعك هذا إلى الله، الله الذي يعلمه . جاء في بعض الأحاديث التي في سندها ضعف أن الرسول ﷺ قال: ما من عبد يزور شخصًا كان يعرفه في الدنيا فيسلم عليه إلا رد الله عليه روحه حتى يرد عليه السلام لكن هذا في صحته نظر، .نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/17045/حكم-زيارة-القبور-والسلام-على-اهلها-والدعاء-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78104.mp3","categories":["زيارة القبور"]},{"id":18008,"question":"أرجو أن توضحوا لي هل يجوز زيارة القبور ووضع الشواهد وأخذ جزء من التراب والمسح على الجسم؟","title":"حكم زيارة القبور والتبرك بترابها ووضع الشواهد","answer":"الجواب: أما زيارة القبور فسنة، الرسول عليه السلام قال: زوروا القبور فإنها تذكركم الآخرة كان الرسول ﷺ نهى عن زيارة القبور أولًا؛ لأن الناس كانوا أهل شرك وتعلق بالقبور فنهاهم عنها، فلما استقر الإسلام في قلوبهم وعرفوا دين الله رخص لهم في زيارة القبور وقال ﷺ: زوروا القبور فإنها تذكركم الآخرة.\nأما أخذ التراب منها للبركة أو التمسح بها أو دعاء أهلها أو الاستغاثة بهم هذا منكر هذا من الشرك، أما وضع الشواهد فهذا الشيء مجمل ما نعرف ما معنى وضع الشواهد، إذا كان المقصود أن يضع عليها أعواد كالجريد أو يغرس عليها شجر هذا لا ينبغي، وإنما فعله النبي ﷺ في قبرين معذبين ولم يفعله ﷺ مع القبور الأخرى، فدل على أنه لا يشرع وضع الجرايد على القبور ولا غرس الشجر.\nأما إن كان وضع الشواهد يعني: علامة على قبر أن هذا قبر فلان، حجر أو قطعة حديدة أو عظم أو شيء علامة على أنه قبر فلان فلا بأس، تعليم القبر بما يدل على صاحبه من غير كتابة لا بأس بذلك.\nأما التمسح بالتراب ووضعه على الجسم تبركًا بهم هذا لا يجوز، هذا من الشرك، وهكذا إذا طلبوا البركة منهم ...: يا صاحب القبر أعطني بركتك، أو أرجو بركتك، أو اغفر لي أو انصرني أو اشف مريضي، أو انصرنا على أعدائنا أو أغثنا أو اشفع لنا، هذا كله من الشرك لا يجوز هذا مع القبور، الشفاعة بيد الله جل وعلا: قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44]، ، يقول: قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44]، تقول: يا رب! شفع في نبيك، يا رب شفع في ملائكتك وأنبياءك، ...: يا رب شفع في عبادك المؤمنين، أما الميت لا تسأله شيئًا إنما تدعو له، تستغفر له، تترحم عليه، ولا تقل: انصرنا أو اشف مرضانا، أو اشفع لنا أو أنت تعلم ما في نفوسنا أو تعلم حاجاتنا، كل هذا من الشرك الأكبر نعوذ بالله. نعم.\nالمقدم: نسأل الله السلامة، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17016/حكم-زيارة-القبور-والتبرك-بترابها-ووضع-الشواهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84904.mp3","categories":["زيارة القبور","التبرك وأنواعه"]},{"id":18101,"question":"هناك عادات تقضي بأن يذهب أهل الميت من رجال ونساء إلى قبره كل يوم خميس خلال الأسابيع الثلاثة الأولى بعد الوفاة، وذلك للتصدق بالفطائر والخبز، ما حكم الإسلام في ذلك؟أليس الأولى أن يتم التصدق على الفقراء والمحتاجين في أي مكان آخر دون الذهاب إلى المقابر، خاصة بعد أن ثبت أن معظم من يتواجدون بها من الأحياء يبيعون ما يجمعونه من أهل الموتى ويتاجرون فيه؟","title":"حكم زيارة المقابر للرجال والنساء واتخاذها محلًا للصدقة","answer":"الجواب: ليس لهذا أصل، ليس لتحديد الزيارة كل أسبوع أو الصدقة عند القبور أصل، بل الواجب أن تكون الزيارة غير محددة، متى تيسرت الزيارة شرع أن تزار القبور من الرجال، يزورها الرجال لذكر الآخرة، وذكر الموت، والدعاء للموتى، فيقول: السلام عليكم دار قومٍ مؤمنين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يغفر الله لنا ولكم. هكذا كان يعلم النبي أصحابه ﷺ. كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون نسأل الله لنا ولكم العافية. وكان ﷺ إذا زار القبور يقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، غداً مؤجلون، اللهم اغفر لأهل بقيع الغرقد. هكذا كان يفعل النبي ﷺ. ويقول: زوروا القبور فإنها تذكركم الآخرة، زوروا القبور فإنها تذكركم الموت. وهذا كله في حق الرجال. أما النساء فلا يزرن القبور كما تقدم، وأما تخصيص يوم معين، الخميس أو الجمعة للزيارة فلا أصل له، وهكذا تخصيص توزيع الصدقات من خبز أو لحوم أو غير ذلك عند القبور لا أصل له، بل المشروع أن صاحب الصدقة يتبع الفقراء في بيوتهم وفي محلاتهم، ويعطيهم الصدقة ولا يكلف عليهم ولا يدعوهم إلى المقابر. فالحاصل أن المشروع أن المؤمن يتبع الفقراء، ويعرف محلاتهم حتى يذهب إليهم بالصدقة، وإذا جاءوا إليه في بيته وطلبوه تصدق عليهم، أما يتخذ المقبرة محلاً صدقة فهذا لا أصل له. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17136/حكم-زيارة-المقابر-للرجال-والنساء-واتخاذها-محلا-للصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/%D8%AD%D9%83%D9%85%20%D8%B0%D9%87%D8%A7%D8%A8%20%D8%A3%D9%87%D9%84%20%D8%A7%D9%84%D9%85%D9%8A%D8%AA%20%D9%85%D9%86%20%D8%B1%D8%AC%D8%A7%D9%84%20%D9%88%D9%86%D8%B3%D8%A7%D8%A1%20%D8%A5%D9%84%D9%89%20%D9%82%D8%A8%D8%B1%D9%87%20%D9%83%D9%84%20%D9%8A%D9%88%D9%85%20%D8%AE%D9%85%D9%8A%D8%B3%20%D8%AE%D9%84%D8%A7%D9%84%20%D8%A7%D9%84%D8%A3%D8%B3%D8%A7%D8%A8%D9%8A%D8%B9%20%D8%A7%D9%84%D8%AB%D9%84%D8%A7%D8%AB%D8%A9%20%D8%A7%D9%84%D8%A3%D9%88%D9%84%D9%89%20%D9%85%D9%86%20%D8%A7%D9%84%D9%88%D9%81%D8%A7%D8%A9.mp3","categories":["زيارة القبور"]},{"id":18102,"question":"تسأل أختنا وتقول: ما حكم زيارة المقابر بالنسبة للمرأة، سواء في تلك الأسابيع أو في أي وقت آخر من العام؟","title":"ما حكم زيارة المقابر للنساء؟","answer":"الجواب: مثلما تقدم، لا يجوز لها أن تزور القبور مطلقًا لا في أول أسابيع الموت، ولا في غير ذلك؛ لأنه ﷺ لعن زائرات القبور فدل ذلك على أنهن لا يزرن القبور مطلقًا، لا حين الموت، ولا بعده بأسابيع، ولا بعده بأعوام. نعم.","link":"https://binbaz.org.sa/fatwas/17137/ما-حكم-زيارة-المقابر-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_904/nour_90402.mp3","categories":["زيارة القبور"]},{"id":18246,"question":"إذا زارت المرأة مدينة الرسول ﷺ فمرت بشهداء أحد، وأهل البقيع علمًا بأنها لم تدخل إلى القبور بل من خلف الشبك الموجود، وتردد الدعاء الوارد وعند زيارة القبور، هل يجوز لها ذلك؟","title":"حكم الدعاء عند المرور بجوار القبور للمرأة","answer":"الجواب: ظاهر الأحاديث المنع؛ لأنها ممنوعة من زيارة القبور، وهذا يشبه الزيارة، وهو وسيلة إلى الزيارة، فإذا مرت على القبور لا تسلم عليهم، لما جاء في الحديث أن الرسول ﷺ لعن زائرات القبور، فالاحتياط لها أن لا تسلم عليهم؛ لأنها قد تسمى زيارة، فالأفضل والأحوط أن لا تسلم عليهم وإن كان مرورًا، كما أنها لا يجوز لها أن تقصد الزيارة إنما هذا للرجال. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17295/حكم-الدعاء-عند-المرور-بجوار-القبور-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78302.mp3","categories":["زيارة القبور","الأدعية والأذكار"]},{"id":18490,"question":"من العراق رسالة بعثت بها إحدى الأخوات من هناك تقول أم داود تسأل وتقول: هل الشخص المتوفى يعرف بما يدور في بيت أهله؟ وكذلك يرى أهله عند زيارتهم له في المقبرة؟إنني والدة شهيد وأبكي كثيرًا وأزوره كل يوم خميس في المقبرة وأطعم الفقراء ولا أعرف قراءة القرآن؛ لأني لا أعرف القراءة، ولكن أقرأ سورة الفاتحة وبعض السور القصار، ولا أصلي وأريد أن أرى ابني في الحلم ولا أستطيع فماذا أفعل؟","title":"حكم القول بأن الميت يعلم من يزوره","answer":"الجواب: المشروع لك الدعاء له إذا كان مات مسلمًا -قتل مسلمًا- الدعاء له والترحم عليه والصدقة عنه، هذا ينفعه كثيرًا. أما الزيارة فليس لك الزيارة، الرسول ﷺ منع النساء من زيارة القبور وقال عليه الصلاة والسلام: زوروا القبور فإنها تذكركم الآخرة وأراد بذلك الرجال، أما النساء فقد ثبت عنه لعن زوارات القبور من النساء. فالواجب عليك ألا تزوريه في المقبرة، ولكن تدعين له في بيتك وفي كل مكان بالمغفرة والرحمة، وتتصدقين عنه إذا تيسر لك صدقة، وأنت على خير إن شاء الله، وأما الزيارة فلا. وعليك أيضًا أن تصلي، عليك أن تتقي الله وأن تصلي؛ فإن الصلاة عمود الإسلام، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر الصلاة عمود الإسلام وأمرها عظيم والله يقول فيها سبحانه في كتابه العظيم القرآن: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى(يعني: العصر) وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] ويقول سبحانه في كتابه العظيم: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]. فالواجب عليك أن تقيمي الصلاة في وقتها، الظهر أربعًا.. العصر أربعًا.. المغرب ثلاثًا.. العشاء أربعًا.. الفجر ثنتين، هذا الواجب عليك وعلى كل مسلم، ومن تركها كفر ولا حول ولا قوة إلا بالله. فالواجب عليك أن تتوبي إلى الله مما سلف، وأن تستقبلي زمانك بالصلاة والمحافظة على دين الله، وأن تسألي عما أشكل عليك من دينك أهل العلم، أو من طريق هذا البرنامج بالمكاتبة وسوف تجدين إن شاء الله في هذا البرنامج ما يكفي ويشفي. وأما كون أهل الميت كونه يطلع على أحوال أهله ويعلم أخبارهم هذا لا دليل عليه، قد قاله بعض الناس في بعض مرائيهم وزعموا أنهم يرون بعض موتاهم وأنهم يخبرونهم ببعض ما قد يقع ولكن هذا لا يعول عليه، المرائي المنامية لا يعول عليها في أشياء من علم الغيب، ولكن على المؤمن أن يحرص على الإحسان إلى أمواته سواء عرفوا أو ما عرفوا، عليه أن يحرص على الدعاء لهم والترحم عليهم وعلى الصدقة عنهم. وقد سئل النبي ﷺ عليه الصلاة والسلام قال له رجل: يا رسول الله! هل بقي من بري أبوي شيء أبرهما به بعد وفاتهما؟ قال:  نعم. الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما -يعني: وصاياهما الشرعية- وإكرام صديقهما وصلة الرحم التي لا توصل إلا بهما فالدعاء للميت والاستغفار له والترحم عليه والصدقة عنه كل هذا ينفعه في حياته وبعد مماته. أما كونهم يعلمون بالزائر فهذا أيضًا محل نظر، فقد جاء في بعض الأحاديث أنه ﷺ قال: ما من عبد يزور أخًا له كان يعرفه في الدنيا فيسلم عليه إلا عرفه ورد عليه السلام هكذا روى ابن عبد البر وابن أبي الدنيا بإسناد جيد عن النبي ﷺ أنه قال: ما من رجل يزور أخًا له كان يعرفه في الدنيا فيسلم عليه إلا عرفه ورد عليه السلام. فالحاصل أنه سواء عرفك أو ما عرفك سواء عرف الزائر أو ما عرف الزائر المهم أنه يزوره ويدعو له، النبي ﷺ قال: زوروا القبور فإنها تذكركم الآخرة فالمهم أنها تنفع الحي، وتعينه على ذكر الآخرة وذكر الموت حتى يستعد للقاء الله، وتنفع الميت من جهة أن الزائر يدعو له ويترحم عليه، ففي الزيارة للقبور مصالح للحي والميت جميعًا. يزورهم ويسلم عليهم ويدعو لهم ثم ينصرف، لا يتمسح بقبورهم ولا يصلي عند قبورهم، ولا يسأل الله بهم، ولكن يدعو لهم يقول: (اللهم اغفر لهم اللهم ارحمهم). كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي الحديث الآخر: يرحم الله المستقدمين منا والمستأخرين اللهم اغفر لأهل بقيع الغرقد يدعو لهم عليه الصلاة والسلام هكذا أمته تتأسى به، فتدعو للأموات، وتسأل الله لهم المغفرة والعافية، وهذا هو المشروع، ويكفي هذا للمؤمن أن يفعل ما شرعه الله وأن يقف عند الحد الشرعي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17590/حكم-القول-بان-الميت-يعلم-من-يزوره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_867/nour_86705.mp3","categories":["زيارة القبور","عذاب القبر ونعيمه "]},{"id":18643,"question":"تسأل أختنا أيضًا فتقول: ما حكم الشرع في زيارة القبور للنساء يوم الجمعة؟","title":"ما حكم زيارة القبور للنساء يوم الجمعة؟","answer":"الجواب: الزيارة للقبور مختصة بالرجال، فمن السنة للرجال أن يزوروا القبور؛ لقوله ﷺ: زوروا القبور، فإنها تذكركم الآخرة وليس لها حد في الليل أو في النهار.  أما النساء فلا يجوز لهن زيارة القبور؛ لأن الرسول ﷺ لعن زائرات القبور فلا يجوز لهن الزيارة، ولكن يدعون لموتاهم بالمغفرة والرحمة في بيوتهن، وفي كل مكان. أما الزيارة فتختص بالرجال، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17756/ما-حكم-زيارة-القبور-للنساء-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73502.mp3","categories":["زيارة القبور"]},{"id":18755,"question":"من ضمن أسئلة الأخ السائل يقول سماحة الشيخ: في المقبرة، وعند زيارة القبر للسلام على الميت، هل من المشروع أن يقف الإنسان متجهًا للقبلة والقبر أمامه، أم يكون ذلك متجهًا لجهة الشرق، حتى يكون مواجهًا لوجه الميت؟","title":"حكم التوجه للقبلة عند السلام على الميت وزيارته","answer":"الجواب: ليس في هذا تحديد، السنة أن يقف على القبر، ويسلم على الميت، سواء من خلفه أو أمامه، المهم أن يسلم عليه، وإذا أتاه من أمامه حتى يكون أمام وجه الميت فلا بأس، الأمر واسع في هذا، النبي  قال زوروا القبور؛ فإنها تذكركم الآخرة ولم يعين جهة معينة، سواء وقف من عند رأسه، أو عن يمينه، أو شماله أو خلفه، الأمر واسع والحمد لله، المهم أنه يزور القبور، ويسلم عليهم، وإذا خص بعض الناس كأبيه أو أخيه، وزاره وخصه، وسلم عليه فالأمر واسع بحمد الله، نعم.","link":"https://binbaz.org.sa/fatwas/17876/حكم-التوجه-للقبلة-عند-السلام-على-الميت-وزيارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79006.mp3","categories":["زيارة القبور"]},{"id":18875,"question":"من العراق، رسالة بعثت بها إحدى الأخوات من هناك تقول: أم داود تسأل وتقول: هل الشخص المتوفى يعرف بما يدور في بيت أهله، وكذلك يرى أهله عند زيارتهم له في المقبرة، إنني والدة شهيد، وأبكي كثيرًا، وأزوره كل يوم خميس في المقبرة، وأطعم الفقراء، ولا أعرف قراءة القرآن؛ لأني لا أعرف القراءة، ولكن أقرأ سورة الفاتحة وبعض السور القصار، ولا أصلي، وأريد أن أرى ابني في الحلم، ولا أستطيع، فماذا أفعل؟","title":"بعض الأحكام المتعلقة بزيارة القبور","answer":"الجواب:  المشروع لك الدعاء له إذا كان مات مسلمًا استشهد مسلمًا، الدعاء له، والترحم عليه، والصدقة عنه، هذا ينفعه كثيرًا، أما الزيارة فليس لك الزيارة، الرسول ﷺ منع النساء من زيارة القبور، وقال -عليه الصلاة والسلام-: زوروا القبور، فإنها تذكركم الآخرة وأراد بذلك الرجال. أما النساء فقد ثبت عنه: \"لعن زوارات القبور من النساء\" فالواجب عليك أن لا تزوريه في المقبرة، ولكن تدعين له في بيتك، وفي كل مكان بالمغفرة والرحمة، وتصدقين عنه إذا تيسر لك صدقة؛ وأنت على خير -إن شاء الله-. وأما الزيارة فلا، وعليك أيضًا أن تصلي، عليك أن تتقي الله، وأن تصلي، فإن الصلاة عمود الإسلام، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة؛ فمن تركها فقد كفر فالصلاة عمود الإسلام، وأمرها عظيم، والله يقول فيها سبحانه في كتابه العظيم القرآن: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] يعني: العصر وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238] ويقول سبحانه في كتابه العظيم: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]. فالواجب عليك أن تقيمي الصلاة في وقتها: الظهر أربعًا، العصر أربعًا، المغرب ثلاث، العشاء أربعًا، الفجر ثنتين، هذا الواجب عليك وعلى كل مسلم، ومن تركها كفر، ولا حول ولا قوة إلا بالله. فالواجب عليك أن تتوبي إلى الله مما سلف، وأن تستقبلي زمانك بالصلاة، والمحافظة على دين الله، وأن تسألي عما أشكل عليك من دينك أهل العلم، أو من طريق هذا البرنامج بالمكاتبة، وسوف تجدين -إن شاء الله- في هذا البرنامج ما يكفي ويشفي. وأما كون الميت يطلع على أحوال أهله، ويعلم أخبارهم، هذا لا دليل عليه، قد قاله بعض الناس في بعض مرائيهم، وزعموا أنهم يرون بعض موتاهم، وأنهم يخبرونهم ببعض ما قد يقع، ولكن هذا لا يعول عليه، المرائي المنامية لا يعول عليها في أشياء من علم الغيب، ولكن على المؤمن أن يحرص على الإحسان إلى أمواته، سواء عرفوا أو ما عرفوا، عليه أن يحرص على الدعاء لهم، والترحم عليهم، وعلى الصدقة عنهم، وقد سئل النبي -عليه الصلاة والسلام-: قال له رجل: يا رسول الله، هل بقي من بر أبوي شيء أبرهما به بعد وفاتهما؟ قال: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما -يعني: وصاياهما الشرعية- وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما. فالدعاء للميت، والاستغفار له، والترحم عليه، والصدقة عنه، كل هذا ينفعه في حياته وبعد مماته، أما كونهم يعلمون بالزائر، فهذا أيضًا محل نظر، فقد جاء في بعض الأحاديث أنه ﷺ قال: ما من عبد يزور أخًا له كان يعرفه في الدنيا، فيسلم عليه إلا عرفه ورد عليه السلام هكذا روى ابن عبد البر و ابن أبي الدنيا بإسناد جيد عن النبي ﷺ أنه قال: ما من رجل يزور أخًا له كان يعرفه في الدنيا فيسلم عليه؛ إلا عرفه ورد عليه السلام. فالحاصل: أنه سواء عرفك أو ما عرفك، سواء عرف الزائر أو ما عرف الزائر، المهم أنه يزوره، ويدعو له، النبي ﷺ قال: زوروا القبور؛ فإنها تذكركم الآخرة فالمهم أنها تنفع الحي تعينه على ذكر الآخرة، وذكر الموت؛ حتى يستعد للقاء الله، وتنفع الميت من جهة أن الزائر يدعو له، ويترحم عليه. ففي الزيارة للقبور مصالح للحي والميت جميعًا، يزورهم، ويسلم عليهم، ويدعو لهم، ثم ينصرف، لا يتمسح بقبورهم، ولا يصلي عند قبورهم، ولا يسأل الله بهم، ولكن يدعو لهم يقول: اللهم اغفر لهم، اللهم ارحمهم، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي الحديث الآخر: يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد يدعو لهم -عليه الصلاة والسلام-، هكذا أمته تتأسى به، فتدعو للأموات، وتسأل الله لهم المغفرة والعافية، وهذا هو المشروع، ويكفي هذا للمؤمن أن يفعل ما شرعه الله، وأن يقف عند الحد الشرعي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18026/بعض-الاحكام-المتعلقة-بزيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88005.mp3","categories":["زيارة القبور"]},{"id":19082,"question":"أولى رسائل هذه الحلقة رسالة المستمع من حضرموت: (م. هـ. ع. ق) أخونا عرضنا له سؤال في حلقة مضت، وفي هذه الحلقة بقي له سؤال على منوال السؤال الأول في الطول والموضوع.يقول: تقام زيارة لقبر أحد الأولياء كما يزعم العامة -والله أعلم- واسمه علي بن محمد الحبشي وتسمى هذه الزيارة بزيارة الحول، ويمكثون على قبره الموجود تحت قبة إحدى عشرة ليلة، يصلون على المقابر حيث الإمام داخل المقبرة المحيطة بالقبة، ويمتد الجمع وخاصة المغرب والعشاء إلى مساحة خارج المقبرة، ويأمر الإمام من يصلي على المقبرة بفرش ردائه، وفي اليوم الثامن يجتمع الناس من الرجال والنساء حيث الاختلاط وانتهاك الأعراض حاملين ثوبًا على النعش من بيت أهل الولي إلى تابوت قبر الولي بالقبة بالطبول والأناشيد، ثم يلبسون ذلك التابوت، مع العلم بأن التابوت مرتفع بقدر متر تقريبًا، ويتمسحون بالثوب والتابوت والقبة سائلين الولي قائلين: يا علي يا علي بما يسأل الله به.وفي اليوم العاشر تكون الوقفة تشبهًا بالحج، يقفون في ذلك المكان وتلقى الكلمات عن ذلك الولي وكراماته، وإذا نصحنا بعدم فعل ذلك وأنه من البدع والشرك، قالوا: أنتم أهل البدع الخارجين عن اتباع السلف، وأنتم تكرهون الأولياء، ما رأي الشرع في ذلك؟ وبم تنصحون هؤلاء؟ جزاكم الله خيرًا، ومتع بوجودكم.","title":"زيارة القبور بين المشروع والممنوع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فينبغي أن يعلم أن شد الرحال للقبور من المنكرات التي نهى عنها النبي عليه الصلاة والسلام؛ فالرحال لا تشد إلا إلى ثلاثة مساجد: المسجد الحرام، والمسجد النبوي، وبيت المقدس، هذه هي المساجد الثلاثة التي يشد لها الرحال، كما قاله النبي عليه الصلاة والسلام، يقول ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى. ثم الذهاب إلى من يسمونهم بالأولياء للجلوس عند قبورهم، وطلب المدد منهم أو الشفاء أو النصر على الأعداء كل هذا من الشرك الأكبر؛ لأنه لا يجوز سؤال المخلوق، سواء سمي ولي أو ما سمي ولي، لا يجوز سؤاله، ولا طلب شفاء المرضى منه ولا طلب المدد؛ لأن هذا إلى الله سبحانه ليس إلى الأولياء ولا إلى الرسل. ولا يطلب منهم مثل هذا الطلب، ولا يتمسح بقبورهم ولا التبرك بها، ولو سموا أولياء، ولو كانوا صالحين، ولو كانوا أنبياء، لا يجوز هذا في القبور، وهذا هو عمل المشركين الأولين وعمل أهل الجاهلية مع القبور. فالواجب على أهل الإسلام الحذر من هذه الأمور وأن لا يفعلوها، وأن ينكروها على من فعلها من العامة، وأن لا يغتروا بما درج عليه الأسلاف والآباء من الشرك الأكبر، فالبناء على القبور واتخاذ القباب عليها منكر لا يجوز، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وكان عليه الصلاة والسلام يأمر بتسوية القبر إذا رفع يأمر بتسويته، قال عليه الصلاة والسلام لـعلي : لا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته معنى (سويته): أي: نقضته وهدمته حتى يستوي بالأرض ما يبقى إلا علامة القبر قدر شبر ونحوه. هكذا شرع الله القبور أن ترفع قدر شبر من الأرض حتى يعرف أنها قبور لا توطأ ولا تمتهن، ولا يبنى عليها لا قبة ولا مسجد ولا غير ذلك. يقول جابر بن عبد الله الأنصاري : «نهى رسول الله ﷺ عن تجصيص القبور، وعن القعود عليها، وعن البناء عليها» فلا فرق بين قبر ولي أو نبي أو غيرهما. ولا يجوز لأحد أن يتبرك بالقبور، أو يتخذها أعيادًا، أو يسألها شفاء المرضى أو المدد والعون، أو النصر على الأعداء، أو البركة في الأولاد أو في الطعام أو ما أشبه ذلك كل هذا لا يجوز. وهذه الإقامة عند قبر هذا الشخص منكرة وبدعة ومن أسباب الشرك، سواء كان إحدى عشر يومًا أو أقل أو أكثر، إنما المشروع للمسلم أن يزور القبور ويسلم عليهم ويدعو لهم وينصرف، إذا كانوا مسلمين يزورهم للسلام عليهم والدعاء لهم، ما هو طلب الدعاء من .. دعاؤهم من دون الله لا، الدعاء لهم بالمغفرة والرحمة، هم محتاجين للدعاء، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية وكان إذا زار القبور عليه الصلاة والسلام يقول: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون، غدًا مؤجلون، وأتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد، وروي عنه ﷺ أنه زار قبور المدينة فأقبل عليهم بوجهه فقال: السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر. هكذا الزيارة الشرعية، سلام على المقبورين ودعاء لهم بالمغفرة والرحمة والعافية، أما أن يدعون مع الله، يقول: اشفعوا لنا، انصرونا، المدد المدد، هذا منكر هذا لا يجوز، هذا الشرك الذي فعله قريش فعلته قريش وغيرها. فالواجب على المسلم الانتباه واليقظة والحذر من أعمال الشرك. ثم النساء لا يزرن القبور، الرسول ﷺ نهى عن زيارة القبور للنساء، ولعن زائرات القبور من النساء، إنما الزيارة للرجال للقبور خاصة، يزورونها ويدعون لأهلها بالمغفرة والرحمة، أما النساء فلا يزرن القبور، والحكمة من ذلك والله أعلم لأنهن قد يفتن أو يفتن ولقلة صبرهن أيضًا. فمن رحمة الله أن نهاهن عن زيارة القبور، ويكفي أن يدعون لأمواتهم في بيوتهم، يدعون للأموات .. يترحمون عليهم وهم في البيوت، لا حاجة إلى زيارة القبور، إنما الزيارة للرجال، ولهذا في الحديث الصحيح: \"لعن رسول الله زائرات القبور\" فلا يجوز للنساء أن يذهبن إلى القبور، ولا يجوز للرجال أن يتوجهوا إلى القبور لقصد التبرك بالمقبورين، أو دعائهم، أو الاستغاثة بهم، أو طلبهم المدد، أو الصلاة عند قبورهم لا هذا منكر، بل هو من المحرمات الشركية، والصلاة عند القبور بدعة، وإذا كان يصلي للميت ويطلبه من دون الله صار شركًا أكبر نسأل الله العافية. فالواجب على أهل الإسلام الحذر من هذه الأمور الشركية، ومن هذه البدع التي أحدثها الجهال الذين ما فهموا الشريعة ولا فقهوا فيها، ونسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا. سماحة الشيخ من خلال ما عرض على سماحتكم من الرسائل التي تصل إلى هذا البرنامج، ظهر ظهورًا واضحًا أن عالمنا الإسلامي مليء بأشياء وأشياء مخالفة للدين، من ذلك هذا التصوف ومن ذلك هذا التبرك بالقبور، وبما يسمونهم بالأولياء وما أشبه ذلك، يبدو أن الأمر يحتاج إلى محمد بن عبد الوهاب من جديد. الشيخ: لا شك أن هذا الأمر يحتاج إلى المصلحين، يحتاج إلى دعاة الهدى، الذين يتصدون لهذه الأمور بالدعوة إلى الله، وتبصير الناس وتوجيههم، وإلى أئمة وقادة يزجرونهم عن الباطل بالقوة، ويأخذون على أيدي السفهاء، ويلزمونهم بالحق كما قام رسول الله ﷺ بذلك في هجرته ﷺ وفي مكة عليه الصلاة والسلام، وهكذا قام خلفاؤه الراشدون، وهكذا دعاة الإصلاح في كل زمان ومنهم شيخ الإسلام ابن تيمية رحمه الله في زمانه، و ابن القيم في زمانه، وأشباههم من دعاة الهدى. ثم جاء دور الشيخ: محمد بن عبد الوهاب رحمه الله في القرن الثاني عشر فقام بهذا الواجب ودعا إلى الله، وأرشد الناس إلى توحيد الله، وأنكر الشرك الذي يوجد في نجد ثم في الحجاز، أنكر ذلك ودعا إلى الحق، وهكذا أنصاره من العلماء والأخيار ومن دعاة الهدى في نجد والحجاز وفي اليمن قاموا بهذا الواجب ونصروا الحق، ودعوا إلى الله  وأرشدوا الناس إلى توحيد الله، وحذروهم من عبادة القبور والأشجار والأحجار والجن، وهكذا كل مصلح يجب عليه أن يفعل هذا العمل بالدعوة إلى الله والتوجيه، وبالجهاد الشرعي والقوة التي تردع المجرم إذا لم يرتدع بالكلام والدعوة، فإنه يحتاج إلى الردع بالقوة بالتأديب بالسجن بقتل المرتد إلى غير ذلك مما قام به نبينا ﷺ وقام به خلفاؤه الراشدون والأئمة بعدهم المهديون والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا. شيخ عبد العزيز الكثير والكثير من المفكرين يثنون على المؤتمرات ويقولون: إنها تكون الرأي العام لدى الأمة، ما رأيكم لو عقد مؤتمرات همها التوحيد، الدعوة إلى توحيد الله. الشيخ: هذا من أهم المهمات الدعوة إلى توحيد الله هي أهم المهمات، والتوحيد هو أصل الدين وأساس الملة، فلو عقد مؤتمرات بين وقت وآخر في بلاد المسلمين بين علماء الحق لإيضاح هذه الأمور وبيانها للناس لكان هذا من أهم المهمات ومن أفضل القربات، ويكون المقصود الأول من عقد المؤتمر بيان حقيقة التوحيد، بيان معنى: لا إله إلا الله، بيان ما بعث الله به الرسل عليهم الصلاة والسلام من تحقيق التوحيد وإنكار الشرك، حتى يفهمه الناس، وحتى يعقله الناس الذين جهلوه في بلاد المسلمين وفي غيرها. هذا ينبغي أن يسعى فيه، وأن تبذل فيه الجهود؛ لأن فيه مصالح عظيمة وأي مصلحة أعظم من مصلحة التوحيد، الذي هو أصل الدين وأساس الملة، نسأل الله أن يعين على ذلك، ونسأل الله أن يمن بذلك، ولعلنا نستطيع شيئًا من ذلك في هذا الموضوع إن شاء الله، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا. كدت أقول: لماذا الشيخ عبد العزيز بن باز لا يتبنى هذه الفكرة. الشيخ: هذا من المهمات نسأل الله أن يعين على ذلك، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وتقبل منكم.","link":"https://binbaz.org.sa/fatwas/18247/زيارة-القبور-بين-المشروع-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93001.mp3","categories":["زيارة القبور"]},{"id":19328,"question":"أخ لنا يقول: المرسل ولدكم المعذب -كما يصف نفسه - عبد الله بن علي المعيطب من الرياض: والدي سماحة الشيخ عبد العزيز أفتوني عن أمر ضاق به صدري، وحالتي الصحية تأثرت به كثيرًا، إنني عصيت والدي كثيرًا وفي يوم من الأيام حصلت لي قضية، وقام والدي بالمتابعة لها، وأثناء هذا حدثت له حادثة سيارة وتعذب كثيرًا في المستشفى، ثم توفي وهو غير راض عني، وفي بعض الأوقات يقول أهلي: إنني أنا الذي قتلته، وأنا الذي تسببت في هذا الحادث، وهذه الكلمات تجرح قلبي، وفي بعض الأوقات أفكر - كما يقول شيخ عبدالعزيز - في الانتحار بسبب تلكم الكلمات، أنا الآن أدعو لوالدي، وأقرأ له القرآن إلا أن حالتي الصحية في تأثر، كيف أكفر عما فعلت تجاه والدي، وبماذا تنصحونني وتنصحون أهلي؟ جزاكم الله خيرًا.","title":"كيفية التوبة من عقوق الوالد بعد وفاته","answer":"الجواب:  أما أنت فننصحك بأن تلزم التوبة النصوح التي تشتمل على الندم على ما فعلت مع والدك من الإساءة، والعزم الصادق أنك لا تعود إلى أمثال ذلك من العقوق والقطيعة، وعليك مع ذلك أن تتبع هذا بالعمل الصالح كما قال الله  في كتابه العظيم : إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70]، قال سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]. فنصيحتي لك أن تلزم التوبة والندم على ما مضى منك، وتكثر الاستغفار والعمل الصالح من صلاة وصدقات وغير ذلك، وتسبيح وتهليل وتحميد وتكبير، وتكثر من قراءة القرآن وغير هذا من العمل الصالح، مع الدعاء لوالدك بالمغفرة والرحمة ورفيع الدرجة في الجنة، وتتصدق عنه بما تستطيع. الصدقات تنفع والدك، أما قراءة القرآن عنه فليس عليها دليل؛ وإن قال بها جمع من أهل العلم، لكن الأفضل أن تجعل بدل القراءة له الدعاء؛ لأنه لم يرد دليل واضح على أنه يقرأ عن الأموات، وإنما الدعاء هو المشروع، الدعاء له، والصدقة عنه، والحج عنه، والعمرة عنه، كل هذا أمر ينفعه، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له، كن أنت ولدًا صالحًا، وأكثر من الدعاء والاستغفار لأبيك مع توبتك الصادقة عما جرى منك سابقًا وأبشر بالخير، والتوبة تجب ما قبلها والحمد لله، وإياك والوساوس، وإياك وطاعة من يقول لك: إنك فعلت وإنك فعلت.. التوبة تهدم ما كان قبلها، وتجب ما قبلها الحمد لله، أعظم من العقوق الشرك، وإذا تاب المشرك تاب الله عليه؛ فالعقوق دون الشرك، فالتوبة تجب ما قبلها. ونصيحتي لأهلك أن يتقوا الله فيك، وأن لا يتعرضوا لهذا الأمر وأن يبشروك بالخير؛ لأنك تبت والتوبة تجب ما قبلها فلا يجوز لهم أبدًا أن يذكروك بما جرى منك مما يضرك، ويسبب ضيق صدرك وتحرجك، بل ينبغي لهم أن يسلوك عن هذا، وأن يقولوا لك: احمد لله لما تاب عليك، وليس لك في هذا الحادث ما يوجب تأثرك، فالأمر بيد الله  هو الذي قضى ما قضى، ويرجى له الخير، ولعله يكون شهيداً بسبب الحادث. فالحاصل أن الواجب عليك التوبة فقط ولزومها، ويشرع لك الدعاء لأبيك والإكثار من ذلك، والصدقة كما تقدم إذا تيسرت ولو بالقليل، والحج إذا تيسر عن والدك والعمرة كذلك، كل هذا طيب. وأبشر بالخير وإياك وسوء الظن بالله وإياك وسوء الظن بالله من تاب أفلح من تاب أفلح، يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، والرسول عليه الصلاة والسلام يقول: التوبة تهدم ما كان قبلها، ويقول: التائب من الذنب كمن لا ذنب له، فاتق الله وأحسن الظن بمولاك واستقم على طاعته جل وعلا ولا تلتفت إلى من يلومك أو يقول لك بعد هذا فهم مخطئون وغالطون في كونهم يؤذونك وقد تبت إلى الله، بل الواجب عليهم أن يبشروك، وأن يفرحوك، وأن يعينوك على الفرح وحسن الظن بالله فالتائب لا يؤذى، التائب يبشر ويعان. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18534/كيفية-التوبة-من-عقوق-الوالد-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_896/nour_89603.mp3","categories":["إهداء القرب للميت","زيارة القبور","الحكم على الأحاديث","بر الوالدين"]},{"id":19405,"question":"له سؤال آخر عن أولئك الذين يزورون القباب وقبور بعض الصالحين كما يسميهم، ما هو توجيهكم شيخ عبد العزيز ؟","title":"حكم زيارة القباب والقبور","answer":"الجواب: يعلمون الزيارة الشرعية، يعلمون زيارة القبور الزيارة الشرعية، كان النبي ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية. وفي حديث آخر قال: السلام عليكم دار قوم مؤمنين، وإنا إن شاء الله بكم لاحقون غدًا مؤجلون وأتاكم ما توعدون، اللهم اغفر لأهل بقيع الغرقد، وفي حديث آخر قال عليه الصلاة والسلام: يرحم الله المستقدمين منا والمستأخرين، يغفر الله لنا ولكم، أنتم سلفنا ونحن بالأثر هذا وأشباهه يدعى به للموتى.\nأما وضع القباب على القبور أو المساجد هذا لا يجوز، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ويقول ﷺ لـعلي : لا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته وصح عنه عليه الصلاة والسلام من حديث جابر عند مسلم في صحيحه: أنه نهى عليه الصلاة والسلام عن تجصيص القبور، والقعود عليها، والبناء عليها فالقبور لا يبنى عليها بنص النبي عليه الصلاة والسلام، ولا يتخذ عليها مساجد ولا قباب، ولا تجصص ولا يقعد عليها فتمتهن، كل هذا ممنوع، ولا تكسى بالستور كل هذا ممنوع، وإنما يرفع القبر عن الأرض قدر شبر تقريبًا ليعرف أنه قبر حتى لا يمتهن ولا يوطأ. فالمؤمن يبلغ إخوانه ويعلمهم وهكذا طالب العلم، وهكذا العلماء يعلمون الناس ما شرعه الله، والمؤمن يتعلم من العلماء ويعلم من يأتي القبور، يقول لهم: إن الزيارة الشرعية كذا وكذا، أما البناء على القبور أو سؤال الميت أو التبرك بتراب القبر أو تقبيل القبر أو الصلاة عنده كل هذه من البدع، لا يصلى عند القبور، ولا تتخذ محلًا للدعاء تقصد للدعاء عندها ولا القراءة عندها، كل هذا من البدع.\nكذلك طلب البركة منها أو الشفاعة منها أو الشفاء هذا من أنواع الشرك الأكبر، إذا قال: يا سيدي فلان! اشفع لي إلى الله، ويقول للميت: انصرني أو اشف مريضي، هذا لا يجوز؛ لأن الميت انقطع عمله بعد موته إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. أما أنه يطلب منه شفاء المرضى أو النصر على الأعداء أو الشفاعة إلى الله في كذا هذا قد انقطع، لا يجوز طلبهم، بل يطلب من الله  اللهم اشفني .. اللهم أعطني كذا .. اللهم شفع في أنبياءك .. اللهم شفع في نبيك محمد ﷺ .. اللهم شفع في أفراطي، اللهم شفع في الملائكة والمؤمنين، هذا لا بأس به تطلب من الله جل وعلا. فالخلاصة أن المسلمين ينصح بعضهم بعضًا، ويعلم بعضهم بعضًا بأمر الشرع، والعلماء عليهم بيان ذلك وتوجيه العامة لما شرع الله  ومن ذلك أن يعلموا الزيارة الشرعية للقبور التي جاءت في الأحاديث عن رسول الله عليه الصلاة والسلام والتي تقدم بيانها. ويعلمون أنه لا يجوز البناء على القبور لا قباب ولا مساجد ولا أبنية أخرى، ولا تجصص ولا يقعد عليها، ولا تتخذ محلًا للدعاء عندها، أو الصلاة عندها، أو القراءة عندها، هذه من البدع التي هي من وسائل الشرك، الصلاة عندها والقعود عندها للدعاء أو القراءة هذا من وسائل الشرك من البدع، أما دعاء الميت والاستغاثة بالميت والنذر له والذبح له، هذا من الشرك الأكبر نعوذ بالله، من عمل الجاهلية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18631/حكم-زيارة-القباب-والقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93602.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]},{"id":19463,"question":"من أسئلة هذه السائلة تقول: هل يجوز لي أن أزور القبور، أي: أن أزور أخي رحمه الله، فأنا منذ أن توفي أخي أذهب دائمًا لزيارته وأقدم البخور وأبقى عنده فترة، وأترحم عليه، وأدعو له دائمًا بدخول الجنة، هل هذا جائز؟","title":"هل يجوز للمرأة أن تزور القبور؟","answer":"الجواب: هذا لا يجوز، الرسول ﷺ لعن زائرات القبور، والنساء لا يزرن القبور، وهكذا الذهاب بالطيب إلى القبور كل هذا منكر، ولكن ادعي له في البيت، ادعي له في بيتك في سجودك، وترحمي عليه وتصدقي عنه. أما زيارة القبور لا، النساء لا يزرن القبور، وعليك التوبة مما سلف، عليك التوبة مما فعلتيه سابقًا، والدعاء له في البيت الحمد لله. المقدم: أحسن الله إليكم، وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18712/هل-يجوز-للمراة-ان-تزور-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93906.mp3","categories":["زيارة القبور"]},{"id":19525,"question":"السائلة أختكم في الله (ح. ص) من القصيم بريدة تقول: كيف نوفق بين حديث: لعن رسول الله ﷺ زائرات القبور وبين ما ذكر عن عائشة رضي الله عنها بأنها كانت تدخل على قبر رسول الله ﷺ وصاحبيه، وأيضًا ما ذكر عنه ﷺ بأنه مر بامرأة عند قبر تبكي فأمرها بالصبر، ولم ينكر عليها؟","title":"القول الراجح في حكم زيارة النساء للقبور","answer":"الجواب: كانت الزيارة مشروعة للجميع، ثم نسخ الله زيارة النساء، فما جاء فيما يتعلق بزيارة النساء كان في الأمر الأول، ثم جاءت الشريعة بنسخ زيارة النساء، ولعن النساء على الزيارة، فاستقرت الشريعة على أن الزيارة للقبور تكون للرجال خاصة، والنساء لا يزرن لضعفهن، وقلة صبرهن، هذا آخر ما استقرت عليه الشريعة، وكان في الأول الزيارة ممنوعة للجميع، ثم أذن الله فيها للجميع، ثم نسخت الزيارة للنساء، ومنعن، وبقيت الزيارة للرجال. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18774/القول-الراجح-في-حكم-زيارة-النساء-للقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94617.mp3","categories":["زيارة القبور","قضايا المرأة"]},{"id":19665,"question":"تقول في آخر أسئلتها السائلة من اليمن: هناك قبور تزار من قبل بعض الناس، فهل يجوز لهم ذلك، حيث أنهم يذبحون عندها؟ وهل يجوز أن يأكلوا اللحم عند هذه القبور؟","title":"حكم الذبح والدعاء والقراءة عند القبور","answer":"الجواب: الذبح عند القبور لا يجوز، ولا الجلوس عندها للقراءة والدعاء، بل يجب الحذر من ذلك، بل هذا من وسائل الشرك، وإذا ذبح يتقرب إلى أصحاب القبور أو دعاهم أو استغاث بهم أو نذر لهم هذا شرك أكبر، هذا شرك أكبر نعوذ بالله. أما زيارة القبور للسلام عليهم والدعاء لهم لا بأس سنة، يقول النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة فإذا زارها المؤمن ليدعو لهم ويسلم عليهم ويستغفر لهم فلا بأس، أما أن يزورهم للذبح عندهم أو للقراءة عندهم أو للدعاء عند قبورهم هذا منكر لا يجوز ومن وسائل الشرك، فإذا ذبح لهم أو دعاهم أو استغاث بهم أو نذر لهم فقد صار هذا شركًا أكبر نعوذ بالله. أما النساء فلا يزرن القبور، يدعون لأمواتهم وهن في البيوت، لا حاجة إلى زيارة القبور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18954/حكم-الذبح-والدعاء-والقراءة-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95018.mp3","categories":["نواقض الإسلام","البدع والمحدثات","زيارة القبور"]}]
